-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 08/18/2020
-- Description:	Add Order Tracking time/job
-- =============================================
ALTER PROCEDURE [dbo].[p_Add_OT]
	@OrderNunber varchar(15),
	@JobID Int,
	@OrderTypeID Int,
	@StartTime datetime,
	@EmployeeIds varchar(100) -- Comma seperated string
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE 
		@SalesNum int = -1,
		@TrackID int = 0,
		@TimeID int = 0

	DECLARE @TrackIDs TABLE(ID INT);
	DECLARE @TimeIDs TABLE(ID INT);

	IF (@OrderNunber is NOT null) 
	BEGIN
		-- First: Create the Tracking Entry for an Order/Job 
		INSERT INTO [dbo].[OT] (
			[OrderNumber]
			,[JobID]
			,[OrderTypeID]
		)
		OUTPUT inserted.TrackID INTO @TrackIDs(ID)
		VALUES (
			@OrderNunber,
			@JobID,
			@OrderTypeID
		)

		-- GET the TrackID, we NEED it
		SELECT TOP(1) @TrackID = ID
		FROM @TrackIDs

		-- Second: Create the Time Entry
		INSERT INTO [dbo].[OT_Times] (
			[StartTime]
			,[Start_StatusId]
			,[TrackId]
		)
		OUTPUT inserted.TimeId INTO @TimeIDs(ID)
		VALUES (
			ISNULL(@StartTime, GETDATE()),
			1,
			@TrackID
		)

		-- GET the TimeID, we NEED it
		SELECT TOP(1) @TimeID = ID
		FROM @TimeIDs

		-- Third: Create the Employee(s) Time Entry(ies)
		DECLARE @separator NCHAR(1),
			@stringParse varchar(101)
		SET @separator=','
		DECLARE @position int
		SET @position = 1
		SET @stringParse = @EmployeeIds + @separator -- Adds seperator to end

		WHILE charindex(@separator,@stringParse,@position) <> 0
		BEGIN
			DECLARE @employee int
			SET @employee = substring(@stringParse, @position, charindex(@separator,@stringParse,@position) - @position)
				
			INSERT INTO [dbo].[OT_Times_Employees] (
				[EmployeeId]
				,[TimeId]
				,[TrackId]
			)
			VALUES (
				@employee,
				@TimeID,
				@TrackID
			)

			SET @position = charindex(@separator,@stringParse,@position) + 1
		END
	END

	SELECT @TrackID
END
GO
