ALTER PROCEDURE [dbo].[p_AllQuotes_AddPO]
	@BuyFrom	VarChar(15),
	@PO			INT,
	@SOitem		VARCHAR(10)
AS

--EXEC dbo.p_AllQuotes_AddPO 'BuyFrom',PO,'SOitem'

--fill the AllQuotes fields, HPAPO and HPAPO2

Set NoCount On

DECLARE @pSOitem	CHAR(10)
SET @pSOitem = dbo.f_ProperSOitem( @SOitem )

DECLARE @cnt AS INT
SET @cnt = 0
SELECT @cnt = COUNT(*) FROM dbo.AllQuotes WHERE SOitem = @pSOitem

IF @cnt > 0
	BEGIN
	
	--If the SOitem is Found in HPApo
	SELECT @cnt = COUNT(*) FROM dbo.AllQuotes 
		WHERE SOitem = @pSOitem 
		AND BuyFrom = @BuyFrom
		AND HPApo = @PO
	IF @cnt = 1
		GOTO DONE
		--Found PO with the SOitem 
	
	--check HPApo2
	SET @cnt = 0
	SELECT @cnt = COUNT(*) FROM dbo.AllQuotes 
		WHERE SOitem = @pSOitem 
		AND BuyFrom2 = @BuyFrom
		AND HPApo2 = @PO
	IF @cnt = 1
		GOTO DONE
		--Found PO with the SOitem 
	
	SET @cnt = 0	
	--Get HPAPO and HPAPO2
	DECLARE @HPAPO INT = 0
	DECLARE @HPAPO2 INT = 0
	
	SELECT @HPAPO=ISNULL(HPAPO,0), @HPAPO2=ISNULL(HPApo2,0) FROM dbo.AllQuotes 
		WHERE SOitem = @pSOitem 
		
	IF @HPAPO = @PO OR @HPAPO2 = @PO	
		begin
			--found PO, Did Name Change?
			IF @HPAPO = @PO
				UPDATE dbo.AllQuotes SET BuyFrom = @BuyFrom WHERE SOitem = @pSOitem
				
			IF @HPAPO2 = @PO
				UPDATE dbo.AllQuotes SET BuyFrom2 = @BuyFrom WHERE SOitem = @pSOitem
				
			GOTO DONE
		end
		--Found PO with that SOitem 
		
	--Did not find PO being used!
	--Is there an empty PO spot to use?
	IF @HPAPO = 0
		BEGIN
		UPDATE dbo.AllQuotes SET HPAPO=@PO, BuyFrom = @BuyFrom WHERE SOitem = @pSOitem
		GOTO DONE
		END
	ELSE
		IF @HPAPO2 = 0
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO2=@PO, BuyFrom2 = @BuyFrom WHERE SOitem = @pSOitem
			GOTO DONE
			END
			
	--No empty PO spots to Add PO
	--Value the PO's		
	DECLARE @nPOv		TinyInt = 0
	DECLARE @nHPAPOv	TinyInt = 0
	DECLARE @nHPAPO2v	TinyInt = 0
	
	
	SELECT @nPOv = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE HPApo = @PO	
		
	SELECT @nHPAPOv = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE HPApo = @nHPAPOv	

		
	SELECT @nHPAPO2v = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE HPApo = @nHPAPO2v	
	
	IF @nPOv < @nHPAPOv AND @nPOv < @nHPAPO2v
		BEGIN
		--Need to Swap and use the nPO
		IF @nPOv < @nHPAPOv
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO=@PO, BuyFrom = @BuyFrom WHERE SOitem = @pSOitem
			GOTO DONE
			END
		
		IF @nPOv < @nHPAPO2v
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO2=@PO, BuyFrom2 = @BuyFrom WHERE SOitem = @pSOitem
			GOTO DONE
			END

		END
	
	END
	
/* at the end of the sp */
DONE:
GO
