ALTER PROCEDURE [dbo].[p_AllQuotes_ins]
--	@company [varchar](30),
--	@name [varchar](25) ,
--	@phone [varchar](10),
--	@phone_ext [varchar](6),
--	@fax [varchar](10),
--	@email [varchar](60),
--	@po_num [varchar](20),
--	@alloy [char](12),
--	@form [char](2),
--	@cc [char](1),
--	@pieces [int],
--	@thck [float],
--	@sz2 [float],
--	@sz3 [float],
--	@weight [float],
--	@descript [varchar](50),
--	@p_lb [float] ,
--	@p_pc [float],
--	@p_ft [float],
--	@cuts [float],
--	@otherfld [varchar](10),
--	@otherp [float],
--	@lotp [float],
--	@lotcost [float] ,
--	@leadtime [varchar](15),
--	@cweight [float] ,
--	@cp_lb [float] ,
--	@cp_pc [float] ,
--	@cp_pcc [float],
--	@cthk [char](9),
--	@clotp [float] ,
--	@clotcp [float],
--	@ccut [float] ,
--	@inqdate [datetime] ,
--	@inqnum [int] ,
--	@inqnump [char](9) ,
	@SalesP [char](1) 
--	@salesnum [int],
--	@soitem [char](10),
--	@item [tinyint] ,
--	@hpapo [int] ,
--	@saledate [datetime] ,
--	@shipdate [datetime] ,
--	@buyfrom [varchar](15),
--	@buycost [float] ,
--	@buyfrom2 [varchar](15) ,
--	@hpapo2 [int],
--	@open_ [bit] ,
--	@bracket [tinyint],
--	@CustID [char](20),
--	@quotememo [varchar](max),
--	@comments [varchar](max) ,
--	@countryc [varchar](10) ,
--	@country [varchar](20) ,
--	@services [bit] ,
--	@randlen [bit] ,
--	@metric [bit] ,
--	@StartStock [bit] ,
--	@TN [bit] ,
--	@sz1orig [varchar](20),
--	@sz2orig [varchar](20),
--	@sz3orig [varchar](20),
--	@QuoteDate [datetime] ,
--	@Cover [char](1),
--	@Cut [char](1) ,
	

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	--EXEC dbo.p_AllQuotes_ins @SalesP = 'D'

	DECLARE @InqNum [int]
	DECLARE @InqNumP [char](9) 
	DECLARE @ID int
	
	SET @ID = 0
	
	--Grab InqNum, then try to insert.
	SELECT @InqNum = MAX(inqnum) FROM dbo.AllQuotes WHERE SalesP = @SalesP
	IF @InqNum = null
	BEGIN
		SET @InqNum = 0
	END
	SET @InqNum = @InqNum + 1
	SET @InqNumP = STR(@inqNum,8,0)+@SalesP

	WHILE @ID=0
	BEGIN
		
		BEGIN TRY
		
			INSERT INTO [dbo].[AllQuotes]  (
			  InqNum,
			  InqNumP,
			  SalesP )
			  Values (
			  @InqNum,
			  @InqNumP,
			  @SalesP )
				
			SET @ID = SCOPE_IDENTITY()
		
		END TRY
		BEGIN CATCH
			--Failed because InqNumP was used, Increment and try again
			SELECT @InqNum = MAX(inqnum) FROM dbo.AllQuotes WHERE SalesP = @salesp
			SET @InqNum = @InqNum + 1
			SET @InqNumP = STR(@inqNum,8,0)+@SalesP
		END CATCH
	END
	
SELECT @ID AS AllQuotes_ID

END

