		 @blind_copy_recipients = @FromEmail,
--		 @copy_recipients = @FromEmail,
		 @subject = @SubjectEmail, 
		 @body = @BodyEmail,
		 @body_format = @BodyType
--		, @file_attachments = @NewFileName



		IF @result <> 0
		     BEGIN
				PRINT 'p_eMail_Send to msdb.dbo.sp_send_dbmail Failed'
				PRINT @result
				SET @result = 6
		     END
		ELSE
		     BEGIN
				PRINT 'p_eMail_Send to msdb.dbo.sp_send_dbmail '
				PRINT 'Sent Email'
		     END
	

		--PRINT 'Delete '+@FileName+' File after Copy.'
END
--RETURN @result

GO


