/****** Object:  StoredProcedure [dbo].[p_AutoFixMissingTimePunch]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_AutoFixMissingTimePunch]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_AutoFixMissingTimePunch] AS' 
END
GO
-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 05/24/2019
-- Description:	Attempts to auto fix missed time punches
-- UPDATES:
-- [11/04/2019] - Changed from -12 hours to -10 hours
-- =============================================
ALTER PROCEDURE [dbo].[p_AutoFixMissingTimePunch]
	-- Add the parameters for the stored procedure here
	@punchId int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here

	-- BASE VARIABLES
	declare @employeeBadge int,
			@timeIn datetime,
			@timeOut datetime


	-- GET SPECIFIED PUNCH
	SELECT top(1) @employeeBadge = EmployeeId,
		@timeIn = [TimeIn],
		@timeOut = [TimeOut]
	FROM [dbo].[TC_Replacement_Employees_Times] et
	WHERE et.[Id] = @punchId


	IF (@@ROWCOUNT > 0) -- MAKE SURE WE FOUND THE TIME ENTRY
	BEGIN

		-- CURSOR VARIABLES
		declare @maxMinutes int = 8 * 60,-- 8 work hours
				@totalMinutes int = 0, -- initialize to 0
				@currentStartTime datetime,
				@selectedStartTime datetime,
				@inActivityId smallint,
				@currentEndTime datetime,
				@selectedEndTime datetime,
				@outActivityId smallint,
				@lastOutTime datetime,
				@lastInTime datetime


		IF (@timeIn is null AND @timeOut is null) -- SOMETHING BROKE DELETE RECORD
		BEGIN
			DELETE FROM [dbo].[TC_Replacement_Employees_Times]
			WHERE [Id] = @punchId
		END

		ELSE IF (@timeIn is null) -- WE HAVE THE END TIME, GET ALL PUNCH TIMES IN THE PREVIOUS 12 HOURS
		BEGIN
			declare fixInPunchCursor cursor for 
				SELECT TOP(100) et.[TimeIn], et.[InActivityType], et.[TimeOut], et.[OutActivityType]
				FROM [dbo].[TC_Replacement_Employees_Times] et
				WHERE et.[Id] != @punchId -- don't use the specified punch, as we are trying to fix it
					AND et.[EmployeeId] = @employeeBadge
					AND et.TimeIn >= DATEADD(HOUR, -10, @timeOut) 
					-- Do time in as we don't want someone working a late shift then early shift, having the previous day's hours counted
				Order by TimeIn asc
			open fixInPunchCursor
			FETCH NEXT FROM fixInPunchCursor INTO @currentStartTime, @inActivityId, @currentEndTime, @outActivityId
			while @@FETCH_STATUS = 0 
			BEGIN
				-- ActivityId's: 1 - Work, 2 - Lunch, 3 - Break

				IF (@selectedStartTime is null AND @currentStartTime is not NULL) -- All Activity ID's are acceptable for Time IN
				BEGIN
					set @selectedStartTime = @currentStartTime
				END

				IF (@outActivityId in (1, 2)) -- IF break, we don't care
				BEGIN
					set @selectedEndTime = @currentEndTime
				END

				IF (@currentEndTime is not null)
				BEGIN
					SET @lastOutTime = @currentEndTime
				END

				IF (@selectedStartTime is not NULL AND @selectedEndTime is not NULL)
				BEGIN
					SET @totalMinutes += datediff(minute, @selectedStartTime, @selectedEndTime)
					SET @selectedStartTime = null
					SET @selectedEndTime = null
				END

				FETCH NEXT FROM fixInPunchCursor INTO @currentStartTime, @inActivityId, @currentEndTime, @outActivityId
			END
			close fixInPunchCursor
			DEALLOCATE fixInPunchCursor
			
			-- NOW we have totaled the work hours as minutes

			IF (@totalMinutes < @maxMinutes)
			BEGIN
				IF (DATEADD(MINUTE, @totalMinutes - @maxMinutes, @timeOut) >= ISNULL(@lastOutTime, DATEADD(HOUR, -24, @timeOut))) -- IF FIRST ENTRY, there wont be a lastOutTime
				BEGIN 
					-- WE CAN NOW UPDATE THE MISSING CLOCK 
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET TimeIn = DATEADD(MINUTE, @totalMinutes - @maxMinutes, @timeOut),
						InActivityType = 1, -- WORK
						[InAutoStatus] = 1,
						[TimeInMissed] = 1
					WHERE Id = @punchId
				END
				ELSE -- last punch was too recent, setTimeIn = LastTimeOut
				BEGIN
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET TimeIn = @lastOutTime,
						InActivityType = 1, -- WORK
						[InAutoStatus] = 1,
						[TimeInMissed] = 1
					WHERE Id = @punchId
				END
			END
			ELSE -- total minutes exceeds 8 hours
			BEGIN
				IF (DATEADD(MINUTE, - 15, @timeOut) >= @lastOutTime) -- set a minumum time frame of 15 minutes
				BEGIN 
					-- WE CAN NOW UPDATE THE MISSING CLOCK 
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET TimeIn = DATEADD(MINUTE, -15, @timeOut),
						InActivityType = 1, -- WORK
						[InAutoStatus] = 1,
						[TimeInMissed] = 1
					WHERE Id = @punchId
				END
				ELSE -- last punch was too recent, set TimeIn = LastTimeOut
				BEGIN
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET TimeIn = @lastOutTime,
						InActivityType = 1, -- WORK
						[InAutoStatus] = 1,
						[TimeInMissed] = 1
					WHERE Id = @punchId
				END
			END
		END

		ELSE IF (@timeOut is null) -- WE HAVE THE START TIME, GET ALL PUNCH TIMES IN THE PREVIOUS AND NEXT 12 HOURS
		BEGIN
			declare fixOutPunchCursor cursor for 
				SELECT TOP(100) et.[TimeIn], et.[InActivityType], et.[TimeOut], et.[OutActivityType]
				FROM [dbo].[TC_Replacement_Employees_Times] et
				WHERE et.[Id] != @punchId -- don't use the specified punch, as we are trying to fix it
					AND et.[EmployeeId] = @employeeBadge
					AND et.TimeIn >= DATEADD(HOUR, -10, @timeOut) 
					-- Do time in as we don't want someone working a late shift then early shift, having the previous day's hours counted
					AND et.TimeIn <= DATEADD(HOUR, 8, @timeOut)
				Order by TimeIn asc
			open fixOutPunchCursor
			FETCH NEXT FROM fixOutPunchCursor INTO @currentStartTime, @inActivityId, @currentEndTime, @outActivityId
			while @@FETCH_STATUS = 0 
			BEGIN
				-- ActivityId's: 1 - Work, 2 - Lunch, 3 - Break

				IF (@currentStartTime is not NULL) -- All Activity ID's are acceptable for Time IN
				BEGIN
					IF (@selectedStartTime is null)
					BEGIN
						set @selectedStartTime = @currentStartTime
					END

					set @lastInTime = @currentStartTime
				END

				IF (@outActivityId in (1, 2)) -- IF break, we don't care
				BEGIN
					set @selectedEndTime = @currentEndTime
				END

				IF (@currentEndTime is not null)
				BEGIN
					SET @lastOutTime = @currentEndTime
				END

				IF (@selectedStartTime is not NULL AND @selectedEndTime is not NULL)
				BEGIN
					SET @totalMinutes += datediff(minute, @selectedStartTime, @selectedEndTime)
					SET @selectedStartTime = null
					SET @selectedEndTime = null
				END

				FETCH NEXT FROM fixOutPunchCursor INTO @currentStartTime, @inActivityId, @currentEndTime, @outActivityId
			END
			close fixOutPunchCursor
			DEALLOCATE fixOutPunchCursor
			
			-- NOW we have totaled the work hours as minutes

			IF (@totalMinutes < @maxMinutes)
			BEGIN
				IF ((ISNULL(@lastInTime, @timeIn) <= @timeIn) OR (DATEADD(MINUTE, @maxMinutes - @totalMinutes, @timeIn) <= @lastInTime))
				BEGIN
					-- WE CAN NOW UPDATE THE MISSING CLOCK 
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET [TimeOut] = DATEADD(MINUTE, @maxMinutes - @totalMinutes, @timeIn),
						OutActivityType = 1, -- WORK
						[OutAutoStatus] = 1,
						[TimeOutMissed] = 1
					WHERE Id = @punchId
				END

				ELSE -- last punch was too recent, set [TimeOut] = @lastInTime
				BEGIN
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET [TimeOut] = @lastInTime,
						OutActivityType = 1, -- WORK
						[OutAutoStatus] = 1,
						[TimeOutMissed] = 1
					WHERE Id = @punchId
				END
			END
			ELSE -- total minutes exceeds 8 hours
			BEGIN
				IF ((ISNULL(@lastInTime, @timeIn) <= @timeIn) OR (DATEADD(MINUTE, 15, @timeIn) <= @lastInTime)) -- set a minumum time frame of 15 minutes
				BEGIN 
					-- WE CAN NOW UPDATE THE MISSING CLOCK 
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET [TimeOut] = DATEADD(MINUTE, 15, @timeIn),
						OutActivityType = 1, -- WORK
						[OutAutoStatus] = 1,
						[TimeOutMissed] = 1
					WHERE Id = @punchId
				END
				ELSE -- last punch was too recent, set [TimeOut] = @lastInTime
				BEGIN
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET [TimeOut] = @lastInTime,
						OutActivityType = 1, -- WORK
						[OutAutoStatus] = 1,
						[TimeOutMissed] = 1
					WHERE Id = @punchId
				END
			END
		END
	END
END
GO
