ALTER PROCEDURE [dbo].[p_Calc_Cust_UnitQty ] 
(
@nPieces INT,
@cAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(11,4),
@nSize2 DECIMAL(10,3),
@nSize3 DECIMAL(10,3),
@cSOitem CHAR(10)
)
AS
BEGIN
--EXEC dbo.p_Calc_Cust_UnitQty  1,'C-276','40',1,12,48,''
--EXEC dbo.p_Calc_Cust_UnitQty  @nPieces, @cAlloy, @cForm, @nThickness, @nSize2, @nSize3, @cSOitem
--EXEC dbo.p_Calc_Cust_UnitQty          1,'HPA N60     ','10',    1.7500,   36.000,    0.000,' 135594-01'

--Called from FoxPro 

--Returns:
-- @nUnitQty= Calculated Cust Quanity for PackingSlip. Pounds, PC or feet.

SET NOCOUNT ON

DECLARE @nTestPounds as float(53)
DECLARE @nUnitQty as REAL
SET @nUnitQty = 0
DECLARE @nDiskWeight AS REAL
SET @nDiskWeight = 0

IF @nPieces < 1
	SET @nPieces = 1

--Find how Customer Unit is priced.
DECLARE @nPU TinyInt = 0
SELECT @nPU = S_PU 
	FROM dbo.Sales WITH(NOLOCK)
	WHERE SOitem = @cSOitem


IF @nPU IS NULL
SELECT @nPU = S_PU
	FROM dbo.AllQuotes WITH(NOLOCK)
	WHERE SOitem = @cSOitem


DECLARE @luse3rdDim bit = 0

IF @nPU = 1 OR @nPU = 6
	begin
--	print @cFormPricing


	DECLARE @nDensity DECIMAL(9,4)
	SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
	IF @nDensity = 0
		SET @nDensity = .29

	
	IF @cForm = '10' 
	   BEGIN
		--CHANGE FROM @nThickness*1.023 2-9-94
		--USING CASE STRUCTURE WITH ERIKS INFO
		IF @nThickness = 0
			SET @nUnitQty = 0
		ELSE
		IF @nThickness < .2
			begin
			SET @nTestPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			IF @nTestPounds > 9999999.9
				SET @nUnitQty = 9999999.9
			ELSE
				SET @nUnitQty = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		ELSE
			IF @nThickness < 1
			begin
			SET @nTestPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			IF @nTestPounds > 9999999.9
				SET @nUnitQty = 9999999.9
			ELSE
				SET @nUnitQty = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		ELSE
			IF @nThickness < 3
			begin
			SET @nTestPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			IF @nTestPounds > 9999999.9
				SET @nUnitQty = 9999999.9
			ELSE
				SET @nUnitQty = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		ELSE
		IF @nThickness < 6
			SET @nUnitQty = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		ELSE
			SET @nUnitQty = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
			
	   END
	ELSE
	IF @cForm = '11'
		SET @nUnitQty = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	ELSE
	IF @cForm = '12'
		SET @nUnitQty = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	ELSE
	IF @cForm = '13' 
		SET @nUnitQty = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	ELSE
	IF @cForm = '20' 
		SET @nUnitQty = @nSize2* @nPieces 
	ELSE
	IF @cForm = '21' 
		SET @nUnitQty = @nSize3 * @nPieces
		--SET @nUnitQty = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
--	ELSE
--	IF @cForm = '30' 
--		SET @nUnitQty = @nSize3* @nPieces 
	ELSE
	IF @cForm = '40' 
		begin
		SET @nTestPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
		IF @nTestPounds > 9999999.9
			SET @nUnitQty = 9999999.9
		ELSE
			SET @nUnitQty = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
		end
	ELSE
	IF @cForm = '80'
		SET @nUnitQty = (@nDensity * @nThickness * 1.015 * (@nSize2+.5) * (@nSize2+.5) * @nPieces )
		
	
	end
ELSE 
IF @nPU = 2 or @nPU = 7 --Dollar / Foot or Meter
	begin
	
	SET @luse3rdDim = dbo.f_GetForm_use3rdDim(@cForm)

	IF @luse3rdDim = 0
		SET @nUnitQty = @nSize2*@nPieces/12
	ELSE
		SET @nUnitQty = @nSize3*@nPieces/12

	end
ELSE 
IF @nPU = 3
	SET @nUnitQty = @nPieces
ELSE 
IF @nPU = 4
	--LOT
	SET @nUnitQty = 1
ELSE 
IF @nPU = 5
	begin
	--Dollar / Inch
	SET @luse3rdDim = dbo.f_GetForm_use3rdDim(@cForm)

	IF @luse3rdDim = 0
		SET @nUnitQty = @nSize2*@nPieces
	ELSE
		SET @nUnitQty = @nSize3*@nPieces

	end
ELSE 

IF @nPU = 6	--Dollar / Kg
	SET @nUnitQty = @nUnitQty / 2.205

IF @nPU = 7 --Dollar / Meter
	SET @nUnitQty = @nUnitQty / 3.281



IF @nUnitQty > 9999999.9
	SET @nUnitQty = 9999999.9


SELECT @nUnitQty AS UnitQty


END

--GRANT EXECUTE ON [dbo].[p_Calc_Cust_UnitQty ] TO [WINDFALL\HPA]











GO
