/****** Object:  Stored Procedure dbo.p_Weight    Script Date: 11/15/2005 10:13:25 AM ******/
/*
--Use [dbo].[p_GetQuote]
This Procedure is a copy of p_GetQuote code
*/


ALTER PROCEDURE [dbo].[p_CALC_Weight] 
(
@nPieces TinyINT,
@cAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),
@nPounds FLOAT(24) OUTPUT
)
AS
--nPounds = 0
--
--sql_sp = "{CALL p_CALC_Weight ("
--sql_sp = sql_sp + ""+ "1" + ","
--sql_sp = sql_sp + "'"+ cAlloy+ "',"
--sql_sp = sql_sp + "'"+ cForm+ "'," 
--sql_sp = sql_sp + ""+ LEFT(STR(nStdSize,9,4),8)+ "," && 3 decimals, not 4
--sql_sp = sql_sp + ""+ STR(nSize2,9,3)+ ","
--sql_sp = sql_sp + ""+ STR(nSize3,9,3)+ ","
--sql_sp = sql_sp + "?@nPounds,"
--sql_sp = Sql_sp + ")}"
--nSQLEXEC = SQLEXEC(nConnHandle, SQL_SP )

-- testing audit
--Also see EXEC dbo.p_Getweight 1,'C-276','40',1,12,48

BEGIN
SET NOCOUNT ON

DECLARE @cMessage as VARCHAR(2000)
SET @cMessage = ''

IF @nPieces < 1
	SET @nPieces = 1

DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
    SET @cMessage = RTRIM(@cMessage)+' Alloy Density not found!'
   END
ELSE
   SET @cMessage = RTRIM(@cMessage)+'Used Density of '+STR(@nDensity,5,3)
--Find Thickness used in PriceTable

SET @nPounds = 0

IF @cForm = '0' 
	SET @nPounds = 0
	
IF @cForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		BEGIN
		SET @nPounds = 0
		END
	ELSE
	IF @nThickness > 4
		BEGIN
		SET @nPounds = (POWER(((@nThickness/2) *1.025)*2 ,2)* 3.14 * @nDensity* @nSize2* @nPieces /4)
		END
	--Changed from <3* .01 and <6 *.020 >6 *.032  2010
	--SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)

   END
ELSE
IF @cForm = '11' 
   BEGIN
	--Flat Bar
	SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
   END
ELSE
IF @cForm = '12'
	BEGIN
	 --HEX Bar
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	END
ELSE
IF @cForm = '13' 
	BEGIN
	--Square Bar
	SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
	END
ELSE
IF @cForm = '20' 
	BEGIN
	--Wire Spool
	SET @nPounds = @nSize2* @nPieces 
	END
ELSE
IF @cForm = '21' 
	BEGIN
	--TIG cans
	SET @nPounds = @nSize3 * @nPieces 
	--SET @nPounds = (@nDensity* @nThickness* 1.003* @nSize2* @nSize3* @nPieces )
	END
ELSE
IF @cForm = '30' 
	BEGIN
	--Coated Electrodes
	SET @nPounds = @nSize3* @nPieces 
	END
ELSE
IF @cForm = '40' 
	BEGIN
	--Plate / Sheet
	IF @nThickness < 4
		SET @nPounds = (@nDensity* @nThickness* 1.001* @nSize2* @nSize3* @nPieces )
	ELSE
		SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
	END
ELSE
IF @cForm = '51' 
	BEGIN
		--STRIP      
		SET @nPounds = @nSize3
	END
ELSE
IF @cForm = '52' 
	BEGIN
		--Coil
		SET @nPounds = @nSize3
	END
ELSE
IF @cForm = '53' 
	BEGIN
		--Hot Band
		SET @nPounds = @nSize3
	END
ELSE
IF @cForm = '60'
	BEGIN
		--Tube
		SET @nPounds = @nDensity *@nSize3*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	END
ELSE
IF @cForm = '65'
	BEGIN
		--Pipe
		DECLARE @nPipeWeight DECIMAL(9,4)
		SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
		IF @nPipeWeight = 0
			SET @cMessage = RTRIM(@cMessage)+' Pipe Weight not found!'

		SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	END
ELSE
IF @cForm = '80'
	BEGIN
		--Disk
		SET @nPounds = (@nDensity* @nThickness* 1.015* (@nSize2)* (@nSize2)* @nPieces )
	END
ELSE
IF @cForm = '99' 
	BEGIN
		--Ingot
		SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
	END
	
RETURN @nPounds
END


GO
