ALTER PROCEDURE [dbo].[p_CalcPrice]
(
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@nStdSize DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nPounds DECIMAL(9,1),
@nForceBracket TinyInt,
--UserName,
--sesionID,
@nPrice DECIMAL(11,2) OUTPUT,
@nBracket TinyInt OUTPUT, 
@cMessage CHAR(2000) OUTPUT,
@bActivePrice BIT OUTPUT
)
AS

/*
DECLARE @cAlloy char(12),@cForm CHAR(2),@cCC CHAR(1), @nStdSize DECIMAL(9,4),@nSize2 DECIMAL(9,3),@nPounds DECIMAL(9,1),@nForceBracket INT
SELECT @cAlloy='400',@cForm='10',@cCC='1',@nStdSize=1,@nSize2=0,@nPounds=10,@nForceBracket=0
DECLARE @nPrice DECIMAL(9,2), @nBracket TinyInt, @cMessage CHAR(2000), @bActivePrice BIT 
EXEC p_CalcPrice @cAlloy,@cForm,@cCC,@nStdSize,@nSize2,@nPounds,@nForceBracket,@nPrice OUTPUT,@nBracket OUTPUT , @cMessage OUTPUT, @bActivePrice OUTPUT
PRINT 'Price  $:'+CAST(@nPrice AS CHAR)
PRINT 'Bracket :'+CAST(@nBracket AS CHAR)
PRINT 'Message :'+@cMessage
PRINT 'Active :'+CAST(@bActivePrice AS CHAR)
*/

--sql_sp = "{CALL p_CalcPrice ('"+cAlloy+"','"+cForm+"','1',"+LEFT(STR(nStdSize,9,4),8)+ ","+STR(nSize2,9,3)+","+STR(nPounds,9,1)+",?@nPrice,?@nBracket,?@cMessage,?@bActivePrice )}"
--nSQLEXEC = SQLEXEC(nConnHandle, SQL_SP )

--RETURNS:
--@nPrice= Price per Quantity.
--@nBracket= Price bracket used.
--@cMessage= Empty or 'Price not found in table.'
--@bActivePrice= Active Price

BEGIN
SET NOCOUNT ON
declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @cCCorig CHAR(1)
SET @cCCorig = @cCC

--Check User login
--IF UserName, sesionID Parameter = UserName, SesionID stored in users table and Login limit date not expired

SET @cMessage = '' 
--+ rtrim(@cAlloy)

--DECLARE @lActivePrice BIT
SET @bActivePrice = 0
--Find Thickness used in PriceTable

IF @nForceBracket = 0
	SET @nPounds = @nPounds
ELSE
IF @nForceBracket = 1
	SET @nPounds = 4
IF @nForceBracket = 2
	SET @nPounds = 9
IF @nForceBracket = 3
	SET @nPounds = 24
IF @nForceBracket = 4
	SET @nPounds = 49
IF @nForceBracket = 5
	SET @nPounds = 99
IF @nForceBracket = 6
	SET @nPounds = 199
IF @nForceBracket = 7
	SET @nPounds = 499
IF @nForceBracket = 8
	SET @nPounds = 999
IF @nForceBracket = 9
	SET @nPounds = 1999
IF @nForceBracket = 10
	SET @nPounds = 4999
IF @nForceBracket = 11
	SET @nPounds = 5001

DECLARE @cCCAdjust CHAR(1)
SET @cCCAdjust = '0'
DECLARE @nAdjust NUMERIC(18,9)

IF @cCC = 'A'
	begin
	SET @cCCAdjust = 'A'
	SELECT TOP 1 @nAdjust = [A] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
ELSE
IF @cCC = 'B'
	begin
	SET @cCCAdjust = 'B'
	SELECT TOP 1 @nAdjust = [B] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'C'
	begin
	SET @cCCAdjust = 'C'
	SELECT TOP 1 @nAdjust = [C] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
ELSE
IF @cCC = 'D'
	begin
	SET @cCCAdjust = 'D'
	SELECT TOP 1 @nAdjust = [D] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
ELSE
IF @cCC = 'E'
	begin
	SET @cCCAdjust = 'E'
	SELECT TOP 1 @nAdjust = [E] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'F'
	begin
	SET @cCCAdjust = 'F'
	SELECT TOP 1 @nAdjust = [F] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'S'
	begin
	SET @cCCAdjust = 'S'
	SELECT TOP 1 @nAdjust = [S] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'T'
	begin
	SET @cCCAdjust = 'T'
	SELECT TOP 1 @nAdjust = [T] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'U'
	begin
	SET @cCCAdjust = 'U'
	SELECT TOP 1 @nAdjust = [U] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'V'
	begin
	SET @cCCAdjust = 'V'
	SELECT TOP 1 @nAdjust = [V] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'W'
	begin
	SET @cCCAdjust = 'W'
	SELECT TOP 1 @nAdjust = [W] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'X'
	begin
	SET @cCCAdjust = 'X'
	SELECT TOP 1 @nAdjust = [X] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end
IF @cCC = 'Y'
	begin
	SET @cCCAdjust = 'Y'
	SELECT TOP 1 @nAdjust = [Y] FROM dbo.ConditionCodeAdjust
	SET @cCC = '2'
	end

---------------------------------------------------
--Use the N60 Cold Work Chart for N50 Cold Work except for condition Code 2- no Anneal
IF @cAlloy = 'HPA N50' AND  @cCCorig = '2'
	begin
	SET @cCC = 1
	SET @cCCAdjust = '1'
	SET @nAdjust = 1.15
	end

IF @cAlloy = 'HPA N50' AND  @cCCorig != '2'
	SELECT @cAlloy = 'HPA N60' 
		WHERE @cCCorig = 'T' 
		OR @cCCorig = 'U' 
		OR @cCCorig = 'V' 
		OR @cCCorig = 'W' 
		OR @cCCorig = 'X' 
		OR @cCCorig = 'Y' 


SET @cAlloy = dbo.f_Price_Alloy( @cAlloy )

---------------------------------------------------

SET @nPrice=0
--@nPrice
IF @nPounds < 5
  BEGIN
	SELECT TOP 1 @nPrice = w0, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 1
   END
ELSE 
IF @nPounds >= 5 AND @nPounds < 10
  BEGIN
	SELECT TOP 1 @nPrice = w5, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 2
   END
ELSE 
IF @nPounds >= 10 AND @nPounds < 25
  BEGIN
	SELECT TOP 1 @nPrice = w10, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 3
   END
ELSE 
IF @nPounds >= 25 AND @nPounds < 50
  BEGIN
	SELECT TOP 1 @nPrice = w25, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 4
   END
ELSE 
IF @nPounds >= 50 AND @nPounds < 100
  BEGIN
	SELECT TOP 1 @nPrice = w50, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 5
   END
ELSE 
IF @nPounds >= 100 AND @nPounds < 200
  BEGIN
	SELECT TOP 1 @nPrice = w100, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 6
   END
ELSE 
IF @nPounds >= 200 AND @nPounds < 500
  BEGIN
	SELECT TOP 1 @nPrice = w200, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 7
   END
ELSE 
IF @nPounds >= 500 AND @nPounds < 1000
  BEGIN
	SELECT TOP 1 @nPrice = w500, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 8
   END
ELSE 
IF @nPounds >= 1000 AND @nPounds < 2000
  BEGIN
	SELECT TOP 1 @nPrice = w1000, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 9
   END
ELSE 
IF @nPounds >= 2000 AND @nPounds < 5000
  BEGIN
	SELECT TOP 1 @nPrice = w2000, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 10
   END
ELSE
IF @nPounds >= 5000
  BEGIN
	SELECT TOP 1 @nPrice = wBase, @bActivePrice = ActivePric 
		FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )
	IF @nPrice = 0
		SELECT TOP 1 @nPrice = w2000, @bActivePrice = ActivePric 
			FROM dbo.pricetable WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 11
   END
ELSE
   BEGIN
	SET @nBracket = 0

	SET @cMessage = 'Price not found in table.'
   END

IF @cCCAdjust != '0'
	SET @nPrice = @nPrice * @nAdjust


--select @RC = @@ROWCOUNT, @err = @@ERROR


--REPLACE Quotes.descript WITH ThisFormSet.QuotesDescription( @cForm, @nThickness, @nSize2, @nSize3 )

RETURN
END




