-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 12/29/2022
-- Description:	Creates Survey Packing Slip Assignment and returns survey HTML code
-- UPDATES:
-- 12/28/2022: Updated to use SalesNum instead of SOitem
-- 12/29/2022: Updated to use PackinSlipNo. Converted to new Procedure
-- 01/30/2023: Fixed issue where it was not correctly removing extra SO's for @SalesNum from @allSOs
-- =============================================
ALTER PROCEDURE [dbo].[p_Create_Survey_PackingSlip_Assignment_HTML] 
	-- Add the parameters for the stored procedure here
	@identifier varchar(50) -- Could be EmployeeID, SalesNum, SOitem, PackingSlip, POitem, Quote, etc. This should match the name of the procedure
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Declare the return variable here
	DECLARE @assignmentID uniqueidentifier

	-- Add the T-SQL statements to compute the return value here
	DECLARE @_surveyID uniqueidentifier,
		@_contactInfoID uniqueidentifier,
		@allSOs varchar(max), -- Required to find SO's from PackingSlip
		@SalesNum varchar(10), -- pick the first SO present in @allSOs
		@dateNow datetime = GETDATE(),
		@phoneNumber varchar(15), -- Required for Creating Contact Info
		@email varchar(254), -- Required for Creating Contact Info
		@companyName varchar(100), -- Required for Creating Contact Info
		@contactName varchar(100) -- Optional for Creating Contact Info


	SELECT TOP(1) @allSOs = [all_so]
	FROM [dbo].[PackingSlip_No]
	WHERE [packingsli] = @identifier

	-- Removes any additional SalesNum's present, as multiple SalesNumbers could be in a PackingSlip
	--SELECT @SalesNum = reverse(substring(reverse (@allSOs), CHARINDEX(';', reverse (@allSOs))+1, len(reverse (@allSOs))));
	SELECT TOP(1) @SalesNum = LTRIM(RTRIM(so.value)) 
	FROM STRING_SPLIT(@allSOs, ';') as so
	WHERE so.value != '';

	-- Verify that the Survey Exists
	SELECT TOP(1) @_surveyID = ID
	FROM [dbo].[Survey]
	WHERE ID = 'D251F921-F3F6-EC11-A85A-ECB1D783CEC0' -- SalesOrder Survey

	IF (@_surveyID is not NULL) -- Survey exists, continue
	BEGIN
		SELECT TOP(1) 
			@phoneNumber = [Phone],
			@email = [Email],
			@companyName = [Company],
			@contactName = [Name]
		FROM [dbo].[AllQuotes]
		WHERE SalesNum = LTRIM(RTRIM(REPLACE(@SalesNum, 'SO', '')))

		IF ((@phoneNumber is not NULL OR @email is not NULL) AND @companyName is not NULL) -- Make sure data was found
		BEGIN 

			-- Create Survey Contact Info
			DECLARE @contactInfoIDTable table([ID] [uniqueidentifier]);
			INSERT INTO [dbo].[Survey_Assignment_ContactInfos]
			(
				[DateCreated]
				,[PhoneNumber]
				,[Email]
				,[CompanyName]
				,[ContactName]
				,[SalesOrder]
				,[Quote]
			)
			OUTPUT INSERTED.[ID] INTO @contactInfoIDTable
			VALUES
			(
				@dateNow,
				@phoneNumber,
				@email,
				@companyName,
				@contactName,
				@SalesNum,
				NULL
			)

			-- GET Contact Info ID
			SELECT TOP(1) @_contactInfoID = ID
			FROM @contactInfoIDTable
			

			-- Create Survey Assignment
			DECLARE @surveyAssignmentIDTable table([ID] [uniqueidentifier]);
			INSERT INTO [dbo].[Survey_Assignments]
			(
				[SurveyID]
				,[DateAssigned]
				,[AssignmentType]
				,[TargetIdentifier]
				,[Survey_Assignment_ContactInfoID]
			)
			OUTPUT INSERTED.[ID] INTO @surveyAssignmentIDTable
			VALUES
			(
				@_surveyID,
				@dateNow,
				2,
				LTRIM(RTRIM(@SalesNum)),
				@_contactInfoID
			)

			-- GET Assignment ID
			SELECT TOP(1) @assignmentID = ID
			FROM @surveyAssignmentIDTable

		END
	END

	-- Return the result of the Procedure
	SELECT [dbo].[f_Format_Survey_Purpose_HTML] (@assignmentID, 'Sales Order(s)')
END
GO
