			DECLARE @surveyAssignmentIDTable table([ID] [uniqueidentifier]);
			INSERT INTO [dbo].[Survey_Assignments]
			(
				[SurveyID]
				,[DateAssigned]
				,[AssignmentType]
				,[TargetIdentifier]
				,[Survey_Assignment_ContactInfoID]
			)
			OUTPUT INSERTED.[ID] INTO @surveyAssignmentIDTable
			VALUES
			(
				@_surveyID,
				@dateNow,
				2,
				LTRIM(RTRIM(@identifier)),
				@_contactInfoID
			)

			-- GET Assignment ID
			SELECT TOP(1) @assignmentID = ID
			FROM @surveyAssignmentIDTable

		END
	END

	-- Return the result of the Procedure
	SELECT [dbo].[f_Format_Survey_Purpose_HTML] (@assignmentID, 'Sales Order')
END
GO
