/****** Object:  Stored Procedure dbo.p_Weight    Script Date: 11/15/2005 10:13:25 AM ******/



ALTER PROCEDURE [dbo].[p_Daily_Report] 
AS

--EXEC p_Daily_Report

DECLARE CurrentSalesP CURSOR FOR
SELECT DISTINCT AQ.SalesP,dbo.SalesPDescription(AQ.SalesP) AS SalesPerson, dbo.SalesPEmail(AQ.SalesP) as Email FROM dbo.AllQuotes AQ WHERE AQ.InqDate > GetDate()-90

DECLARE @SalesP CHAR(1),
	@SalesPerson char(20),
	@Email CHAR(30),
	@AllSalesPSO VARCHAR(255),
	@AllSalesPPO VARCHAR(255)
	
SET @AllSalesPSO = ''
SET @AllSalesPPO = ''

DECLARE @cSQL VARCHAR(1000)
DECLARE @nCount INT

OPEN CurrentSalesP
FETCH NEXT FROM CurrentSalesP 
	INTO @SalesP, @SalesPerson, @Email
	
WHILE @@FETCH_STATUS = 0
BEGIN 
	
	SET @AllSalesPSO = @AllSalesPSO + @SalesP
	
	SET @cSQL = "SELECT AQ.SalesP, S.SOitem, AQ.Company, S.ItemCost, S.ItemSale 
		FROM dbo.Sales S, dbo.AllQuotes AQ 
		WHERE ISNULL(S.Shipped,0) = 0 
		AND ISNULL(S.ShipDue,GetDate())+1 <= GETDATE()
		AND ISNULL(S.Cncld,0) = 0 
		AND ISNULL(S.CMPLT,0) = 0
		AND ISNULL(S.ShipOn,0) = 0
		AND AQ.SalesP = '"+@SalesP+"'		
		AND AQ.SOitem = S.SOitem"
			
	SELECT @nCount = COUNT(*) FROM dbo.Sales S, dbo.AllQuotes AQ 
		WHERE ISNULL(S.Shipped,0) = 0 
		AND S.ShipDue < GETDATE() 
		AND ISNULL(S.Cncld,0) = 0 
		AND ISNULL(S.CMPLT,0) = 0
		AND ISNULL(S.ShipOn,0) = 0
		AND AQ.SalesP = @SalesP
		AND AQ.SOitem = S.SOitem
		
	IF @nCount > 0
		begin	
		PRINT 'Email:'+@Email
		
		EXEC msdb.dbo.sp_send_dbmail 
		 @profile_name = 'ERP_1s', 
		 @recipients = @Email, 
		 @query = @cSQL, 
		 @subject = 'Late Sales Orders', 
		 @attach_query_result_as_file = 0,
		 @execute_query_database = 'ERP_1';
	
		PRINT 'Late SO for:'+@SalesP+' '+ @SalesPerson+ @Email
	
		WAITFOR DELAY '00:00:10';
		end
		
		
	FETCH NEXT FROM CurrentSalesP 
		INTO @SalesP, @SalesPerson, @Email

END

CLOSE CurrentSalesP 
DEALLOCATE CurrentSalesP


--*--*--*--


DECLARE CurrentPurchaser CURSOR FOR
SELECT DISTINCT PO.SalesP
	,dbo.SalesPDescription(PO.SalesP) AS SalesPerson
	, dbo.SalesPEmail(PO.SalesP) as Email 
	FROM dbo.PurchaseOrder PO 
	WHERE PO.Received < GetDate()
	AND ISNULL(Cancelled,0) = 0
	AND ISNULL(Delivered,0) = 0
	AND dbo.SalesPEmail(PO.SalesP) IS NOT NULL

OPEN CurrentPurchaser
FETCH NEXT FROM CurrentPurchaser 
	INTO @SalesP, @SalesPerson, @Email
	
WHILE @@FETCH_STATUS = 0
BEGIN 

	SET @AllSalesPPO = @AllSalesPPO + @SalesP
	
	SET @cSQL = "SELECT PO.POitem, PO.Company
		, CASE PO.SOitem WHEN '      0-01' THEN '   No SO' ELSE ISNULL(PO.SOitem,'   No SO') END AS SOitem
		, PO.Alloy
		FROM dbo.PurchaseOrder PO 
		WHERE ISNULL(PO.Delivered,0) = 0
		AND ISNULL(PO.Cancelled,0) = 0
		AND ISNULL(PO.Services,0) = 0
		AND ISNULL(PO.Due_Max,ISNULL(PO.Due_Min,ISNULL(PO.OrderDate,GetDate())))+1 <= GETDATE()
		AND PO.SalesP = '"+@SalesP+"'"

--		, suser_sname()		
		
	SELECT @nCount = COUNT(*) FROM dbo.PurchaseOrder PO 
		WHERE ISNULL(PO.Delivered,0) = 0
		AND ISNULL(PO.Cancelled,0) = 0
		AND ISNULL(PO.Due_Max,ISNULL(PO.Due_Min,ISNULL(PO.OrderDate,GetDate()))) < GETDATE()
		AND PO.SalesP = @SalesP
		

	IF @nCount > 0
		begin	
		
		EXEC msdb.dbo.sp_send_dbmail 
		 @profile_name = 'ERP_1', 
		 @recipients = @Email, 
		 @query = @cSQL,
		 @subject = 'Late Purchase Orders', 
		 @attach_query_result_as_file = 0,
		 @execute_query_database = 'ERP_1';
		
		PRINT 'Late PO for:'+@SalesP+' '+ @SalesPerson+ @Email
		
		WAITFOR DELAY '00:00:30';
		end
		
		
	FETCH NEXT FROM CurrentPurchaser 
		INTO @SalesP, @SalesPerson, @Email

END

CLOSE CurrentPurchaser 
DEALLOCATE CurrentPurchaser

DECLARE @text VARCHAR(255)
SET @Text = 'SO:'+@AllSalesPSO+' PO:'+@AllSalesPPO

EXEC dbo.p_eMail_Send  'vfpprogramming@ERP_1s.com', 'vfpprogramming@ERP_1s.com', 'p_Daily_Report', @Text, @BodyType ='HTML'
--*--*--*--
GO
