ALTER PROCEDURE [dbo].[p_Duplicates_Sales_Invoice]
AS

--BEGIN TRANSACTION; EXEC [dbo].[p_Duplicates_Sales_Invoice]
--commit
  Set NoCount On

----------------------------
-- show the Duplictes
PRINT 'show the Duplictes'
----------------------------

SELECT Distinct t.ID,t.SOitem,ISNULL(t.Reconciled,0) AS Reconciled, t.GL_Account
FROM dbo.Sales_Invoice As t
Inner Join
(
  SELECT SOitem,GL_Account
  FROM dbo.Sales_Invoice
  WHERE ISNULL(Sales_Invoice.Reconciled,0) = 0
  Group By SOitem,GL_Account
  
  Having Count(*) > 1
) dt
  On (dt.SOitem = t.SOitem) AND (dt.GL_Account = t.GL_Account)

----------------------------
-- Delete the previous Duplicates 
-- where SOitem same and not Reconciled

----------------------------

Print 'Count number of records to start with'
SELECT COUNT(*) AS Records FROM dbo.Sales_Invoice

Print 'Select highest ID of Dubplicates'


/*
SELECT Invoice, SOitem ,GL_Account
,MAX(ID) AS ID
into #t1 
FROM dbo.Sales_Invoice
WHERE NOT ( SOitem = '') 
AND Sales_Invoice.Reconciled = 0
GROUP BY Invoice, SOitem, GL_Account
HAVING COUNT(*) > 1
ORDER BY Invoice, SOitem, GL_Account
*/

SELECT x.Invoice, x.SOitem ,x.GL_Account
,(SELECT Max(ID) AS MaxID FROM dbo.Sales_Invoice SI2 WHERE SI2.Invoice = x.Invoice AND SI2.SOitem = x.SOitem AND SI2.GL_Account = x.GL_Account) AS MaxID
,x.CNTD
into #t1 

FROM (
SELECT Invoice, SOitem ,GL_Account
, COUNT(*) AS CNTD
FROM dbo.Sales_Invoice
WHERE ISNULL(Sales_Invoice.Reconciled,0) = 0
GROUP BY Invoice, SOitem, GL_Account
HAVING COUNT(*) > 1

) x
ORDER BY x.Invoice, x.SOitem, x.GL_Account

Print 'Show Marked Records'
SELECT * FROM #t1

Print 'Count number of marked records '
SELECT COUNT(*) AS Records FROM #t1


PRINT 'Delete the previous Duplicates'

DELETE D 
FROM dbo.Sales_Invoice D 
INNER JOIN #t1 t ON D.SOitem = t.SOitem 
WHERE D.GL_Account = t.GL_Account
AND D.Invoice = t.Invoice
AND D.ID < t.MaxID
AND ISNULL(D.Reconciled,0) = 0


-- clean up
Drop table #t1

SELECT * FROM dbo.Sales_Invoice order by SOitem desc -- no dupes !!

Print 'Count number of records to now'
SELECT COUNT(*) AS Records FROM dbo.Sales_Invoice

--p_Duplicates_Sales_Invoice
GO
