ALTER PROCEDURE [dbo].[p_Fix_AcctStnd] 
(
@ID INT
)
AS
-- EXEC dbo.p_Fix_AcctStnd(AllQuotes.ID)
--*EXEC dbo.p_Fix_AcctStnd(Alloy,Form,Pieces,Thck,Size2,Size3,[Weight],P_lb,P_pc,P_ft,Cuts,OtherFld,OtherP,LotP,Q_P,Q_QTY,Q_PU,Q_Total,S_P,S_QTY,S_PU,InqNumP)

BEGIN
SET NOCOUNT ON

IF @ID < 1
begin
	PRINT 'Bad ID'
	RETURN -1
end

IF NOT EXISTS(SELECT ID FROM dbo.AllQuotes WHERE ID= @ID)
begin
	PRINT 'ID not Found'
	RETURN -1
end


DECLARE @cMessage as VARCHAR(2000)
SET @cMessage = ''

DECLARE @cAlloy CHAR(12),
@cForm CHAR(2),
@nPieces INT,
@nThck DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),

@nWeight Numeric(9,1),
@nP_lb Numeric(8,2),
@nP_pc Numeric(9,2),
@nP_ft  Numeric(8,2),
@nCuts Numeric(6,0),
@cOtherFld CHAR(10),
@nOtherP Numeric(8,2),
@nLotP Numeric(8,2),
	
@nQ_P	Money,
@nQ_QTY	Money,
@nQ_PU	TinyInt,
@nQ_Total	Money,
	
@nS_P	Money,
@nS_QTY	Money,
@nS_PU	TinyInt,
@cInqNumP CHAR(9)

IF @ID > 0
	SELECT @cAlloy = Alloy,
		@cForm = Form,
		@nPieces = Pieces,
		@nThck = Thck,
		@nSize2 = Sz2,
		@nSize3 =Sz3,

		@nWeight = [Weight],
		@nP_lb = P_LB,
		@nP_pc = P_PC,
		@nP_ft = P_Ft,
		@nCuts = Cuts,
		@cOtherFld = OtherFld,
		@nOtherP = OtherP,
		@nLotP = LotP,
	
		@nQ_P = Q_P,
		@nQ_QTY	= Q_QTY,
		@nQ_PU = Q_PU,
		@nQ_Total = Q_Total,
	
		@nS_P = S_P,
		@nS_QTY	= S_QTY,
		@nS_PU = S_PU,
		@cInqNumP = InqNumP
	FROM dbo.AllQuotes WHERE ID=@ID


IF @nS_QTY <= 0
	SET @nS_QTY = dbo.f_Calc_Acct_QTY( @cAlloy, @cForm, @nPieces, @nThck, @nSize2, @nSize3, @cOtherFld )

DECLARE @nFeet Money = 0
SET @nFeet = 
	CASE WHEN dbo.f_GetForm_use3rdDim( @cForm ) = 1
	THEN (@nPieces * @nSize3 / 12) 
	ELSE (@nPieces * @nSize2 / 12) 	
	END


IF @nQ_P <= 0
begin
	PRINT 'No nQ_P';
	Print 'Caclulating nQ_P';
	--dbo.f_GetWeight(1000,'L605','10',.125,36,0)  --174.6
	--dbo.f_Calc_Acct_QTY(Alloy,Form,Pieces,Thck,Sz2,Sz3,OtherFld)


	DECLARE @nAcct_QTY Money

	SET @nAcct_QTY  = 
		CASE WHEN @cOtherFld = 'Per Inch' THEN @nFeet*12 ELSE 
		 CASE WHEN @cOtherFld = 'Per kg' THEN dbo.f_GetWeight(@nPieces,@cAlloy,@cForm,@nThck,@nSize2,@nSize3)/2.205 ELSE 
		  CASE WHEN @nS_PU = 1 THEN dbo.f_GetWeight(@nPieces,@cAlloy,@cForm,@nThck,@nSize2,@nSize3) ELSE 
		   CASE WHEN @nS_PU = 2 THEN @nFeet ELSE
			CASE WHEN @nS_PU = 3 THEN @nPieces ELSE
			 CASE WHEN @nS_PU = 4 THEN 1 ELSE
			  CASE WHEN @nS_PU = 5 THEN  @nFeet*12 ELSE
			   CASE WHEN @nS_PU = 6 THEN dbo.f_GetWeight(@nPieces,@cAlloy,@cForm,@nThck,@nSize2,@nSize3)/2.205 ELSE
				CASE WHEN @nS_PU = 7 THEN @nFeet/3.281 END
			   END
			  END
			 END
			END
		   END 
		  END 
		 END
		END
end

--*nQ_P = Get_Qoute_P(nPieces,cAlloy,cForm,nThck,nSz2,nSz3,nWeight,nP_lb,nP_pc,nP_ft,nLotP,cOtherFld,nOtherP, gnConnHandle)

DECLARE @nSigDim TinyInt = 0
SET @nSigDim = dbo.f_getSigDim(@cForm)

DECLARE @isLBonSz2 BIT
SELECT @isLBonSz2 = case when LBSonSZ2=1 then 1 when LBSonSZ3 = 1 then 1 else 0 end 
	FROM dbo.Forms WITH(NOLOCK) 
	WHERE FormNumber = @cForm

--**********************************************************
IF @cOtherFld = "PER MR" OR @cOtherFld = "PER MTR" OR @cOtherFld = "$/MTR" OR @cOtherFld = "$/MR"
begin
	SET @nQ_PU = 7
--*	cQ_PU = "$/Mtr"
	SET @nQ_P  = @nOtherP 
	
	
	IF @nFeet > 0
	begin
		SET @nQ_QTY	= @nFeet * .0254
		SET @nQ_Total = @nOtherP * @nFeet * .0254
	end
	ELSE
		SET @nQ_Total = -1
	
end

--**********************************************************
IF @cOtherFld LIKE '%PER KG%' OR @cOtherFld LIKE '%/KG%' 
begin
	SET @nQ_PU = 6
	SET @nQ_P  = @nOtherP 
	
	IF @nOtherP > 0
	begin

		IF @isLBonSz2 = 1
		begin
			PRINT 'Pounds are entered in a Sz2 or Sz3 fld and should be mutliplied by PC'
			SET @nQ_QTY = @nWeight/2.2 * IIF(@nPieces<1,1,@nPieces) 
		end
		ELSE
		begin
			SET @nQ_QTY	= @nWeight/2.2
			SET @nQ_Total = @nOtherP * @nQ_QTY
		end

	end
	ELSE
		SET @nQ_Total = -1
end

--**********************************************************
IF @cOtherFld like '%PER INCH%' OR @cOtherFld LIKE '%/IN%'
begin
	SET @nQ_PU = 5
	SET @nQ_P  = @nOtherP 
	
	IF @nSigDim = 2
		SET @nFeet = IIF(@nPieces<1,1,@nPieces) * @nSize2

	IF @nSigDim = 3 OR @nSigDim = 6
		SET @nFeet = IIF(@nPieces<1,1,@nPieces) * @nSize3
	
	IF @nFeet > 0
	begin
		SET @nQ_QTY	= @nFeet
		SET @nQ_Total = @nOtherP * @nQ_QTY
	end
	ELSE
		SET @nQ_Total = -1
	
end

--**********************************************************
IF @nLotP > 0
begin
	SET @nQ_PU = 4
	SET @nQ_P  = @nLotP 
	SET @nQ_QTY	= 1
	SET @nQ_Total = @nLotP 
end

--**********************************************************
IF @nP_lb > 0
begin
	SET @nQ_PU = 1
	SET @nQ_P  = @nP_lb
	
	IF @nWeight = 0
		SET @nWeight = dbo.f_GetWeight (@nPieces,@cAlloy,@cForm,@nThck,@nSize2,@nSize3)
		
		
	IF @nWeight > 0
		IF @isLBonSz2 = 1
		begin
			PRINT 'Pounds are entered in a Sz2 or Sz3 fld and should be mutliplied by PC'
			SET @nQ_QTY = @nWeight * IIF(@nPieces<1,1,@nPieces) 
		end
		ELSE
		begin
			SET @nQ_QTY	= @nWeight
			SET	@nQ_Total = @nP_lb * @nQ_QTY
		end
	ELSE
		SET @nQ_Total = -1
	
end

--**********************************************************
IF @nP_ft > 0
	begin
	SET @nQ_PU = 2
	Set @nQ_P =	@nP_ft
		
	IF @nSigDim = 2
		SET @nFeet = IIF(@nPieces<1,1,@nPieces) * @nSize2/12
	
	IF @nSigDim = 3 OR @nSigDim = 6
	begin
		IF @nPieces < 1
			SET @nPieces = 1

		SET @nFeet = @nPieces * @nSize3/12
	end
	
	IF @nFeet > 0
	begin
		SET @nQ_QTY	= @nFeet
		SET @nQ_Total = @nP_ft * @nFeet
	end
	ELSE
		SET @nQ_Total = -1
	
	end

--**********************************************************
IF @nP_Pc > 0
begin
	SET @nQ_PU = 3
	SET @nQ_P = @nP_pc

	IF @nPieces > 0
	begin
		SET @nQ_QTY	= @nPieces
		SET @nQ_Total = @nP_Pc * @nPieces
	end
	ELSE
		SET @nQ_Total = -1
	
end
/*
OTHERWISE 
	 nQ_P	= 0
	 nQ_PU	= GetPUfromForm( cForm, nConn )
	 nQ_QTY = 0
	 nQ_Total = -1
	 
ENDCASE
*/

RETURN @ID
END




