,ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev WHERE SalesNum = SN.salesnum ),0) AS Ver
,ISNULL((SELECT MAX([Ver]) FROM dbo.Sales_No_Chng WHERE SalesNum = SN.salesnum ),0) AS Chng
,SN.salesnum,SN.cncld,SN.cmplt,SN.ShopRecv,SN.Changing,SN.itemtot 
,SN.salesrep,SN.shippay,SN.shiproute
,S.SOitem,S.ItemSale,S.ItemCost,ISNULL(S.Hold,0) AS Hold
,AQ.Company,dbo.f_Descript(AQ.Alloy,AQ.CC,AQ.Form,AQ.Thck,AQ.Sz2,AQ.Sz3,AQ.Q_QTY,AQ.RandLen) AS Descript
FROM dbo.Sales_No SN 
INNER JOIN dbo.Sales S ON SN.salesnum = S.SalesNum
INNER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
WHERE SN.cncld = 0 
AND SN.cmplt = 0 --AND SN.cmplt = 1
AND ( ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev  WHERE SalesNum = SN.salesnum ) ,0)
OR ISNULL(SN.Amendment,0) < ISNULL((SELECT MAX([Ver]) FROM dbo.Sales_No_Chng WHERE SalesNum = SN.salesnum  ) ,0) )

