-- =============================================
-- Author:		David Kirchner
-- Create date: 2017 09 11
-- Description:	Returns successful ColdWork logs
-- =============================================
ALTER PROCEDURE [dbo].[p_Get_CW] 
	@cAlloy char(12),
	@cCC CHAR(1),
	@cCL CHAR(1),
	@nfSize Decimal(9,3)
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	--DECLARE @Alloy CHAR(12) = 'HPA N60', @CC CHAR(1) = '7', @CL CHAR(1) = '3', @nfSize Decimal(9,3) = 1.25
	-- EXEC dbo.p_Get_CW @cAlloy,@cCC,@cCL,@nfSize
	-- EXEC dbo.p_Get_CW 'HPA N60','7','3',1.25
	-- EXEC dbo.p_Get_CW 'HPA N60','7','1',1.25
	-- EXEC dbo.p_Get_CW 'HPA N60','7','2',1.25

	DECLARE @sql VarChar(MAX)
		
DECLARE @MinUTS AS INT
DECLARE @MinYld AS INT
DECLARE @MinEL AS TinyINT
DECLARE @MinRA AS TinyINT
DECLARE @DiaMax AS NUMERIC(9,3)
DECLARE @UTS_Max AS INT
DECLARE @Yld_Max AS INT

SELECT @MinUTS = ISNULL(UTS,0)
	,@MinYld = ISNULL(Yld,0)
	,@MinEL = ISNULL(EL,0)
	,@MinRA = ISNULL(RA,0) 
	,@DiaMax = ISNULL(DiaMax,0)
	,@UTS_Max = ISNULL(UTS_Max,0)
	,@Yld_Max = ISNULL(YLD_Max,0)
	FROM dbo.AlloyCodeLevel WHERE 
		Alloy = @cAlloy AND CC = @cCC AND CL = @cCL



	SET @sql ='SELECT G.sSize ';
	SET @sql = @sql+',CASE WHEN G.GFMSize>0 THEN G.GFMsize ELSE SQRT(((3.14156*G.sSize*G.sSize/4) - ( (3.14156*G.sSize*G.sSize/4) * Cast(G.ColdWork AS Numeric(4,2))))*4/3.14156) END AS CalcGFMsize ';
	SET @sql = @sql+' ,G.fSize,G.ColdWork '
	SET @sql = @sql+',l.UTS AS UTS_max, l.Yld AS YLD_max, l.EL AS EL_max, l.RA AS RA_max, l.Spec , l.RC AS RC_max, l.BHN AS BHN_max'
	SET @sql = @sql+',l.DiaMax'

	SET @sql = @sql+',G.Tensile ,G.Yield ,G.Elongation ,G.Red_Area ,G.RockWell ,G.BHN '
	SET @sql = @sql+',G.Tensile2,G.Yield2,G.Elongation2,G.Red_Area2,G.RockWell2,G.BHN2'
	SET @sql = @sql+',G.Tensile3,G.Yield3,G.Elongation3,G.Red_Area3,G.RockWell3,G.BHN3'
	SET @sql = @sql+',G.Tensile4,G.Yield4,G.Elongation4,G.Red_Area4,G.RockWell4,G.BHN4'
	SET @sql = @sql+',G.Tensile5,G.Yield5,G.Elongation5,G.Red_Area5,G.RockWell5,G.BHN5'
	SET @sql = @sql+',G.Notes,G.Lot'
	SET @sql = @sql+',l.[Text]'
	SET @sql = @sql+'FROM dbo.GFMlog G '
	SET @sql = @sql+'INNER JOIN dbo.AlloyCodeLevel l ON G.AlloyName = l.Alloy '
			SET @sql = @sql+' AND l.CC = '''+@cCC+'''' ;
			SET @sql = @sql+' AND l.CL = '''+@cCL+'''';
			IF @MinUTS > 1
				SET @sql = @sql+' AND G.Tensile > (l.UTS+1)*1000 ';
			IF @MinYld > 1
				SET @sql = @sql+' AND G.Yield > (l.Yld+1)*1000 ';
			IF @MinEL > 1
				SET @sql = @sql+' AND G.Elongation > (l.EL+.5) ';
			IF @MinRA > 1
				SET @sql = @sql+' AND G.Red_Area > (l.RA+.5) ';
			IF @UTS_Max > 1
				SET @sql = @sql+' AND G.Tensile < (ISNULL(l.UTS_Max,999))*1000 ';
			IF @Yld_Max > 1
				SET @sql = @sql+' AND G.Yield < (ISNULL(l.Yld_Max,999))*1000 ';


	SET @sql = @sql+' WHERE G.AlloyName = '''+@cAlloy+'''' ;
	SET @sql = @sql+' AND ISNULL(G.sSize,0) > 0 ';
	SET @sql = @sql+' AND ISNULL(G.ColdWork,0) > 0 ';
	SET @sql = @sql+' AND ( fSize > '+CAST(@nfSize-.1 AS CHAR(10))+' AND fSize < '+CAST(@nfSize+.1 AS CHAR(10))+') ';
	
	SET @sql = @sql+' AND NOT (G.Notes LIKE ''%Hot%'' or G.Notes LIKE ''%From%'' OR G.Notes LIKE ''%HW %''  OR G.Notes LIKE ''%Anneal%'' ) ';
	SET @sql = @sql+' ORDER BY ColdWork,fSize '

	EXEC (@sql);

END
GO
