-- =============================================
-- Author:		David Kirchner
-- Create date: 2017 09 11
-- Description:	Returns Min,Avg,Max ColdWork
-- =============================================
ALTER PROCEDURE [dbo].[p_Get_CW_MAM] 
	@cAlloy char(12),
	@cCC CHAR(1),
	@cCL CHAR(1),
	@nfSize Decimal(9,3)
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

/*	DECLARE @cAlloy CHAR(12) = 'HPA N60'
	DECLARE @cCC CHAR(1) = '7'
	DECLARE @cCL CHAR(1) = '3'
	DECLARE @nfSize Decimal(9,3) = 1.25
	EXEC dbo.p_Get_CW_MAM @cAlloy,@cCC,@cCL,@nfSize
*/

	-- EXEC dbo.p_Get_CW_MAM 'HPA N60','7','3',1.25
	-- EXEC dbo.p_Get_CW_MAM 'HPA N60','7','2',1.25
DECLARE @sql VarChar(MAX)
		
DECLARE @MinUTS AS INT
DECLARE @MinYld AS INT
DECLARE @MinEL AS TinyINT
DECLARE @MinRA AS TinyINT
DECLARE @DiaMax AS NUMERIC(9,3)
DECLARE @UTS_Max AS INT
DECLARE @Yld_Max AS INT

SELECT @MinUTS = ISNULL(UTS,0)
	,@MinYld = ISNULL(Yld,0)
	,@MinEL = ISNULL(EL,0)
	,@MinRA = ISNULL(RA,0) 
	,@DiaMax = ISNULL(DiaMax,0)
	,@UTS_Max = ISNULL(UTS_Max,0)
	,@Yld_Max = ISNULL(YLD_Max,0)
	FROM dbo.AlloyCodeLevel WHERE 
		Alloy = @cAlloy AND CC = @cCC AND CL = @cCL


	SET @sql ='SELECT '
	SET @sql = @sql+' CAST( AVG(T.sSize) AS Numeric(9,3) ) AS AvgSS '
	SET @sql = @sql+',CAST(MIN(t.MinCW)*100 AS SmallInt) AS MinCW '
	SET @sql = @sql+',CAST(AVG(t.AvgCW)*100 AS SmallInt) AS AvgCW '
	SET @sql = @sql+',dbo.f_CC_CL_Median_Cw('''+@cAlloy+''','''+@cCC+''','''+@cCL+''','''+CAST(@nfSize+.1 AS CHAR(10))+''') as Median '
	SET @sql = @sql+',CAST(Max(t.MaxCW)*100 AS SmallInt) AS MaxCW '
	SET @sql = @sql+',MIN(t.DiaMax) AS DiaMax '
	SET @sql = @sql+',SUM(t.CNTD) AS CNTD '
	SET @sql = @sql+' FROM '
		SET @sql = @sql+' ('
		SET @sql = @sql+'SELECT G.sSize ';
		SET @sql = @sql+' ,MIN(G.ColdWork) AS MinCW ';
		SET @sql = @sql+' ,CAST(AVG(G.ColdWork) AS Decimal(9,3)) AS AvgCW ';
		SET @sql = @sql+' ,Max(G.ColdWork) AS MaxCW ';
		SET @sql = @sql+' ,MIN(l.DiaMax) AS DiaMax ';
		SET @sql = @sql+' ,COUNT(*) AS CNTD ';
		SET @sql = @sql+' FROM dbo.GFMlog G ';
		SET @sql = @sql+' INNER JOIN dbo.AlloyCodeLevel l ON G.AlloyName = l.Alloy ';
			SET @sql = @sql+' AND l.CC = '''+@cCC+'''' ;
			SET @sql = @sql+' AND l.CL = '''+@cCL+'''';
			IF @MinUTS > 1
				SET @sql = @sql+' AND G.Tensile > (l.UTS+1)*1000 ';
			IF @MinYld > 1
				SET @sql = @sql+' AND G.Yield > (l.Yld+1)*1000 ';
			IF @MinEL > 1
				SET @sql = @sql+' AND G.Elongation > (l.EL+.5) ';
			IF @MinRA > 1
				SET @sql = @sql+' AND G.Red_Area > (l.RA+.5) ';
			IF @UTS_Max > 1
				SET @sql = @sql+' AND G.Tensile < (ISNULL(l.UTS_Max,999))*1000 ';
			IF @Yld_Max > 1
				SET @sql = @sql+' AND G.Yield < (ISNULL(l.Yld_Max,999))*1000 ';

		SET @sql = @sql+' WHERE G.AlloyName = '''+@cAlloy+'''' ;
		SET @sql = @sql+' AND ISNULL(G.sSize,0) > 0 ';
		SET @sql = @sql+' AND ISNULL(G.ColdWork,0) > 0 ';
		SET @sql = @sql+' AND ( fSize > '+CAST(@nfSize-.1 AS CHAR(10))+' AND fSize < '+CAST(@nfSize+.1 AS CHAR(10))+') ';
	
		SET @sql = @sql+' AND NOT (G.Notes LIKE ''%Hot%'' or G.Notes LIKE ''%From%'' OR G.Notes LIKE ''%HW %''  OR G.Notes LIKE ''%Anneal%'' ) ';
		SET @sql = @sql+' Group By sSize ';
		SET @sql = @sql+')  t ';

--	Print @sql
	EXEC (@sql);

END
GO
