ALTER PROCEDURE [dbo].[p_GetFullQuote2] 
(
@nPieces INT,
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),
@nForceBracket INT
)
AS
BEGIN
--EXEC dbo.[p_GetFullQuote] 1,'C-276','40','1',1,12,48,0
SET NOCOUNT ON

DECLARE @nPounds as FLOAT
SET @nPounds = 0
DECLARE @nCutPounds as DECIMAL(7,1)
SET @nCutPounds = 0
DECLARE @nSquarePounds AS DECIMAL(7,1)
SET @nSquarePounds = 0
DECLARE @nSawCurf as DECIMAL(4,3)
SET @nSawCurf = .300
DECLARE @cMessage as VARCHAR(2000)
SET @cMessage = ''

IF @nPieces < 1
	SET @nPieces = 1

DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
    SET @cMessage = RTRIM(@cMessage)+' Alloy Density not found!'
   END
ELSE
   SET @cMessage = RTRIM(@cMessage)+'Used Density of '+STR(@nDensity,5,3)
--Find Thickness used in PriceTable



IF @cForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		begin
		SET @nPounds = 0
		SET @nCutPounds = 0
		end
	ELSE
	IF @nThickness < 3
		begin
		SET @nPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSawCurf* @nPieces /4)
		end
	ELSE
	IF @nThickness < 6
		begin
		SET @nPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSawCurf* @nPieces /4)
		end
	ELSE
		begin
		SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSawCurf* @nPieces /4)
		end
   END
ELSE
IF @cForm = '11'
	begin 
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nThickness* 1.03* @nSawCurf* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '12'
	begin
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	SET @nCutPounds = @nDensity*@nThickness*@nThickness*.866*@nSawCurf* @nPieces
	end
ELSE
IF @cForm = '13' 
	begin
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nThickness* 1.03* @nSawCurf* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '20' 
	begin
	SET @nPounds = @nSize2* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '21' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '22' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '23' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '30' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '40' 
	begin
	SET @nPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nThickness* 1.015* @nSawCurf* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '60'
	begin
	SET @nPounds = @nDensity *@nSize3*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	SET @nCutPounds = @nDensity *@nSawCurf*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	end
ELSE
IF @cForm = '65'
   BEGIN
	DECLARE @nPipeWeight DECIMAL(9,4)
	SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
	IF @nPipeWeight = 0
		   SET @cMessage = RTRIM(@cMessage)+' Pipe Weight not found!'

	SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nPipeWeight* @nSawCurf* @nPieces )

   END
ELSE
IF @cForm = '80'
	begin
	--PI*R*R - Area of Disk
	SET @nPounds = (@nDensity * @nThickness * 1.03 * 3.14*(@nSize2/2)*(@nSize2/2) * @nPieces )

	--Weight of Square with Curf
	IF @nThickness > .5
		SET @nCutPounds = (@nDensity * @nThickness * 1.03 * (@nSize2+@nSawCurf) * (@nSize2+@nSawCurf) * @nPieces )
	ELSE
		SET @nCutPounds = (@nDensity * @nThickness * 1.03 * (@nSize2+.5) * (@nSize2+.5) * @nPieces )
	
	--Remove Inside Dia
	IF  @nSize3 > 0
		SET @nPounds = @nPounds - (@nDensity * @nThickness * 1.03 * 3.14*(@nSize3/2)*(@nSize3/2) * @nPieces )

	--Set CutPounds as Full Square minus Disk
	IF @nPounds < @nCutPounds 
		SET @nCutPounds = @nCutPounds - @nPounds
	
	SET @nSquarePounds = @nCutPounds + @nPounds
	end



DECLARE @lnSurcharge REAL
SELECT @lnSurcharge = dbo.Alloy_Surcharge(@cAlloy)


--SELECT @cAlloy='400',@cForm='10',@nStdSize=1,@nSize2=0,@nPounds=10
DECLARE @nStdSize DECIMAL(9,4)
SET @nStdSize = dbo.f_PriceTableStandard(@cAlloy,@cForm,@cCC,@nThickness)

--OUTPUT @nPrice, @nBracket, @cPTMessage, @bActivePrice
DECLARE @nPrice DECIMAL(9,2), @nBracket TinyInt, @cPTMessage CHAR(2000), @bActivePrice BIT

IF @cForm = '80'
	EXEC [dbo].[p_CalcPrice] @cAlloy,'40',@cCC,@nStdSize,@nSize2,@nSquarePounds,@nForceBracket, @nPrice OUTPUT,@nBracket OUTPUT, @cPTMessage OUTPUT, @bActivePrice OUTPUT
ELSE
	EXEC [dbo].[p_CalcPrice] @cAlloy,@cForm,@cCC,@nStdSize,@nSize2,@nPounds,@nForceBracket, @nPrice OUTPUT,@nBracket OUTPUT, @cPTMessage OUTPUT, @bActivePrice OUTPUT


DECLARE @CommSpec CHAR(20)
SET @CommSpec = dbo.f_PriceTable_CommSpec(@cAlloy,@cForm,@cCC,@nStdSize)

--Form 80 Retuns Pounds
SELECT @nPounds AS Pounds
, @lnSurcharge AS Surcharge
, @nCutPounds AS CutPounds
, @nPrice AS Price
, @nBracket AS Bracket
, @nStdSize AS StdSize
, @cAlloy AS StdAlloy
, @nDensity AS Density
, @CommSpec AS CommonSpec
, @cMessage AS WeightMess
, @cPTMessage AS PriceMess
, @bActivePrice AS ActivePrice

END











GO
