ALTER PROCEDURE [dbo].[p_GetFullQuoteDisc] 
(
@nPieces INT
,@cAlloy char(12)
,@cForm CHAR(2)
,@cCC CHAR(1)
,@nThickness DECIMAL(11,4)
,@nSize2 DECIMAL(10,3)
,@nSize3 DECIMAL(10,3)
,@nForceBracket INT
,@cCustID CHAR(20)
)
AS
BEGIN

/*
DECLARE @Pc INT = 1
DECLARE @Alloy CHAR(12) = 'HPA N50'
Declare @Form CHAR(2) = '10'
DECLARE @CC CHAR(1) = '1'
DECLARE @Thck NUMERIC(10,4) = 1.75
Declare @Sz2 NUMERIC(9,3) = 144
DECLARE @Sz3 NUMERIC(9,3) = 0
DECLARE @nForceBracket TINYINT = 0
DECLARE @CustID CHAR(10) = ''
EXEC dbo.[p_GetFullQuoteDisc] @Pc,@Alloy,@Form,@CC,@Thck,@Sz2,@Sz3,@nForceBracket,@CustID
*/

--EXEC dbo.[p_GetFullQuote] 1,'C-276','40','1',1,12,48,0,'CustomerID'
--Called from FoxPro Quotes or Web Service

--Returns:
-- @nPounds= Total Quanity. Pounds, PC or feet.
-- @lnSurcharge= Current Alloy Surcharge.
-- @nCutPounds= Weight lost to chopping off.
-- @nPrice= Price per Quantity.
-- @nBracket= Pricing Bracket used.
-- @nStdSize= Pricing table standard size used.
-- @cAlloy= Pricing table standard alloy used.
-- @nDensity= Density of alloy.
-- @CommSpec= Common Spec.
-- @cMessage= Weight Message.
-- @cPTMessage= Price Message.
-- @bActivePrice= Active Price.

SET NOCOUNT ON

DECLARE @nTestPounds as float(53)
DECLARE @nPounds as REAL
SET @nPounds = 0
DECLARE @nCutPounds as REAL
SET @nCutPounds = 0
DECLARE @nDiskWeight AS REAL
SET @nDiskWeight = 0
DECLARE @nSawCurf as DECIMAL(4,3)
SET @nSawCurf = .300
DECLARE @cMessage as VARCHAR(2000)
SET @cMessage = ''


IF @nPieces < 1
	SET @nPieces = 1

DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
    SET @cMessage = RTRIM(@cMessage)+' Alloy Density not found!'
   END
ELSE
   SET @cMessage = '' 
-- SET @cMessage = RTRIM(@cMessage)+'Used Density of '+STR(@nDensity,5,3)

--Find Thickness used in PriceTable

IF @cForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		begin
		SET @nPounds = 0
		SET @nCutPounds = 0
		end
	ELSE
	IF @nThickness < .2
		begin
		SET @nTestPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			SET @nCutPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSawCurf* @nPieces /4)
			end
		end
	ELSE
		IF @nThickness < 1
		begin
		SET @nTestPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			SET @nCutPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSawCurf* @nPieces /4)
			end
		end
	ELSE
		IF @nThickness < 3
		begin
		SET @nTestPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			SET @nCutPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSawCurf* @nPieces /4)
			end
		end
	ELSE
	IF @nThickness < 6
		begin
		SET @nPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSawCurf* @nPieces /4)
		end
	ELSE
		begin
		SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSawCurf* @nPieces /4)
		end
   END
ELSE
IF @cForm = '11'
	begin 
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nThickness* 1.03* @nSawCurf* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '12'
	begin
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	SET @nCutPounds = @nDensity*@nThickness*@nThickness*.866*@nSawCurf* @nPieces
	end
ELSE
IF @cForm = '13' 
	begin
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nThickness* 1.03* @nSawCurf* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '20' 
	begin
	SET @nPounds = @nSize2* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '21' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '30' 
	begin
	SET @nPounds = @nSize3* @nPieces 
	SET @nCutPounds = 0
	end
ELSE
IF @cForm = '40'
	begin
	SET @nTestPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
		SET @nCutPounds = (@nDensity* @nThickness* 1.015* (@nSize2+@nSawCurf)*(@nSize3+@nSawCurf)* @nPieces ) - @nPounds
		end
	end
ELSE
IF @cForm = '50' 
	begin
	SET @nTestPounds = (@nDensity* @nThickness* 1* @nSize2* @nSize3* @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (@nDensity* @nThickness* 1* @nSize2* @nSize3* @nPieces )
		SET @nCutPounds = (@nDensity* @nThickness* 1* (@nSize2+@nSawCurf)*(@nSize3+@nSawCurf)* @nPieces ) - @nPounds
		end
	end
ELSE
IF @cForm = '60'
	begin
	SET @nPounds = @nThickness*3.14*@nSize2*@nSize3*@nDensity*@nPieces 
	SET @nCutPounds = @nThickness*3.14*@nSize2*.3*@nDensity*@nPieces 
	--SET @nPounds = @nDensity *@nSize3*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	--SET @nCutPounds = @nDensity *@nSawCurf*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	end
ELSE
IF @cForm = '65'
   BEGIN

	DECLARE @nPipeWeight DECIMAL(9,6)
	SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
	IF @nPipeWeight = 0
		   SET @cMessage = RTRIM(@cMessage)+' Pipe Weight not found!'

	SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	SET @nCutPounds = (@nDensity* @nPipeWeight* @nSawCurf* @nPieces )

   END
ELSE
IF @cForm = '80'
	begin

	--Weight of Square with Curf
	SET @nPounds = (@nDensity * @nThickness * 1.015 * (@nSize2+.5) * (@nSize2+.5) * @nPieces )
	
	--Actual Weight
	SET @nDiskWeight = (@nDensity * @nThickness * 1.015 * 3.14*(@nSize2/2)*(@nSize2/2) * @nPieces )

	IF  @nSize3 > 0
	   SET @nDiskWeight = @nDiskWeight - (@nDensity * @nThickness * 1.015 * 3.14*(@nSize3/2)*(@nSize3/2) * @nPieces )

	--Set CutPounds as Full Square minus Disk
	SET @nCutPounds = @nPounds - @nDiskWeight

	end
ELSE
IF @cForm = '96'
	begin
	--SLAB
	SET @nTestPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2*1.05* @nSize3* @nPieces )
		SET @nCutPounds = (@nDensity* @nThickness* 1.05* (@nSize2*1.05)*(@nSize3+@nSawCurf)* @nPieces ) - @nPounds
		end
	end
ELSE
IF @cForm = '97' 
   BEGIN
	--Billet

	SET @nTestPounds = (POWER(@nThickness* 1.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (POWER(@nThickness* 1.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		SET @nCutPounds = (POWER(@nThickness* 1.005,2)* 3.23 * @nDensity* @nSawCurf* @nPieces /4)
		end
   END
ELSE
IF @cForm = '98'
	begin
	--RCS
	SET @nTestPounds = (@nDensity* @nThickness* 1.05* @nThickness* 1.05* @nSize2*  @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = @nDensity* @nThickness* 1.05* @nThickness* 1.05* @nSize2*  @nPieces 
		SET @nCutPounds = ( @nDensity* @nThickness* 1.05* @nThickness* 1.05* (@nSize2+@nSawCurf)*  @nPieces )- @nPounds
		end
	end
ELSE
IF @cForm = '99'
	begin
	--INGOT
	SET @nTestPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
		SET @nCutPounds = (@nDensity* @nThickness* 1.05* (@nSize2+@nSawCurf)*(@nSize3+@nSawCurf)* @nPieces ) - @nPounds
		end
	end
	
--*****************************************************


IF @nPounds > 9999999.9
	SET @nPounds = 9999999.9

DECLARE @lnSurcharge REAL
SELECT @lnSurcharge = dbo.f_Alloy_Surcharge(@cAlloy)

--*****************************************************

--SELECT @cAlloy='400',@cForm='10',@nStdSize=1,@nSize2=0,@nPounds=10
DECLARE @nStdSize DECIMAL(9,4)
SET @nStdSize = dbo.f_PriceTableStandard(@cAlloy,@cForm,@cCC,@nThickness)

--*****************************************************

DECLARE @nPrice DECIMAL(11,2), @nBracket TinyInt, @cPTMessage CHAR(2000), @bActivePrice BIT

--Form 80 Retuns Pounds
IF @cForm = '80'
	EXEC [dbo].[p_CalcPrice] @cAlloy,'40',@cCC,@nStdSize,@nSize2,@nPounds,@nForceBracket
	, @nPrice OUTPUT,@nBracket OUTPUT, @cPTMessage OUTPUT, @bActivePrice OUTPUT
ELSE
	EXEC [dbo].[p_CalcPrice] @cAlloy,@cForm,@cCC,@nStdSize,@nSize2,@nPounds,@nForceBracket
	, @nPrice OUTPUT,@nBracket OUTPUT, @cPTMessage OUTPUT, @bActivePrice OUTPUT

IF @nPounds = 9999999.9
	SET @cMessage = RTRIM(@cMessage) + ' Pounds were reduced to a MAXIMUM of 9999999.9'

DECLARE @CommSpec CHAR(20)
SET @CommSpec = dbo.f_PriceTable_CommSpec(@cAlloy,@cForm,@cCC,@nStdSize)

--*****************************************************
DECLARE @nCustDiscount Numeric(3,2)
SET @nCustDiscount = dbo.f_Customer_Discount(@cCustID)

IF @nCustDiscount >= .01 AND @nCustDiscount <= .15
	SET @nPrice = @nPrice * (1-@nCustDiscount)
ELSE
	SET @nCustDiscount = 0
	

--*****************************************************



SELECT @nPounds AS Pounds
, @lnSurcharge AS Surcharge
, @nCutPounds AS CutPounds
, @nPrice AS Price
, @nBracket AS Bracket
, @nStdSize AS StdSize
, @cAlloy AS StdAlloy
, @nDensity AS Density
, @CommSpec AS CommonSpec
, @cMessage AS WeightMess
, @cPTMessage AS PriceMess
, @bActivePrice AS ActivePrice
, @nCustDiscount AS Discount

END



