-- =============================================
-- Author:		Sean Lykins
-- Create date: 8/22/2011
-- Description:	HpaEmailErrorsServiceP2
-- =============================================
ALTER PROCEDURE [dbo].[p_GetLatestEmailErrors]
	@mailItemID int = 0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	--SELECT DISTINCT CASE WHEN L.description LIKE '%recipient invalid domain%' THEN 'recipient invalid domain' WHEN L.description LIKE '%Service not available%' THEN 'Service not available' WHEN L.description LIKE '%Authentication required%' THEN 'Authentication required' WHEN L.description LIKE '% Message sending error%' THEN 'Comcast Message sending error' WHEN L.description LIKE '%Too many sessions opened%' THEN 'Too many sessions opened' WHEN L.description LIKE '%Object reference not set to an instance of an object%' THEN 'not set to an instance of an object.' WHEN L.description LIKE '%Cannot send mails to mail server%' THEN 'Cannot send mails to mail server' WHEN L.description LIKE '%No such host is known%' THEN 'No such host is known' WHEN L.description LIKE '%No connection could be made because the target machine actively refused it%' THEN 'the target machine actively refused it' WHEN L.description LIKE '%party did not properly respond after a period of time, or established connection failed because connected host has failed to respond%' THEN 'connected host has failed to respond' ELSE '*'+RIGHT(L.description,35) END AS [Descript], Items.recipients, Items.subject,  Items.send_request_date, Items.send_request_user, Items.mailitem_id FROM MSDB.dbo.sysmail_event_log L , MSDB.dbo.sysmail_faileditems items WHERE L.event_type = 'error' AND L.mailitem_id = items.mailitem_id AND items.mailitem_id > @mailItemID
	SELECT L.description
		, Items.recipients
		, Items.subject
		, Items.body
		, Items.send_request_date
		, Items.send_request_user
		, Items.mailitem_id 
		, Items.profile_id
--		, Failed.sent_account_id
		FROM MSDB.dbo.sysmail_event_log L
		INNER JOIN MSDB.dbo.sysmail_faileditems items ON L.mailitem_id = items.mailitem_id
--		INNER JOIN [msdb].[dbo].[sysmail_faileditems] Failed ON L.mailitem_id = Failed.mailitem_id
		WHERE L.event_type = 'error'
		AND items.mailitem_id > @mailItemID
		ORDER BY send_request_date DESC
END

