-- =============================================
-- Author:		Brandon S. van de Venter
-- Create date: 11/16/2016
-- Description:	Returns Location as Unknown, Windfall, Tipton, Direct, Blind, Service, RemoteStock
-- =============================================
ALTER PROCEDURE [dbo].[p_GetLocation] 
	-- Add the parameters for the stored procedure here
	@S_P_WO_WOD VARCHAR(3),
    @OrderNumber VARCHAR(12),
	@Loc VARCHAR(15) out
AS
BEGIN

DECLARE @result VARCHAR(15) = ''

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	IF (LTRIM(RTRIM(@S_P_WO_WOD))) like 'S'
		BEGIN
				select @result = p.Location from (Select CASE ISNULL( i.ProcLoc, (CASE ISNULL(i.form,'') 
					WHEN '20' THEN 'Windfall' 
					WHEN '22' THEN 'Windfall' 
					WHEN '23' THEN 'Windfall' 
					WHEN '40' THEN 'Windfall'
					WHEN '50' THEN 'Windfall'
					WHEN '51' THEN 'Windfall'
					WHEN '80' THEN 'Windfall' 
					WHEN '10' THEN 'Tipton' 
					WHEN '12' THEN 'Tipton' 
					WHEN '60' THEN 'Tipton'	
					WHEN '65' THEN 'Tipton' 
					WHEN '90' THEN 'Tipton' 
					WHEN '97' THEN 'Tipton' 
					WHEN '98' THEN 'Tipton' 
					WHEN '99' THEN 'Tipton' 
					ELSE 
						CASE  
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BJ%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%JB%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%JOHN%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BRIAN%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BB%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%EL%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%WR%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%RT%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%WAYNE%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%ES%' THEN 'Tipton' 
						ELSE 'Unknown' END END))
					WHEN 'W' THEN 'Windfall'
					WHEN 'T' THEN 'Tipton'
					ELSE 'Unknown' END
						 as Location
				FROM (
						SELECT a.form, s.ProcLoc
								,(SELECT TOP 1 psn.checkedby 
									FROM [dbo].[PackingSlip] ps
										LEFT OUTER JOIN [dbo].PackingSlip_No psn on psn.packingsli = ps.Packingsli
									WHERE ps.SOitem = s.soitem) [checkedby]
						FROM	[dbo].Sales_No AS SN 
								LEFT OUTER JOIN [dbo].Sales AS S ON SN.salesnum = S.salesnum 
								LEFT OUTER JOIN [dbo].SoldAddr AS SA ON SN.psoldaddr = SA.soldcode
								INNER JOIN [dbo].AllQuotes a ON a.soitem = S.soitem
						WHERE	RTRIM(LTRIM(s.SOitem)) = RTRIM(LTRIM('91621-03'))
						) i) p
		END

	ELSE IF (LTRIM(RTRIM(@S_P_WO_WOD))) like 'P'
		BEGIN
				select @result = p.Location from (Select CASE ISNULL(i.ShipWhere, 0) 
					WHEN 1 THEN 'Tipton' 
					WHEN 2 THEN 'Direct' 
					WHEN 3 THEN 'Blind' 
					WHEN 4 THEN 'Service'
					WHEN 5 THEN 'Windfall'
					WHEN 6 THEN 'RemoteStock'
					ELSE 
						CASE  
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BJ%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%JB%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%JOHN%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BRIAN%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%BB%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%EL%' THEN 'Windfall' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%WR%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%RT%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%WAYNE%' THEN 'Tipton' 
						WHEN UPPER(ISNULL(checkedby,'')) LIKE '%ES%' THEN 'Tipton' 
						ELSE 'Unknown' END END as Location
				FROM (
						SELECT PO.ShipWhere
								,(SELECT TOP 1 psn.checkedby 
									FROM [dbo].[PackingSlip] ps
										LEFT OUTER JOIN [dbo].PackingSlip_No psn on psn.packingsli = ps.Packingsli
									WHERE ps.SOitem = PO.POitem) [checkedby]
						FROM	[dbo].PurchaseOrder AS PO 
								INNER JOIN [dbo].AllQuotes a ON a.POitem = PO.POitem
						WHERE	RTRIM(LTRIM(PO.POitem)) = RTRIM(LTRIM(@OrderNumber))
						) i) p
		END

	ELSE IF (LTRIM(RTRIM(@S_P_WO_WOD))) like 'WOD'
		BEGIN
				select @result = p.Location from (Select CASE ISNULL(i.form,'') 
					WHEN '20' THEN 'Windfall' 
					WHEN '22' THEN 'Windfall' 
					WHEN '23' THEN 'Windfall' 
					WHEN '40' THEN 'Windfall'
					WHEN '50' THEN 'Windfall'
					WHEN '51' THEN 'Windfall'
					WHEN '80' THEN 'Windfall' 
					WHEN '10' THEN 'Tipton' 
					WHEN '12' THEN 'Tipton' 
					WHEN '60' THEN 'Tipton'	
					WHEN '65' THEN 'Tipton' 
					WHEN '90' THEN 'Tipton' 
					WHEN '97' THEN 'Tipton' 
					WHEN '98' THEN 'Tipton' 
					WHEN '99' THEN 'Tipton' 
					ELSE 'Unknown' END as Location
				FROM (
						SELECT  wod.fForm as form
						FROM	[dbo].WorkOrder_Detail as wod
						WHERE	wod.WO_Detail = @OrderNumber
						) i) p
		END

	ELSE IF (LTRIM(RTRIM(@S_P_WO_WOD))) like 'WO'
		BEGIN
				select @result = p.Location from (Select CASE ISNULL(i.form,'') 
					WHEN '20' THEN 'Windfall' 
					WHEN '22' THEN 'Windfall' 
					WHEN '23' THEN 'Windfall' 
					WHEN '40' THEN 'Windfall'
					WHEN '50' THEN 'Windfall'
					WHEN '51' THEN 'Windfall'
					WHEN '80' THEN 'Windfall' 
					WHEN '10' THEN 'Tipton' 
					WHEN '12' THEN 'Tipton' 
					WHEN '60' THEN 'Tipton'	
					WHEN '65' THEN 'Tipton' 
					WHEN '90' THEN 'Tipton' 
					WHEN '97' THEN 'Tipton' 
					WHEN '98' THEN 'Tipton' 
					WHEN '99' THEN 'Tipton' 
					ELSE 'Unknown' END as Location
				FROM (
						SELECT  wo.sForm as form
						FROM	[dbo].WorkOrder as wo
						WHERE	wo.WO = @OrderNumber
						) i) p
		END

	if (@result = '')
		BEGIN 
			select @Loc = 'Unknown'
		END
	ELSE
		BEGIN
			select @Loc = @result
		END
END


