-- =============================================
-- Author:		Sean Lykins
-- Create date: 2015 01 16
-- Description:	Given the dimensions and weight desired, calculate the numbers of pieces required
-- =============================================
ALTER PROCEDURE [dbo].[p_GetPieces] 
	-- Add the parameters for the stored procedure here
	@nPounds DECIMAL,
	@nAlloy char(12),
	@nForm CHAR(2),
	@nThickness DECIMAL(11,4),
	@nSize2 DECIMAL(10,3),
	@nSize3 DECIMAL(10,3)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
DECLARE @nDensity DECIMAL(11,4) = IsNull(dbo.AlloyDensity( dbo.AlloyName(@nAlloy) ),0)
	,@nPieces as DECIMAL(11,4) = 0
	,@AdditionalThickness DECIMAL(11,4) = .001
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
   END
ELSE
IF @nForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		begin
		SET @nPounds = 0
		end
	ELSE
	IF @nThickness < .2
		begin
		SET @AdditionalThickness = .001
		end
	ELSE IF @nThickness < 1
		begin
		SET @AdditionalThickness = .005
		end
	ELSE IF @nThickness < 3
		begin
		SET @AdditionalThickness = .01
		end
	ELSE IF @nThickness < 6
		begin
		SET @AdditionalThickness = .020
		end
	ELSE
		begin
		SET @AdditionalThickness = .032
		end
	--SET @nPounds = (POWER(@nThickness + @AdditionalThickness,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
	SET @nPieces = @nPounds*4/(POWER(@nThickness + .005,2)* 3.23 * @nDensity* @nSize2)
   END
ELSE
IF @nForm = '11'
	begin 
	--SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nPieces = @nPounds/(@nDensity* @nThickness* 1.03* @nSize2* @nSize3)
	end
ELSE
IF @nForm = '12'
	begin
	--SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	SET @nPieces = @nPounds/(@nDensity*@nThickness*@nThickness*.866*@nSize2)
	end
ELSE
IF @nForm = '13' 
	begin
	--SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces)
	SET @nPieces = @nPounds /(@nDensity* @nThickness* 1.03* @nSize2* @nSize3)
	end
ELSE
IF @nForm = '20' 
	begin
	--SET @nPounds = @nSize2* @nPieces 
	SET @nPieces = @nPounds / @nSize2 
	end
ELSE
IF @nForm = '21' 
	begin
	--SET @nPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
	--TIG Cans
	SET @nPieces = @nSize3 / @nPounds
	end
ELSE
IF @nForm = '30' 
	begin
	--SET @nPounds = @nSize3* @nPieces 
	SET @nPieces = @nPounds / @nSize3 
	end
ELSE
IF @nForm = '40'
	begin
	--SET @nPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
	SET @nPieces = @nPounds / (@nDensity* @nThickness* 1.015* @nSize2* @nSize3)
	end
ELSE
IF @nForm = '50' 
	begin
	--SET @nPounds = (@nDensity* @nThickness* 1* @nSize2* @nSize3* @nPieces )
	SET @nPieces = @nPounds / (@nDensity* @nThickness* 1* @nSize2* @nSize3)
	end
ELSE
IF @nForm = '60'
	begin
	--SET @nPounds = @nThickness*3.14*@nSize2*@nSize3*@nDensity*@nPieces 
	SET @nPieces = @nPounds / (@nThickness*3.14*@nSize2*@nSize3*@nDensity)
	end
ELSE
IF @nForm = '65'
   BEGIN

	DECLARE @nPipeWeight DECIMAL(9,6)
	SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)

	--SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	SET @nPieces = @nPounds / (@nDensity* @nPipeWeight* @nSize3)

   END
ELSE
IF @nForm = '80'
	begin

	--Weight of Square with Curf
	SET @nPounds = (@nDensity * @nThickness * 1.015 * (@nSize2+.5) * (@nSize2+.5) * @nPieces )
	
	end
ELSE
IF @nForm = '96'
	begin
	--SLAB
	--SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2*1.05* @nSize3* @nPieces )
	SET @nPieces = @nPounds / (@nDensity* @nThickness* 1.05* @nSize2*1.05* @nSize3)
	end
ELSE
IF @nForm = '97' 
   BEGIN
	--Billet
	--SET @nPounds = (POWER(@nThickness* 1.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
	SET @nPieces = @nPounds * 4 / (POWER(@nThickness* 1.005,2)* 3.23 * @nDensity* @nSize2)
   END
ELSE
IF @nForm = '98'
	begin
	--RCS
	--SET @nPounds = @nDensity* @nThickness* 1.05* @nThickness* 1.05* @nSize2*  @nPieces 
	SET @nPieces = @nPounds / (@nDensity* @nThickness* 1.05* @nThickness* 1.05* @nSize2)
	end
ELSE
IF @nForm = '99'
	begin
	--INGOT
	--SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
	SET @nPieces = @nPounds / (@nDensity* @nThickness* 1.05* @nSize2* @nSize3)
	end

--SELECT @nPieces AS Pieces
--, @nDensity AS Density
--, @AdditionalThickness AS AdditionalThickness

RETURN ERP_2.dbo.f_RoundUp(@nPieces,0)
--RETURN ROUND(@nPieces,0)
END


