ALTER PROCEDURE [dbo].[p_GetShipmentByMonth] 
(@nYear INT)
AS
BEGIN
--EXEC dbo.[p_GetShipmentByMonth] 2002

SET NOCOUNT ON
--Pass the year to start report from (2002).
--Pass a negative to show that many years (-4) will run last 4 years.
IF ISNULL(@nYEAR,0) < 0
	SET @nYear=YEAR( GetDate()+(365*@nYEAR) ) 
	
--If no number was passed, set to 2002,  before 2002 totals are inacurate.
SET @nYear = ISNULL(@nYear,2002)

--Check for Out of range years
IF @nYear < 2000 
	SET @nYear = 2002
	
IF @nYear > YEAR( GetDate())
	SET @nYear = YEAR( GetDate()) 

DECLARE @nNextYear INT
SET @nNextYear = YEAR( GETDATE() )+1

CREATE TABLE #SalesByMonth ([Year] INT,[Jan] INT,[Feb] INT,[Mar] INT,[Apr] INT,[May] INT,[Jun] INT,[Jul] INT,[Aug] INT,[Sep] INT,[Oct] INT,[Nov] INT,[Dec] INT)

INSERT INTO #SalesByMonth
SELECT [Year],[Jan],[Feb],[Mar],[Apr],[May],[Jun],[Jul],[Aug],[Sep],[Oct],[Nov],[Dec]
 FROM ( 
 SELECT YEAR(Shipped) AS [Year]
, CAST([cmplt] AS INT) AS Cmplte
, (CASE MONTH(Shipped)
WHEN 1 THEN 'Jan' WHEN 2 THEN 'Feb' WHEN 3 THEN 'Mar' WHEN 4 THEN 'Apr'
WHEN 5 THEN 'May' WHEN 6 THEN 'Jun' WHEN 7 THEN 'Jul' WHEN 8 THEN 'Aug'
WHEN 9 THEN 'Sep' WHEN 10 THEN 'Oct' WHEN 11 THEN 'Nov' WHEN 12 THEN 'Dec' END
 )AS [Month]
 FROM dbo.Sales
 WHERE YEAR(Shipped) >= @nYear
 AND ISNULL(Cncld,0) < 1
) AS salesByMonth
 PIVOT( SUM([cmplte]) FOR [Month] IN
([Jan],[Feb],[Mar],[Apr],[May],[Jun],
[Jul],[Aug],[Sep],[Oct],[Nov],[Dec])
) AS Total_Shipments
 ORDER BY [Year] DESC


CREATE TABLE #SalesByMonthOnTime ([Year] INT,[Ja1] INT,[Fe1] INT,[Mr1] INT,[Ap1] INT,[My1] INT,[Jn1] INT
,[Jl1] INT,[Au1] INT,[Se1] INT,[Oc1] INT,[No1] INT,[De1] INT)

INSERT INTO #SalesByMonthOnTime 
SELECT [Year],[Ja1],[Fe1],[Mr1],[Ap1],[My1],[Jn1],[Jl1],[Au1],[Se1],[Oc1],[No1],[De1]
 FROM (
 SELECT YEAR(Shipped) AS [Year]
, (CASE 
	WHEN ([Shipped] <= [ShipDue] AND ISNULL(ShipOn,0) = 0) THEN 1
 	WHEN ([Shipped] >= [ShipDue] AND ISNULL(ShipOn,0) = 1) THEN 1
 ELSE 0
 END) AS [Good]
 , (CASE MONTH(ShipDue)
 WHEN 1 THEN 'Ja1' WHEN 2 THEN 'Fe1' WHEN 3 THEN 'Mr1' WHEN 4 THEN 'Ap1'
 WHEN 5 THEN 'My1' WHEN 6 THEN 'Jn1' WHEN 7 THEN 'Jl1' WHEN 8 THEN 'Au1' 
 WHEN 9 THEN 'Se1' WHEN 10 THEN 'Oc1' WHEN 11 THEN 'No1' WHEN 12 THEN 'De1' END
  )AS [MonthGood]
 FROM dbo.Sales
 WHERE YEAR(Shipped) >= @nYear
 AND ISNULL(Cncld,0) < 1 
 AND ISNULL(ShipOn,0) < 1
) AS SalesByMonth
 PIVOT( SUM([Good]) FOR [MonthGood] IN
([Ja1],[Fe1],[Mr1],[Ap1],[My1],[Jn1],
 [Jl1],[Au1],[Se1],[Oc1],[No1],[De1])
 ) AS On_Time_Shipments 
 ORDER BY [Year] DESC

CREATE TABLE #SalesByMonth2days ([Year] INT,[Ja2] INT,[Fe2] INT,[Mr2] INT,[Ap2] INT,[My2] INT,[Jn2] INT
,[Jl2] INT,[Au2] INT,[Se2] INT,[Oc2] INT,[No2] INT,[De2] INT)

INSERT INTO #SalesByMonth2days 
SELECT [Year],[Ja2],[Fe2],[Mr2],[Ap2],[My2],[Jn2],[Jl2],[Au2],[Se2],[Oc2],[No2],[De2]
 FROM (
 SELECT YEAR(Shipped) AS [Year]
 , (CASE 
 	WHEN ([Shipped] <= [ShipDue]+2 AND ISNULL(ShipOn,0) = 0) THEN 1
 	WHEN ([Shipped] >= [ShipDue]-2 AND ISNULL(ShipOn,0) = 1) THEN 1 ELSE 0
 	END) AS [Good]
, (CASE MONTH(Shipped)
 WHEN 1 THEN 'Ja2' WHEN 2 THEN 'Fe2' WHEN 3 THEN 'Mr2' WHEN 4 THEN 'Ap2'
 WHEN 5 THEN 'My2' WHEN 6 THEN 'Jn2' WHEN 7 THEN 'Jl2' WHEN 8 THEN 'Au2'
 WHEN 9 THEN 'Se2' WHEN 10 THEN 'Oc2' WHEN 11 THEN 'No2' WHEN 12 THEN 'De2' END
  )AS [Monthwith5]
FROM dbo.Sales
WHERE YEAR(Shipped) >= @nYear
AND ISNULL(Cncld,0) < 1 
 ) AS salesByMonth
 PIVOT( 
 SUM([Good]) FOR [Monthwith5] IN
 ([Ja2],[Fe2],[Mr2],[Ap2],[My2],[Jn2],
 [Jl2],[Au2],[Se2],[Oc2],[No2],[De2])
 ) AS Within2Days
 ORDER BY [Year] DESC


CREATE TABLE #SalesByMonth7days ([Year] INT,[Ja5] INT,[Fe5] INT,[Mr5] INT,[Ap5] INT,[My5] INT,[Jn5] INT
,[Jl5] INT,[Au5] INT,[Se5] INT,[Oc5] INT,[No5] INT,[De5] INT)

INSERT INTO #SalesByMonth7days 
SELECT [Year],[Ja5],[Fe5],[Mr5],[Ap5],[My5],[Jn5],[Jl5],[Au5],[Se5],[Oc5],[No5],[De5]
 FROM (
 SELECT YEAR(Shipped) AS [Year]
, (CASE 
 	WHEN ([Shipped] <= [ShipDue]+7 AND ISNULL(ShipOn,0) = 0) THEN 1
 	WHEN ([Shipped] >= [ShipDue]-7 AND ISNULL(ShipOn,0) = 1) THEN 1	ELSE 0
 	END) AS [Good]
, (CASE MONTH(Shipped)
 WHEN 1 THEN 'Ja5' WHEN 2 THEN 'Fe5' WHEN 3 THEN 'Mr5' WHEN 4 THEN 'Ap5'
 WHEN 5 THEN 'My5' WHEN 6 THEN 'Jn5' WHEN 7 THEN 'Jl5' WHEN 8 THEN 'Au5'
 WHEN 9 THEN 'Se5' WHEN 10 THEN 'Oc5' WHEN 11 THEN 'No5' WHEN 12 THEN 'De5' END
  )AS [Monthwith5]
 FROM dbo.Sales
 WHERE YEAR(Shipped) >= @nYear
 AND ISNULL(Cncld,0) < 1
 ) AS salesByMonth
 PIVOT( 
 SUM([Good]) FOR [Monthwith5] IN
 ([Ja5],[Fe5],[Mr5],[Ap5],[My5],[Jn5],
 [Jl5],[Au5],[Se5],[Oc5],[No5],[De5])
 ) AS WithinWeek
ORDER BY [Year] DESC

CREATE TABLE #SalesByMonthRMA ([Year] INT,[JaR] INT,[FeR] INT,[MrR] INT,[AlR] INT,[MyR] INT,[JnR] INT
,[JlR] INT,[AuR] INT,[SeR] INT,[OcR] INT,[NoR] INT,[DeR] INT)

INSERT INTO #SalesByMonthRMA   
SELECT [Year],[JaR],[FeR],[MrR],[AlR],[MyR],[JnR],[JlR],[AuR],[SeR],[OcR],[NoR],[DeR]
 FROM (
 SELECT YEAR(Shipped) AS [Year]
, (CASE WHEN RMA_No > 0 THEN 1 ELSE 0 END) AS [RMA]
, (CASE MONTH(Shipped)
 WHEN 1 THEN 'JaR' WHEN 2 THEN 'FeR' WHEN 3 THEN 'MrR' WHEN 4 THEN 'AlR'
 WHEN 5 THEN 'MyR' WHEN 6 THEN 'JnR' WHEN 7 THEN 'JlR' WHEN 8 THEN 'AuR'
 WHEN 9 THEN 'SeR' WHEN 10 THEN 'OcR' WHEN 11 THEN 'NoR' WHEN 12 THEN 'DeR' END
 )AS [MonthRMA]
 FROM dbo.Sales
 WHERE YEAR(Shipped) >= @nYear
 ) AS salesByMonth
PIVOT( 
 SUM([RMA]) FOR [MonthRMA] IN
 ([JaR],[FeR],[MrR],[AlR],[MyR],[JnR],
 [JlR],[AuR],[SeR],[OcR],[NoR],[DeR])
 ) AS RMAPivot
ORDER BY [Year] DESC



	SELECT T.[Year],T.Jan,T.Feb,T.Mar,T.Apr,T.May,T.Jun,T.Jul,T.Aug,T.Sep,T.Oct,T.Nov,T.[Dec]
		,Ja1,Fe1,Mr1,Ap1,My1,Jn1,Jl1,Au1,Se1,Oc1,No1,De1
		,Ja2,Fe2,Mr2,Ap2,My2,Jn2,Jl2,Au2,Se2,Oc2,No2,De2
		,Ja5,Fe5,Mr5,Ap5,My5,Jn5,Jl5,Au5,Se5,Oc5,No5,De5
		,JaR,FeR,MrR,AlR,MyR,JnR,JlR,AuR,SeR,OcR,NoR,DeR
	FROM #SalesByMonth T, #SalesByMonthOnTime OT, #SalesByMonth2days W2D, #SalesByMonth7days WW, #SalesByMonthRMA R
	WHERE T.Year = OT.Year AND OT.Year = W2D.Year AND W2D.Year = WW.Year AND WW.Year = R.Year


END





