/****** Object:  StoredProcedure [dbo].[p_GetSpecificMonthlyQuotedTotal]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_GetSpecificMonthlyQuotedTotal]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_GetSpecificMonthlyQuotedTotal] AS' 
END
GO
-- =============================================
-- Author:		Brandon van de Venter, Sean Lykins, and David Kirchner
-- Create date: 06/19/2019
-- Description:	Gets the Quoted total for the month, with 7 day review.  Sales Shipped, cmplt, not cancld, sum Quoted price. 
-- Now used for 50 dollar, Million sales month
-- in HPA Chatter
-- UPDATES:
-- 07/29/2020 - Changed calculation from Sales.Quoted_Total to Sales.ItemSale
-- =============================================
ALTER PROCEDURE [dbo].[p_GetSpecificMonthlyQuotedTotal] 
	-- Add the parameters for the stored procedure here
	@ProcessDate datetime
AS
BEGIN
	SET NOCOUNT ON;

    -- EXEC dbo.[p_GetSpecificMonthlyQuotedTotal] '05/19/2019' -- 1466690.64	2019	5
    -- EXEC dbo.[p_GetSpecificMonthlyQuotedTotal] '04/19/2019' -- 1508873.15	2019	4
	-- EXEC dbo.[p_GetSpecificMonthlyQuotedTotal] '05/19/2025' --  164047.58	2025	5

--Simulair fields :Sales.ItemSale, Sales.PT_Total, Sales.Quoted_Total
/*
	--DECLARE @today DATETIME = GETDATE()
	DECLARE @thismonth int = MONTH(@ProcessDate)
	--,@thisday int = DAY(@ProcessDate)
	,@thisyear int = YEAR(@ProcessDate)
	
	SELECT SUM(Sales.ItemSale) AS Quoted_Total
	, @thisyear AS Year
	, @thismonth AS Month
	FROM dbo.Sales 
	WHERE ISNULL(Sales.SalesNum,0)>0 
	AND ISNULL(Sales.Cncld,0)=0  
	AND ISNULL(Sales.cmplt,0)=1 
	AND YEAR(SHIPPED) = @thisyear
	AND MONTH(SHIPPED) = @thismonth
*/
	--DECLARE @ProcessDate DATETIME = GETDATE()
	--DECLARE @YearMn INT = dbo.f_get_Year_Month( @ProcessDate )

	SELECT SUM( ISNULL(dbo.f_get_S_P_SOitem(SPS.SOitem) *  SPS.Acct_QTY,0) ) AS Quoted_Total
	--SUM( SPS.Acct_QTY ) AS Shipped_Total
	FROM dbo.Sales_PS SPS WITH(NOLOCK)
	WHERE SPS.Cncld = 0
	--AND dbo.[f_get_Year_Month](SPS.PS_Date) = @YearMn
	AND dbo.f_YearMn(SPS.PS_Date) = dbo.f_YearMn(@ProcessDate)
END
 
GO
