ALTER Procedure [dbo].[p_getStockLstCurrent] 
(
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@nThickness DECIMAL(9,4)
)

AS
BEGIN
--PRINT dbo.[p_getStockLstCurrent]('C-276','40','1',.5)
--EXEC dbo.[p_getStockLstCurrent] @cAlloy = '6B',@cForm = '10',@cCC = '1', @nThickness=1
--EXEC dbo.[p_getStockLstCurrent] @cAlloy = 'C-276',@cForm = '10',@cCC = '1', @nThickness=.5
--SET NOCOUNT ON



SELECT 
(SELECT ISNULL(SUM(mWeight),0) FROM dbo.StockLst_Master 
	WHERE Alloy = @cAlloy
	AND dbo.f_GetBasicStockForm(Form) = dbo.f_GetBasicStockForm(@cForm)
	AND dbo.f_GetCCSortValue(CC) = dbo.f_GetCCSortValue(@cCC)
	AND [Size] = dbo.[getStockLstStandardSize](@nThickness) ) as CurrentLbs,
(SELECT ISNULL(SUM(SP.Pweight),0)
	FROM dbo.StockLst_Process SP, dbo.StockLst_Detail SD, dbo.StockLst_Master SM 
	WHERE (Process_ID = 'INCOMING' OR Process_ID = 'PARTRECV')
	AND SP.ID_Detail = SD.ID_Detail
	AND SD.ID = SM.ID
	AND dbo.f_GetBasicStockForm(Form) = dbo.f_GetBasicStockForm(@cForm)
	AND dbo.f_GetCCSortValue(CC) = dbo.f_GetCCSortValue(@cCC)
	AND [Size] = dbo.[getStockLstStandardSize](@nThickness) ) AS Incoming,
(SELECT ISNULL(SUM(SP.Pweight),0)
	FROM dbo.StockLst_Process SP, dbo.StockLst_Detail SD, dbo.StockLst_Master SM 
	WHERE Process_ID = 'SELECTED'
	AND SP.ID_Detail = SD.ID_Detail
	AND SD.ID = SM.ID
	AND dbo.f_GetBasicStockForm(Form) = dbo.f_GetBasicStockForm(@cForm)
	AND dbo.f_GetCCSortValue(CC) = dbo.f_GetCCSortValue(@cCC)
	AND [Size] = dbo.[getStockLstStandardSize](@nThickness) ) AS StockSold

END


GO
