ALTER PROCEDURE [dbo].[p_GetWeight] 
(
@nPieces INT,
@cAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3)
)
AS

BEGIN
SET NOCOUNT ON
--EXEC dbo.p_Getweight 1,'C-276','40',1,12,48
--EXEC dbo.p_Getweight @nPieces, @cAlloy, @cForm, @nThickness, @nSize2 , @nSize3
--EXEC dbo.p_GetWeight          1,'HPA N60     ','97',    7.7500,   84.750,    0.000
--Returns @nPounds, Pounds Only
--Also see p_CALC_Weight
--also see dbo.f_GetWeight

SET NOCOUNT ON

DECLARE @nTestPounds as float(53)
DECLARE @nPounds as REAL
SET @nPounds = 0
DECLARE @nDiskWeight AS REAL
SET @nDiskWeight = 0

IF @nPieces < 1
	SET @nPieces = 1

DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
   END

--Find Thickness used in PriceTable

IF @cForm = '0' 
	SET @nPounds = 0

IF @cForm = '10' OR @cForm = '30' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		begin
		SET @nPounds = 0
		end
	ELSE
	IF @nThickness < .2
		begin
		SET @nTestPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		end
	ELSE
		IF @nThickness < 1
		begin
		SET @nTestPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.005,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		end
	ELSE
		IF @nThickness < 3
		begin
		SET @nTestPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		IF @nTestPounds > 9999999.9
			SET @nPounds = 9999999.9
		ELSE
			begin
			SET @nPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
			end
		end
	ELSE
	IF @nThickness < 6
		begin
		SET @nPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		end
	ELSE
		begin
		SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		end
   END
ELSE
IF @cForm = '11'
	begin 
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '12'
	begin
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	end
ELSE
IF @cForm = '13' 
	begin
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	end
ELSE
IF @cForm = '20' 
	begin
	SET @nPounds = @nSize2* @nPieces 
	end
ELSE
IF @cForm = '21' 
	begin
	SET @nPounds = @nSize3 * @nPieces 
	--SET @nPounds = (POWER(@nThickness+.001,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
	end
ELSE
IF @cForm = '22' 
	begin
	SET @nPounds = @nSize2* @nPieces 
	end
ELSE
IF @cForm = '23' 
	begin
	SET @nPounds = @nSize2* @nPieces 
	end
ELSE
IF @cForm = '40' OR @cForm = '90' OR @cForm = '91' OR @cForm = '95' OR @cForm = '96'
	begin
	SET @nTestPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
	IF @nTestPounds > 9999999.9
		SET @nPounds = 9999999.9
	ELSE
		begin
		SET @nPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
		end
	end
ELSE
IF @cForm = '51'
	begin 
	SET @nPounds = (@nSize3 * @nPieces)
	end
ELSE
IF @cForm = '52' 
	begin
	SET @nPounds = (@nSize3 * @nPieces)
	end
ELSE
IF @cForm = '53' 
	begin
	SET @nPounds = (@nSize3 * @nPieces)
	end
ELSE
IF @cForm = '60'
	begin
	SET @nPounds = @nThickness*3.14*@nSize2*@nSize3*@nDensity*@nPieces 
	end
ELSE
IF @cForm = '65'
   BEGIN

	DECLARE @nInchPipeWeight DECIMAL(9,6)
	SET @nInchPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
	SET @nPounds = @nInchPipeWeight * @nSize3*@nPieces 

   END
ELSE
IF @cForm = '80'
	begin

	--Actual Weight
	SET @nDiskWeight = (@nDensity * @nThickness * 1.015 * 3.14*(@nSize2/2)*(@nSize2/2) * @nPieces )

	IF  @nSize3 > 0
	   SET @nDiskWeight = @nDiskWeight - (@nDensity * @nThickness * 1.015 * 3.14*(@nSize3/2)*(@nSize3/2) * @nPieces )
	
	SET @nPounds = @nDiskWeight
	
	end
ELSE
IF @cForm = '97' or @cForm = '99'
	SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
ELSE
IF @cForm = '98'
	SET @nPounds = (@nDensity* @nThickness* 1.015* @nThickness* @nSize2* @nPieces )


IF @nPounds > 9999999.9
	SET @nPounds = 9999999.9


SELECT @nPounds AS [Weight]


END
/*
FormNumber	FormDescription
0 	no_form    
10	BAR        
11	FLAT BAR   
12	HEX BAR    
13	SQUARE BAR 
20	WIRE SPOOL 
21	TIG WIRE   
22	LOOSE COIL 
23	WIRE REEL  
30	COATED ELEC
40	PLATE      
50	SHEET      
51	STRIP      
52	COIL       
53	HOT BAND   
60	TUBING     
65	PIPE       
66	NIPPLE     
67	ELBOW      
68	TEE        
69	REDUCER    
70	FITTINGS   
71	COUPLING   
72	FLANGE     
75	FASTENER   
80	CUT DISK   
90	MACHINED   
91	CASTING    
95	FORGE      
96	SLAB       
97	BILLET     
98	RCS        
99	INGOT      
*/
--GRANT EXECUTE ON [dbo].[p_GetWeight] TO [WINDFALL\HPA]
GO
