ALTER PROCEDURE [dbo].[p_IND_Type]
(
@nIND_Type INT
)

AS
BEGIN
	SET NOCOUNT ON
	--EXEC dbo.p_IND_Type 3
	
	--Also see f_IND_Type, f_Is_IND_Complete_Type
	--Also See p_IND_Number, p_IND_Type

	DECLARE @Consumer BIT
	SET @Consumer = 0
	Declare @Competitor BIT
	SET @Competitor = 0
	DECLARE @Corrosion BIT
	SET @Corrosion = 0
	DECLARE @Wear BIT
	SET @Wear = 0
	DECLARE @HighTemp BIT
	SET @HighTemp = 0
	DECLARE @AeroSpace BIT
	SET @AeroSpace = 0
	DECLARE @Chemical BIT
	SET @Chemical = 0
	DECLARE @oil BIT
	SET @Oil = 0
	DECLARE @Pharm BIT
	SET @Pharm = 0
	DECLARE @Military BIT
	SET @Military = 0
	DECLARE @Nuclear BIT
	SET @Nuclear = 0
	DECLARE @Conversion BIT
	SET @Conversion = 0
	DECLARE @Service BIT
	SET @Service = 0
	DECLARE @Medical BIT
	SET @Medical = 0
	DECLARE @Fabricator BIT
	SET @Fabricator = 0
	DECLARE @Food BIT
	SET @Food = 0

	DECLARE @GovSub BIT
	SET @GovSub = 0
	DECLARE @Gov BIT
	SET @Gov = 0

	DECLARE @Hydro BIT
	SET @Hydro = 0

	DECLARE @nCurrentInt INT
	SET @nCurrentInt = @nIND_Type

	IF @nCurrentInt >= 262144
		begin
		SET @Hydro = 1
		SET @nCurrentInt = @nCurrentInt - 262144
		end
		
	IF @nCurrentInt >= 131072
		begin
		SET @Gov = 1
		SET @nCurrentInt = @nCurrentInt - 131072
		end
		
	IF @nCurrentInt >= 65536
		begin
		SET @GovSub = 1
		SET @nCurrentInt = @nCurrentInt - 65536
		end

	IF @nCurrentInt >= 32768
		begin
		SET @Food = 1
		SET @nCurrentInt = @nCurrentInt - 32768
		end

	IF @nCurrentInt >= 16384
		begin
		SET @Fabricator = 1
		SET @nCurrentInt = @nCurrentInt - 16384
		end

	IF @nCurrentInt >= 8192
		begin
		SET @Medical = 1
		SET @nCurrentInt = @nCurrentInt - 8192
		end

	IF @nCurrentInt >= 4096
		begin
		SET @Service = 1
		SET @nCurrentInt = @nCurrentInt - 4096
		end
		
	IF @nCurrentInt >= 2048
		begin
		SET @Conversion = 1
		SET @nCurrentInt = @nCurrentInt - 2048
		end
		
	IF @nCurrentInt >= 1024
		begin
		SET @Nuclear = 1
		SET @nCurrentInt = @nCurrentInt - 1024
		end
		
	IF @nCurrentInt >= 512
		begin
		SET @Military = 1
		SET @nCurrentInt = @nCurrentInt - 512
		end
		
	IF @nCurrentInt >= 256
		begin
		SET @Pharm = 1
		SET @nCurrentInt = @nCurrentInt - 256
		end
	
	IF @nCurrentInt >= 128
		begin
		SET @oil = 1
		SET @nCurrentInt = @nCurrentInt - 128
		end
		
	IF @nCurrentInt >= 64
		begin
		SET @Chemical = 1
		SET @nCurrentInt = @nCurrentInt - 64
		end
		
	IF @nCurrentInt >= 32
		begin
		SET @AeroSpace = 1
		SET @nCurrentInt = @nCurrentInt - 32
		end

	IF @nCurrentInt >= 16
		begin
		SET @HighTemp = 1
		SET @nCurrentInt = @nCurrentInt - 16
		end
		
	IF @nCurrentInt >= 8
		begin
		SET @Wear = 1
		SET @nCurrentInt = @nCurrentInt - 8
		end

	IF @nCurrentInt >= 4
		begin
		SET @Corrosion = 1
		SET @nCurrentInt = @nCurrentInt - 4
		end

	IF @nCurrentInt >= 2
		begin
		SET @Competitor = 1
		SET @nCurrentInt = @nCurrentInt - 2
		end

	IF @nCurrentInt >= 1
		begin
		SET @Consumer = 1
		SET @nCurrentInt = @nCurrentInt - 1
		end


	SELECT @Consumer AS Consumer
	, @Competitor AS Competitor
	, @Corrosion AS Corrosion
	, @Wear AS Wear
	, @HighTemp AS HighTemp
	, @AeroSpace AS AeroSpace
	, @Chemical AS Chemical
	, @Oil AS Oil
	, @Pharm AS Pharm
	, @Military AS Military
	, @Nuclear AS Nuclear
	, @Medical AS [Medical]
	, @Food AS [Food]
	, @Conversion AS Conversion
	, @Service AS [Service]
	, @Fabricator AS [Fabricator]
	, @Food AS [Food]
	, @GovSub AS [GOV_Sub]
	, @Gov AS [Government]
	, @Hydro AS [Hydro]
	
END


