/****** Object:  StoredProcedure [dbo].[P_IsAMS2750D]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[P_IsAMS2750D]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[P_IsAMS2750D] AS' 
END
GO
ALTER Procedure [dbo].[P_IsAMS2750D]
(
@HpaName VARCHAR(50)
)

AS
BEGIN
--EXEC dbo.p_IsAMS2750D 'A1'

DECLARE @CountUse INT
SELECT @CountUse = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName
IF @CountUse < 1
	begin
	SELECT 1 AS [Valid], 'Meets AMS 2750D, No History found.' AS [Why], 0 AS [CountUse], 0 AS [Days], 0 AS [HighTemp]
	RETURN	 
	end

DECLARE @HighTemp INT
SELECT @HighTemp = MAX(Temp) FROM dbo.ThermalCoupleUse  WHERE HPAName = @HpaName

DECLARE @Above2300 INT
SELECT @Above2300 = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName AND Temp >= 2300
IF @Above2300 > 0
	begin
	DECLARE @Above2300Use INT
	DECLARE @Above2300Hours INT
	SELECT @Above2300Use = COUNT(*), @Above2300Hours = SUM(Hours) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName 

	IF @Above2300Use >= 1
		begin
		SELECT 0 AS [Valid], 'Above 2300, 1 times use.' AS [Why], @Above2300Use AS [CountUse], (@Above2300Hours/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end
	end

DECLARE @Above2200 INT
SELECT @Above2200 = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName AND Temp >= 2200 --AND Temp < 2300
IF @Above2200 > 0
	begin
	DECLARE @Above2200Use INT
	DECLARE @Above2200Hours INT
	SELECT @Above2200Use = COUNT(*), @Above2200Hours = SUM(Hours) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName --AND Temp >= 2200 --AND Temp < 2300

	IF @Above2200Use >= 10
		begin
		SELECT 0 AS [Valid], 'Above 2200, 10 times use.' AS [Why], @Above2200Use AS [CountUse], (@Above2200Use/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN 
		end
	end

DECLARE @Above1801 INT
SELECT @Above1801 = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName AND Temp >= 1801
IF @Above1801 > 0
	begin
	DECLARE @Above1801Use INT
	DECLARE @Above1801Hours INT
	SELECT @Above1801Use = COUNT(*), @Above1801Hours = SUM(Hours) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName --AND Temp >= 1801 --AND Temp < 2200

	IF @Above1801Use >= 30
		begin
		SELECT 0 AS [Valid], 'Above 1801, 30 times use.' AS [Why], @Above1801Use AS [CountUse], (@Above1801Use/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN  
		end
		
	IF @Above1801Hours >= 30*24
		begin
		SELECT 0 AS [Valid], 'Above 1801, 30 day use.' AS [Why], @Above1801Use AS [CountUse], (@Above1801Use/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN   
		end
	end

DECLARE @Above1200 INT
SELECT @Above1200 = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName AND Temp >= 1200
IF @Above1200 > 0
	begin
	DECLARE @Above1200Use INT
	DECLARE @Above1200Hours INT
	SELECT @Above1200Use = COUNT(*), @Above1200Hours = SUM(Hours) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName --AND Temp >= 1200 --AND Temp < 1801

	IF @Above1200Use >= 180
		begin
		SELECT 0 AS [Valid],  'Above 1200, 180 times use.' AS [Why], @Above1200Use AS [CountUse], (@Above1200Use/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end

	IF @Above1200Hours >= 90*24
		begin
		SELECT 0 AS [Valid],  'Above 1200, 90 day use.'  AS [Why], @Above1200Use AS [CountUse], (@Above1200Use/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end
	end

DECLARE @Below1200 INT
SELECT @Below1200 = COUNT(*) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName --AND Temp < 1200
IF @Below1200 > 0
	begin
	DECLARE @Below1200Use INT
	DECLARE @Below1200Hours INT
	SELECT @Below1200Use = COUNT(*), @Below1200Hours = SUM(Hours) FROM dbo.ThermalCoupleUse WHERE HPAName = @HpaName --AND Temp < 1200

	IF @Below1200Use >= 270
		begin
		SELECT 0 AS [Valid],  'Below 1200, 270 times use.' AS [Why], @Below1200Use AS [CountUse], (@Below1200Hours/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end
	ELSE
	IF @Below1200Hours >= 90*24
		begin
		SELECT 0 AS [Valid],  'Below 1200, 90 day use.' AS [Why], @Below1200Use AS [CountUse], (@Below1200Hours/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end
	ELSE
		begin
		SELECT 1 AS [Valid], 'Meets AMS 2750D.' AS [Why], @Below1200 AS [CountUse], (@Below1200Hours/24) AS [Days], @HighTemp AS [HighTemp]
		RETURN
		end

	end
END

--GRANT EXECUTE ON [dbo].[P_IsAMS2750D] TO [WINDFALL\HPA]
GO
