DECLARE @GoodTable BIT
SET @GoodTable = 0

IF @TBL='S'
	SET @GoodTable = 1
ELSE
	IF @TBL='B'
		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1
		ELSE
			IF @TBL='SH'
				SET @GoodTable = 1
