		,[InvoiceValue]
		,[LiveCheck]
		,[AccountingCheck]
		,[Quarantine]
		,[S_QTY]
		,[S_P]
		,[S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		   )
		SELECT 
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,'' AS [Length]
		,CASE when [S_PU] = 1 then @mS_QTY else 0 end   AS [Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,'' AS [InvCheck]
		, @ID AS [ID]
		--,[ID_Detail]
		,0 AS [ReceivingID]
		,0 AS [InvoiceValue]
		,0 AS [LiveCheck]
		,0 AS [AccountingCheck]
		,0 AS [Quarantine]
		, @mS_QTY AS [S_QTY]
		,[S_P]
		,ISNULL(@mS_QTY* S_P,0) AS [S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		FROM dbo.Stocklst_Detail WITH(NOLOCK)
			WHERE ID_Detail = @ID_Detail

