		,[WO]
		FROM dbo.Ar_Stocklst_Detail_History WITH(NOLOCK)
			WHERE ID_Detail = @ID_Detail
			AND [WHAT] = 'DELETE'

	IF @TBL='BH'
	  INSERT INTO dbo.WIPLst_Detail (
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,[Length]
		,[Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,[InvCheck]
		,[ID]
		--,[ID_Detail]
		,[ReceivingID]
		,[InvoiceValue]
		,[LiveCheck]
		,[AccountingCheck]
		,[Quarantine]
		,[S_QTY]
		,[S_P]
		,[S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		   )
		SELECT 
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,'' AS [Length]
		,CASE when [S_PU] = 1 then @mS_QTY else 0 end   AS [Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,'' AS [InvCheck]
		, @ID AS [ID]
		--,[ID_Detail]
		,0 AS [ReceivingID]
		,0 AS [InvoiceValue]
		,0 AS [LiveCheck]
		,0 AS [AccountingCheck]
		,0 AS [Quarantine]
		, @mS_QTY AS [S_QTY]
		,[S_P]
		,ISNULL(@mS_QTY* S_P,0) AS [S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		FROM dbo.Ar_Brokerlst_Detail_History WITH(NOLOCK)
			WHERE ID_Detail = @ID_Detail
			AND [WHAT] = 'DELETE'

	IF @TBL='WH'
	  INSERT INTO dbo.WIPLst_Detail (
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,[Length]
		,[Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,[InvCheck]
		,[ID]
		--,[ID_Detail]
		,[ReceivingID]
		,[InvoiceValue]
		,[LiveCheck]
		,[AccountingCheck]
		,[Quarantine]
		,[S_QTY]
		,[S_P]
		,[S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		   )
		SELECT 
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,'' AS [Length]
		,CASE when [S_PU] = 1 then @mS_QTY else 0 end   AS [Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,'' AS [InvCheck]
		, @ID AS [ID]
		--,[ID_Detail]
		,0 AS [ReceivingID]
		,0 AS [InvoiceValue]
		,0 AS [LiveCheck]
		,0 AS [AccountingCheck]
		,0 AS [Quarantine]
		, @mS_QTY AS [S_QTY]
		,[S_P]
		,ISNULL(@mS_QTY* S_P,0) AS [S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		FROM dbo.Ar_WIPlst_Detail_History WITH(NOLOCK)
			WHERE ID_Detail = @ID_Detail
			AND [WHAT] = 'DELETE'

	  SELECT SCOPE_IDENTITY()

	END
  

  --GRANT EXECUTE ON [dbo].[p_Lst_Detail_Clone_WIP] TO [WINDFALL\HPA] AS [dbo];



GO
