ALTER PROCEDURE [dbo].[p_Lst_Restore_Master]
	@ID		INT,
	@TBL	Char(1)

AS
Set NoCount On

--EXEC dbo.p_Lst_Restore_Master @ID=     12265,@TBL='B'
--Restore ANY TBL_Master from where History 'DELETE'
-- Return 0 if bad ID or TBL, -1 if History not found
-- Returns same ID if Worked

DECLARE @GoodTable BIT
SET @GoodTable = 0

IF @TBL='S'
	SET @GoodTable = 1
ELSE
	IF @TBL='B'
		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1
--		ELSE
--			PRINT 'dbo.p_Lst_Restore_Master: Unkown TBL'



IF @GoodTable = 0 OR @ID = 0
	SELECT 0
ELSE
	begin
	
--	BEGIN TRANSACTION Restore_Master ;  

	-- Tracking Inserted ID to ignore problems with "@@ROWCOUNT"
	DECLARE @RestoredIdTable TABLE (ID int);

	IF @TBL='S'
	  begin

		--PRINT 'TBL=S'

	  SET IDENTITY_INSERT dbo.StockLst_Master ON; 

	  INSERT INTO dbo.Stocklst_Master (
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		,[MWeight]
		,[Specs]
		,[Heat]
		,[Lot]
		,[Paid]
		,[PO_item]
		,[PoDueDate]
		,[Mill]
		,[StkDate]
		,[History]
		,[Num]
		,[POStatus]
		,[BrandName],[MillTrace]
		,[FROM_ID]
		,[Melt]
		,[ID]
		,[mS_QTY]
		,[WO_Detail]
		,[ProjID]
		   )
		-- OUTPUT THE INSERTED ROW ID INTO THE TEMP TABLE
		OUTPUT INSERTED.[ID] INTO @RestoredIdTable(ID)
		SELECT 
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		, 0 AS [MWeight]
		,[Specs]
		,[Heat]
		,[lot]
		,[Paid]
		,[PO_item]
		,[PoDueDate]
		,[Mill]
		,GetDate() AS [StkDate]
		,'Recovered' AS  [History]
		,[Num]
		,[POStatus]
		,[BrandName],[MillTrace]
		,[FROM_ID]
		,[Melt]
		,[ID]
		,0 AS [mS_QTY]
		,[WO_Detail]
		,[ProjID]
		FROM dbo.Ar_Stocklst_Master_History WITH(NOLOCK) 
			WHERE ID = @ID
			AND [WHAT] = 'DELETE'

	  SET IDENTITY_INSERT dbo.StockLst_Master OFF; 

	    -- Check if we inserted any rows
		IF (SELECT COUNT(ID) FROM @RestoredIdTable) = 0 --@@ROWCOUNT=0
			SELECT -1
		ELSE
			begin
			SELECT SCOPE_IDENTITY()
		
			UPDATE dbo.Ar_Stocklst_Master_History SET [WHAT] = 'RECOVERED'
				WHERE ID = @ID
				AND [WHAT] = 'DELETE'
			end
		end

	IF @TBL='B'
	  begin
		
		--PRINT 'TBL=B'

	  SET IDENTITY_INSERT dbo.BrokerLst_Master ON; 

	  INSERT INTO dbo.BrokerLst_Master (
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		,[MWeight]
		,[Specs]
		,[Heat]
		,[Lot]
		,[Paid]
		,[PO_item]
		,[PoDueDate]
		,[Mill]
		,[StkDate]
		,[History]
		,[Num]
		,[POStatus]
		,[BrandName],[MillTrace]
		,[FROM_ID]
		,[Melt]
		,[ID]
		,[mS_QTY]
		,[WO_Detail]
		,[ProjID]
		   )
		-- OUTPUT THE INSERTED ROW ID INTO THE TEMP TABLE
		OUTPUT INSERTED.[ID] INTO @RestoredIdTable(ID)
		SELECT 
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		, 0 AS [MWeight]
		,[Specs]
		,[Heat]
		,[lot]
		,[Paid]
		,[PO_item]
		,[PoDueDate]
		,[Mill]
		,GetDate() AS [StkDate]
		,'Recovered' AS  [History]
		,[Num]
		,[POStatus]
		,[BrandName],[MillTrace]
		,[FROM_ID]
		,[Melt]
		,[ID]
		, 0 AS [mS_QTY]
		,[WO_Detail]
		,[ProjID]
		FROM dbo.Ar_BrokerLst_Master_history WITH(NOLOCK) 
			WHERE ID = @ID
			AND [WHAT] = 'DELETE'

		

		SET IDENTITY_INSERT dbo.BrokerLst_Master OFF; 

		-- Check if we inserted any rows
		IF (SELECT COUNT(ID) FROM @RestoredIdTable) = 0 --@@ROWCOUNT=0
			SELECT -1
		ELSE
			begin
			SELECT SCOPE_IDENTITY()

			UPDATE dbo.Ar_BrokerLst_Master_history SET [WHAT] = 'RECOVERED'
				WHERE ID = @ID
				AND [WHAT] = 'DELETE'
			end
		end

	IF @TBL='W'
	  begin
		
		--PRINT 'TBL=W'

	  SET IDENTITY_INSERT dbo.WIPLst_Master ON; 

	  INSERT INTO dbo.WIPlst_Master (
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		,[MWeight]
		,[Specs]
		,[Heat]
		,[Lot]
		,[Paid]
		,[PO_item]
		,[PoDueDate]
		,[Mill]
		,[StkDate]
		,[History]
		,[Num]
		,[POStatus]
		,[BrandName],[MillTrace]
		,[FROM_ID]
		,[Melt]
		,[ID]
		,[mS_QTY]
		,[WO_Detail]
		,[ProjID]
		   )
		-- OUTPUT THE INSERTED ROW ID INTO THE TEMP TABLE
		OUTPUT INSERTED.[ID] INTO @RestoredIdTable(ID)
		SELECT 
		 [Alloy]
		,[Form]
		,[CC]
		,[CL]
		,[Size]
		,[Cond]
		, 0 AS MWeight
		,[Specs]
		,[Heat]
		,[lot]
