ALTER PROCEDURE [dbo].[p_Maintenance_]

AS

--EXEC dbo.p_Sales_Summary
--ran from Maintenace Plans: ERP_1 Backup saturday
--Should rename to Weekly Maintance

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)
DECLARE @CntSO INT = 0


SELECT @CntSO = COUNT(*) FROM dbo.StockLst_Process SP
	LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
	WHERE ISNULL(S.cmplt,0)>0

IF @CntSO > 0
	BEGIN

	PRINT 'SO Complete with Process issue.'

	SELECT @Body = ('SELECT @CntSO = COUNT(*) FROM dbo.StockLst_Process SP'+CHAR(13)
		+' LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem'+CHAR(13)
		+'WHERE ISNULL(S.cmplt,0)>0'+CHAR(13)

		+' --Found a Process Problem.'+CHAR(13)
		+' on '+RTRIM(GETDATE())  
		+@@SERVERNAME+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Sales_Summary ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'SO Process Complete issue.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'


		DELETE FROM dbo.StockLst_Process WHERE ID_Detail_Process IN 
			(SELECT ID_Detail_Process 
			FROM dbo.StockLst_Process SP
			LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
			WHERE ISNULL(S.cmplt,0)>0 )

		END
RETURN
GO
