AS

--EXEC dbo.p_Maintenance_AQ_SalesNum_HPApo
--ran from Maintenace Plans: ERP_1 Backup daily

SET QUOTED_IDENTIFIER ON


---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = 'David.Kirchner@ERP_1s.com' --ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0

-----------------------------
-- Fix NoNoiseName

SELECT @CntSO = COUNT(*) FROM dbo.AllQuotes
	WHERE SalesNum > 0
	AND NoNoiseName IS NULL and LEN(Company)>1


