ALTER PROCEDURE [dbo].[p_Maintenance_BrokerLst_Detail]

AS

--EXEC dbo.p_Sales_Summary
--ran from Maintenace Plans: ERP_1 Backup saturday
--Should rename to Weekly Maintance

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0
DECLARE @ID INT = 0
DECLARE @ID_Detail INT = 0
-----------------------------
-- BrokerLst Detail Problem.
SET @CntSO = 0


SELECT @CntSO = COUNT(*)
 FROM dbo.Brokerlst_Detail 
 WHERE ID NOT IN (SELECT DISTINCT ID FROM dbo.BrokerLst_Master );

IF @CntSO > 0
	BEGIN

	PRINT 'BrokerLst_Detail without BrokerLst_Master ';

	--Get atleast one ID before delete.
	SELECT TOP 1 @ID = ISNULL(ID,0), @ID_Detail=ISNULL(ID_Detail,0)
		FROM dbo.BrokerLst_Detail 
		WHERE ID NOT IN (SELECT DISTINCT ID FROM dbo.BrokerLst_Master );

	SET @Body = 'BrokerLst_Detail without BrokerLst_Master '+CHAR(13);
	SET @Body=@Body+' Counted: '+CAST(@CntSO AS CHAR(10))+CHAR(13);

	SET @Body=@Body+'Top 1 ID= '+TRIM(CAST(ISNULL(@ID,0) AS CHAR(10)))+' ID_Detail='+TRIM(CAST(@ID_Detail AS CHAR(10)));
	SET @Body=@Body+' SELECT * FROM dbo.BrokerLst_Detail '+CHAR(13)
	SET @Body=@Body+' 	WHERE ID NOT IN '+CHAR(13)
	SET @Body=@Body+' 	(SELECT DISTINCT ID FROM dbo.Brokerlst_Master );'+CHAR(13)
	SET @Body=@Body+'Top Missing Master ID = '+ CAST(ISNULL(@ID,0) AS CHAR(10))+'. Only have the Detail'+CHAR(13)
	
	SET @Body=@Body+' on '+RTRIM(GETDATE())+'. '+@@SERVERNAME+CHAR(13)
	SET @Body=@Body+'Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_BrokerLst_Detail ' 		

	EXEC dbo.p_eMail_Send
		@FromEmail = @cEmailFrom, 
		@ToEmail = 'David.Kirchner@ERP_1s.com', 
		@SubjectEmail = 'BrokerLst_Detail without BrokerLst_Master.',
		@BodyEmail = @Body,
		@BodyType = 'TEXT'

	----------
	DECLARE @msg VARCHAR(250);
	DECLARE @query varchar(2048);
	DECLARE @cProfile_Name VarChar(50);

	/* SET @msg = 'Please refer to the attached spread sheet for the report.';  
	
	SET @query='SELECT *
		FROM dbo.Brokerlst_Detail 
		WHERE ID NOT IN 
		(SELECT DISTINCT ID FROM dbo.BrokerLst_Master);';

	SET @cProfile_Name = dbo.f_Get_profile_name('');

	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_BrokerLst_Detail'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_BrokerLst_Detail.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;
		*/
	----------

	DELETE
		FROM dbo.BrokerLst_Detail
		WHERE ID NOT IN (SELECT DISTINCT ID FROM dbo.BrokerLst_Master )

	END

---------------------------------------------

 --FROM dbo.Brokerlst_Detail 
 --WHERE ID NOT IN (SELECT DISTINCT ID FROM dbo.BrokerLst_Master )
SET @CntSO = 0

SELECT @CntSO = COUNT(*) 
	FROM dbo.BrokerLst_Master M
	WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D 
				 WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0

IF @CntSO > 0
	BEGIN

	PRINT 'BrokerLst_Master without BrokerLst_Detail'

/*	SELECT @Body = ('BrokerLst_Master without BrokerLst_Detail'+CHAR(13)
	 +' Counted: '+CAST(@CntSO AS CHAR(10))+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '+@@SERVERNAME+CHAR(13)
	 +'Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_BrokerLst_Detail ' )*/

	--Get atleast one ID before deleting
	SELECT TOP 1 @ID = ISNULL(ID,0)
		FROM dbo.BrokerLst_Master M
		WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D 
			 WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0 ;


	SET @Body = 'BrokerLst_Master without Detail'+CHAR(13);
	SET @Body=@Body+'Top 1 ID= '+TRIM(CAST(ISNULL(@ID,0) AS CHAR(10)))+CHAR(13);
	SET @Body=@Body+'SELECT (SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D WHERE D.ID = M.ID ) AS ID_Detail'+CHAR(13)
	 +',M.* '+CHAR(13)
	 +'			FROM dbo.BrokerLst_Master M '+CHAR(13)
	 +'				WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D '+CHAR(13)
	 +'				WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0;'+CHAR(13)
	 +'Top Master ID with no Detail: '+ CAST(ISNULL(@ID,0) AS CHAR(10))+'.'+CHAR(13)
	 +'Deleted: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '+@@SERVERNAME+CHAR(13)
	 +'Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_BrokerLst_Detail ' ;
			

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'BrokerLst_Master without BrokerLst_Detail.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'

	---------------------------------------------------	
	/*
	SET @query='SELECT (SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D WHERE D.ID = M.ID ) AS ID_Detail
				,M.* 
				FROM dbo.BrokerLst_Master M
					WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D 
					WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0;';
	
	SET @msg = 'Please refer to the attached spread sheet for the report.'+CHAR(13)+@query;  

	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_BrokerLst_Detail'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='BrokerLst_Master_without_Detail.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;
	
	*/
	---------------------------------------------------	

	--SET QUOTED_IDENTIFIER OFF;

	--DELETE FROM dbo.Brokerlst_Master WHERE ID=@ID;
	UPDATE dbo.Brokerlst_Master SET History=LEFT('Lost Detail '+[History],20) 
			,Specs = LEFT('p_Maintenance_BrokerLst_Detail '+[Specs],160)  --Added 9/25/2025
			WHERE ID IN (SELECT DISTINCT M.ID 
			FROM dbo.BrokerLst_Master M 
				WHERE ISNULL((SELECT TOP 1 ID FROM dbo.BrokerLst_Detail D 
				WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0 );

	DELETE FROM dbo.BrokerLst_Master	WHERE ID in 
		(SELECT ID FROM dbo.BrokerLst_Master M
			WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D 
						WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0);

	--SET QUOTED_IDENTIFIER ON;

	END

-----------------------------
RETURN

