		, @nWO=ISNULL(sp.WO,0)
		, @nID_Detail = ISNULL(sp.ID_Detail,0)
		, @nID_Detail_Process = ISNULL(sp.ID_Detail_Process,0)
	FROM dbo.StockLst_Process sp
	inner join dbo.WorkOrder wo ON sp.WO = wo.WO AND sp.WO > 0
	WHERE sp.Process_ID = 'SELECTED  '
	AND (WO.Cncld = 1 OR WO.Cmplt = 1 OR WO.StkConsumed = 1 )

	SELECT @Body = '@InqNumP '+@InqNumP+CHAR(13)
		+'@SOitem '+@SOitem+CHAR(13)+' '+dbo.f_HTML_link_SOitem(@SOitem)+CHAR(13)
		+'@Process_ID '+@Process_ID+CHAR(13)
		+'@WO '+CAST(@nWO AS CHAR(10) )+CHAR(13)	
		+'@ID_Detail '+CAST(@nID_Detail AS CHAR(10) )+CHAR(13)
		+'@ID_Detail_Process '+CAST(@nID_Detail_Process AS CHAR(10) )+CHAR(13)
		+CHAR(10)+CHAR(13)

	SELECT @Body = @Body+('SELECT sp.InqNumP,sp.Process_ID,sp.SOitem,sp.WO,sp.ID_Detail,sp.ID_Detail_Process'+CHAR(13)
		+', (SELECT COUNT(*) FROM dbo.StockLst_Process WHERE ID_Detail = sp.ID_Detail) AS Counted'+CHAR(13)
		+'FROM dbo.StockLst_Process sp'+CHAR(13)
		+'inner join dbo.WorkOrder wo ON sp.WO = wo.WO AND sp.WO > 0'+CHAR(13)
		+'WHERE sp.Process_ID = ''SELECTED  '' '+CHAR(13)
		+'AND (WO.Cncld = 1 OR WO.Cmplt = 1 OR WO.StkConsumed = 1 );'+CHAR(13)
		
		+' on '+RTRIM(GETDATE())  
		+@@SERVERNAME+' Agent Job _ERP_1  weekly dbo.p_Maintenance_Process_Complete ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Remove Completed WO Stock SELECTED Process.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'


		DELETE FROM dbo.StockLst_Process WHERE ID_Detail_Process IN 
		(SELECT SP.ID_Detail_Process
			FROM dbo.StockLst_Process sp
			inner join dbo.WorkOrder wo ON sp.WO = wo.WO AND sp.WO > 0
			WHERE sp.Process_ID = 'SELECTED  '
			AND (WO.Cncld = 1 OR WO.Cmplt = 1 OR WO.StkConsumed = 1 )
		);

	END

/*SELECT 
(SELECT COUNT(*) FROM dbo.StockLst_Process WHERE ID_Detail = sp.ID_Detail) AS Counted,
* FROM dbo.StockLst_Process SP
inner join dbo.WorkOrder_Detail WOD ON SP.WO_Detail = WOD.WO_Detail AND SP.WO_Detail > 0
WHERE SP.Process_ID = 'SELECTED  '
AND (WOD.fCncld = 1 OR WOD.fCmplt = 1 )*/

------------------------------
--SELECTED WO_Detail Complete
