---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = 'David.Kirchner@ERP_1s.com' --ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0

-----------------------------
-- Cancelled Problem.
-- Checks all tables
--p_Maintenance_Sales_Complete only check Sales to Sales_No


SELECT @CntSO = COUNT(*) FROM dbo.Sales_No SN 
	INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
	WHERE S.cncld = 1 AND S.Cmplt = 1
	AND SN.cncld =1  AND SN.cmplt=1
	AND NOT (ISNULL(S.RMA_No,0) > 0 or ISNULL(S.RMA_Detail,0) > 0)

IF @CntSO > 0
	BEGIN

	PRINT 'SO Cancelled and Complete issue.'
	DECLARE @SalesNum INT = 0

	SELECT TOP 1 @SalesNum = SN.SalesNum
		FROM dbo.Sales_No SN 
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
		WHERE S.cncld = 1 AND S.Cmplt = 1
		AND SN.cncld = 1 AND SN.cmplt = 1
		AND NOT (ISNULL(S.RMA_No,0) > 0 or ISNULL(S.RMA_Detail,0) > 0)

		SELECT @Body = ('SELECT SN.SalesNum,SN.cncld AS [SN cnc],SN.cmplt,S.SOitem,S.cncld AS [S cnc],S.cmplt,S.gs_cmplt'+CHAR(10)+CHAR(13)
	+',AQ.ShipDate AS [AQ ShipDate],AQ.Company,AQ.InqNumP, AQ.DescriptID'+CHAR(13)
	+',PS.Cancld AS [PS Cnc] --,PS.Descript AS [PS Desc]'+CHAR(10)+CHAR(13)
	+' ,ship.Cncld AS [Ship Cnc],ship.Complete AS [Ship Cmplt],ship.[When] AS [Ship When],ship.ShipVia'+CHAR(13)
	+' ,SNR.[When] AS [SNR When],SNR.Ver,SNR.Comment AS [SNR Comment] ,RMA_Detail.RMA_No'+CHAR(10)+CHAR(13)
	+',(SELECT TOP 1 Mess1 FROM dbo.NR_UserTrack WHERE Mess1 LIKE ''%Cancelled for SalesNum ''+LTRIM(CAST(113973 AS CHAR(10)) )+''%'') Track'+CHAR(13)
	+' ,S.RMA_No, S.RMA_Detail '+CHAR(10)+CHAR(13)
	+'  FROM dbo.Sales_No SN'+CHAR(10)+CHAR(13)
	+' INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum '+CHAR(10)+CHAR(13)
	+' INNER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem '+CHAR(10)+CHAR(13)
	+' INNER JOIN dbo.Ship ship ON S.SOitem = ship.SOitem '+CHAR(10)+CHAR(13)
	+' left outer join dbo.Sales_No_Rev SNR ON SN.SalesNum = SNR.SalesNum '+CHAR(10)+CHAR(13)
	+' LEFT OUTER JOIN dbo.RMA_Detail ON S.SOitem = RMA_Detail.so_item '+CHAR(10)+CHAR(13)
	+' LEFT OUTER JOIN dbo.PackingSlip PS ON S.SOitem = PS.SOitem '+CHAR(10)+CHAR(13)
	+' WHERE S.cncld = 1 AND S.Cmplt = 1  AND SN.cncld =1  AND SN.cmplt=1 AND NOT (ISNULL(S.RMA_No,0) > 0 or ISNULL(S.RMA_Detail,0) > 0) ORDER BY SN.SalesNum DESC;  '+CHAR(10)+CHAR(13)
	+' '+CHAR(13)
	+' --Found a Cancelled Problem. Sales to Sales_No:(Cmplt&Cncld) '+CHAR(10)+CHAR(13)
	+' --Fix a Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)
	+' --to fix: UPDATE dbo.Sales_No SET cmplt = 0 WHERE SalesNum = '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)
	+' --to fix: UPDATE dbo.Sales SET cmplt = 0 WHERE SalesNum = '+ CAST(@SalesNum AS CHAR(10))+' AND cmplt = 1 and cncld = 1'+CHAR(13)+CHAR(10)+CHAR(13)
		+' Counted:'+ CAST(@CntSO AS CHAR(10))+'.'
		+' on '+RTRIM(GETDATE()) +@@SERVERNAME+CHAR(10)+CHAR(13)
		+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Weekly ' )+CHAR(13)
		+' dbo.p_Maintenance_Sales_Cancel';

	EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'SO Cancelled and Complete issue.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'
	
		---------------
	DECLARE @cProfile_Name VarChar(50);
	SET @cProfile_Name = dbo.f_Get_profile_name('David Kirchner')

	/*
	DECLARE @msg VARCHAR(250);
	DECLARE @query varchar(2048);

	SET @msg = 'Sales to Sales_No:(Cmplt&Cncld) Please refer to the attached spread sheet for the report.';  

	SET @query='SELECT SN.SalesNum,SN.cncld,SN.cmplt,S.SOitem,S.cncld,S.cmplt,S.gs_cmplt,AQ.ShipDate
	  ,ship.Cncld,ship.Complete,ship.[When],ship.ShipVia
		FROM dbo.Sales_No SN 
 		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum 
 		INNER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
 		INNER JOIN dbo.Ship ship ON S.SOitem = ship.SOitem 
 		WHERE S.cncld = 1 AND S.Cmplt = 1  AND SN.cncld =1  AND SN.cmplt=1  
		ORDER BY SN.SalesNum DESC;';

	SET @query='SELECT DISTINCT SN.SalesNum,SN.cncld,SN.cmplt,S.SOitem,S.cncld,S.cmplt
	,ship.Cncld,ship.Complete
	,ISNULL(RD.RMA_No,0) AS RMA_RMA_No
	,S.Rma_No
	,SS.[What]
	,ship.[When] AS DateShip ,ship.ShipVia
	,AQ.Company, AQ.SalesP
	, (SELECT TOP 1 Mess1 FROM dbo.NR_UserTrack WHERE Mess1 like ''%''+RTRIM(LTRIM(S.SOitem))+''%'' AND Mess1 LIKE ''Cancel_SO:%'' Order By ErrorDate DESC) AS UserTrack1
	, (SELECT TOP 1 Mess1 FROM dbo.NR_UserTrack WHERE Mess1 like ''%''+RTRIM(LTRIM(S.SOitem))+''%'' AND Mess1 LIKE ''Cancel_SO:%'' Order By ErrorDate ) AS UserTrack2
	,SNR.[When],SNR.Ver,SNR.Comment
	FROM dbo.Sales_No SN
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum 
		INNER JOIN dbo.Ship ship ON S.SOitem = ship.SOitem 
		INNER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem 
		INNER JOIN dbo.Sales_Status SS ON S.SOitem = SS.SOitem
		LEFT OUTER JOIN dbo.RMA_Detail RD ON S.SOitem = RD.so_item
		left outer join dbo.Sales_No_Rev SNR ON SN.SalesNum = SNR.SalesNum 
		WHERE S.cncld = 1 AND S.Cmplt = 1  AND SN.cncld =1  AND SN.cmplt=1 
		AND SS.[WHAT] = ''Complete''
		ORDER BY SN.SalesNum DESC;';


	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_Sales_CancelComplete'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_Sales_CancelComplete.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;


		---------------
	*/
	END

RETURN

