AS

--EXEC dbo.p_Maintenance_Sales_Hold
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = 'David.Kirchner@ERP_1s.com' --ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0

-----------------------------
-- Cancelled Problem.
-- Checks all tables
--p_Maintenance_Sales_Complete only check Sales to Sales_No


SELECT @CntSO = COUNT(*) FROM dbo.Sales S
	WHERE ISNULL(S.Cncld,0) = 0
	AND ISNULL(S.Cmplt,0) = 1
	AND S.Hold = 1

IF @CntSO > 0
	BEGIN

	PRINT 'Sales Hold issue.'
	DECLARE @SalesNum INT = 0

	SELECT TOP 1 @SalesNum = S.SalesNum
		FROM dbo.Sales S
		WHERE  ISNULL(S.Cncld,0) = 0
		AND ISNULL(S.Cmplt,0) = 1
		AND S.Hold = 1
		

		SELECT @Body = ('SELECT S.* '+CHAR(10)+CHAR(13)
		+'  FROM dbo.Sales S'+CHAR(10)+CHAR(13)
		+' WHERE ISNULL(S.Cncld,0) = 0 AND ISNULL(S.Cmplt,0) = 1 AND S.Hold = 1 ;  '+CHAR(10)+CHAR(13)
		+' '+CHAR(13)
		+' --Found a HOLD on a Complete Order Problem.  '+CHAR(10)+CHAR(13)
		+' Counted:'+ CAST(@CntSO AS CHAR(10))+'.'
		+' on '+RTRIM(GETDATE())+'  Server:'+@@SERVERNAME+CHAR(10)+CHAR(13)
		+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Weekly ' )+CHAR(13)
		+' dbo.p_Maintenance_Sales_Cancel';

	EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'HOLD on a Complete Order Problem',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';
	
	

	PRINT 'Record to Hold Status'
	INSERT INTO dbo.Sales_Hold_Status 
	([SOitem],[SalesNum],[POitem],[Hold_Type],[Hold_Value],[What],[Comment])
	( 
	SELECT S.[SOitem],S.[SalesNum],'','',0,'OFF Hold','Order is Complete set OFF Hold'
	FROM dbo.Sales S 
			WHERE ISNULL(S.Cncld,0) = 0
			AND ISNULL(S.Cmplt,0) = 1
			AND S.Hold = 1
	)


	PRINT 'Remove Hold Status'
		UPDATE dbo.Sales SET Hold = 0 
			WHERE ISNULL(Cncld,0) = 0
			AND ISNULL(Cmplt,0) = 1
			AND Hold = 1
			
	
	END

RETURN

