--SELECT SN.SalesNum AS SNSalesNum, SN.ItemTot AS SNItems, S.ItemTot AS SItems, (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE Sales.SalesNum = SN.Salesnum) AS S_Items
