 FROM dbo.Sales S
 INNER JOIN dbo.Sales_No SN ON S.salesnum = SN.salesnum
 AND S.ItemTot < SN.ItemTot
 AND ISNULL(SN.cncld,0) = 0;

IF @CntSO > 0
	BEGIN

