ALTER PROCEDURE [dbo].[p_Maintenance_Sales_Quotes]

AS

--EXEC dbo.p_Maintenance_Sales_Quotes
--ran from Maintenace Plans: ERP_1 Backup saturday

--See Raptor Report
--http://raptor/ReportS/report/Sales%20Reports/Sales%20Version%20Issue
--http://raptor/ReportS/report/Sales%20Reports/Sales%20missing%20in%20Quotes

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0;
DECLARE @CntSOCanc INT = 0;
DECLARE @cProfile_Name VarChar(50);
DECLARE @SalesNum INT = 0;
DECLARE @cSOitem CHAR(12) = '';
Declare @cInqNumP Char(9) = '';

--DECLARE @msg VARCHAR(250) = 'Please refer to the attached spread sheet for the report.';  
--DECLARE @query varchar(2048);

-----------------------------
-- SalesNum in Sales and not Quotes Problem.


SELECT @CntSOCanc = COUNT(*)
 FROM dbo.Sales S 
 LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
 WHERE ISNULL(AQ.SalesNum,-1) = -1
 AND S.SalesNum > 100000;

SELECT @CntSO = COUNT(*)
 FROM dbo.Sales S 
 LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
 WHERE ISNULL(AQ.SalesNum,-1) = -1
 AND S.SalesNum > 100000
 AND ISNULL(S.cncld,0) = 0;

 
IF @CntSO > 0
	BEGIN

	PRINT 'Found a Problem in Sales. No matching Quote';

	SELECT TOP 1 @SalesNum = S.SalesNum, @cInqNumP = S.InqNumP
		FROM dbo.Sales S 
		LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
		WHERE ISNULL(AQ.SalesNum,-1) = -1  
		AND S.SalesNum > 100000
		AND ISNULL(S.cncld,0) = 0;

	SELECT @Body = ('USE ERP_1;'+CHAR(13)+' SELECT S.SOitem '+CHAR(13)
	 +' FROM dbo.Sales S '+CHAR(13)
	 +' LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem '+CHAR(13)
	 +' WHERE ISNULL(AQ.SalesNum,-1) = -1'+CHAR(13)
	 +' AND S.SalesNum > 100000'+CHAR(13)
	 +' AND ISNULL(S.cncld,0) = 0;'+CHAR(10)+CHAR(13) );

	 SET @Body = @Body +'http://raptor/ReportS/report/Sales%20Reports/Sales%20missing%20in%20Quotes'+CHAR(13)+CHAR(10)+CHAR(13)
	 +' --Fix  Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)
	 +' File Name: C:\Users\David Kirchner\OneDrive - High Performance Alloys Inc\Documents\SQL Server Management Studio\Fix SOitem -02.sql  a 2 item fix.'+CHAR(13)
	 +' No matching Quote SalesNum found in AllQuotes.'+CHAR(13)
	 +' InqNumP='+@cInqNumP+'.'+CHAR(13)
	 +' Counted: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '+CHAR(13)
	 +@@SERVERNAME+'.  in dbo.p_Maintenance_Sales_Quotes ' 
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'SO in Sales missing in Quotes.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';
	
	
	END
ELSE
IF @CntSOCanc > 0
	BEGIN

	PRINT 'Found a Problem in Sales. Sales is Cancelled. No matching Quote. ';

	SELECT TOP 1 @cSOitem = S.SOitem, @cInqNumP = S.InqNumP,  @SalesNum=S.SalesNum
		FROM dbo.Sales S 
		LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem
		WHERE ISNULL(AQ.SalesNum,-1) = -1  
		AND S.SalesNum > 100000

	SELECT @Body = ('USE ERP_1;'+CHAR(13)+' SELECT S.SOitem '+CHAR(13)
	 +' FROM dbo.Sales S '+CHAR(13)
	 +' LEFT OUTER JOIN dbo.AllQuotes AQ ON S.SOitem = AQ.SOitem '+CHAR(13)
	 +' WHERE ISNULL(AQ.SalesNum,-1) = -1'+CHAR(13)
	 +' AND S.SalesNum > 100000'+CHAR(13)
	 +CHAR(10)+CHAR(13) );

	 SET @Body = @Body +
	  +' --Fix  Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+' --SOitem '+ @cSOitem +CHAR(13)
	 +' File Name: C:\Users\David Kirchner\OneDrive - High Performance Alloys Inc\Documents\SQL Server Management Studio\Fix SOitem -02.sql  a 2 item fix.'+CHAR(13)
	
	 +' SOitem is Cancelled in dbo.Sales.'+CHAR(13)
	 +' No matching Quote SOitem found in AllQuotes.'+CHAR(13)
	 +' InqNumP='+@cInqNumP+'.'+CHAR(13)
	 +' Counted: '+ CAST(@CntSOCanc AS CHAR(10))+'.'+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '+CHAR(13)
	 +@@SERVERNAME+'.  in dbo.p_Maintenance_Sales_Quotes ' 
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'SO in Sales is Cancelled but missing in Quotes.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';
	
	
	END


RETURN

