ALTER PROCEDURE [dbo].[p_Maintenance_Sales_Summary_ps]

AS

--EXEC dbo.p_Maintenance_Sales_Summary_ps
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

--SELECT * FROM dbo.NR_Sales_Summary_ps WHERE Shipped >= CAST(GETDATE()-31 AS DATE)

--PRINT 'SET QUOTED_IDENTIFIER ON;'
--SET QUOTED_IDENTIFIER ON;

--SELECT CouNT(*) FROM dbo.NR_Sales_Summary_ps GROUP  BY [Year] order by [Year] DESC

DECLARE @DateLastYear AS Date
SET @DateLastYear = GETDATE()-365

PRINT 'p_Maintenance_Sales_Summary-ps  -Remove 365 days and ReAdd to Summary'
PRINT 'Remove summary for SOitem that we will now add!'

DELETE FROM dbo.NR_Sales_Summary_ps
	WHERE SOitem IN
	(SELECT DISTINCT SOitem 
		FROM dbo.packingSlip
			WHERE LEN(SOitem) > 0
				AND First_RSO >= @DateLastYear )

PRINT 'Remove summary for cancelled SO.'
DELETE FROM dbo.NR_Sales_Summary_ps
	WHERE SOitem IN
	(SELECT DISTINCT S.SOitem 
		FROM ERP_2.dbo.Sales S
			WHERE LEN(S.SOitem) > 0
				AND ISNULL(S.Cncld,0) = 1
				AND S.DateAdded >= @DateLastYear )


PRINT 'Add summary of 365 days of Sales -without- Sz2.'
INSERT INTO dbo.NR_Sales_Summary_ps
([Shipped],[Mnth],[Qtr],[Year],[Alloy],[form],[CC],[CL],[Size],[Sz2],[PCs],[PT_QTY],[SO_QTY],[PT_P],[MatlWt],[MatlFt],[Typ],[ItemCost],[ItemSales],[SOitem],[Q_P],[Q_QTY],[PackingSli])

SELECT 
	PS.First_RSO AS Shipped 
	,Month(PS.First_RSO) AS Mnth
	,CASE WHEN Month(PS.First_RSO) < 4 THEN 1 WHEN Month(PS.First_RSO) < 7 THEN 2 WHEN Month(PS.First_RSO) < 10 THEN 3 ELSE 4 END AS Qtr
	,Year(PS.First_RSO) AS Yr
	,AQ.Alloy, AQ.form, dbo.f_CC_ESR(AQ.CC) AS CC, AQ.CL
	,ERP_2.dbo.f_SizeStandard(AQ.Thck) AS Size
	,0 AS Sz2
	,PS.PCs  --( CASE ERP_2.dbo.f_GetFormPU(AQ.Form) WHEN 3 THEN AQ.Pieces ELSE 0 END ) As Pc
	,PS.PT_QTY
	,PS.SO_QTY
	,PS.PT_P

	,S.MatlWt
	,ERP_2.dbo.f_Est_Ft(PS.PT_QTY,AQ.Form,AQ.Thck,AQ.Alloy,AQ.Sz2,AQ.Pieces) AS MatlFt

	,S.Typ
	,S.ItemCost
	,S.ItemSale

	,S.SOitem
	,AQ.Q_P
	,AQ.Q_QTY
	,PS.PackingSli

FROM dbo.PackingSlip PS
--inner join dbo.PackingSlip_No PSN ON PS.Packingsli = PSN.PackingSli
inner join dbo.AllQuotes AQ ON PS.SOitem = AQ.SOitem 
inner join dbo.Sales S ON PS.SOitem = S.SOitem

	WHERE LEN(S.SOitem) > 0
	--AND ISNULL(S.Cmplt,0) = 1
	AND ISNULL(S.Cncld,0) = 0
	AND ISNULL(S.IntP,0) = 0
	AND ISNULL(AQ.[Services],0) = 0
	AND PS.First_RSO >= @DateLastYear
	AND PS.First_RSO IS NOT NULL
	AND dbo.f_GetForm_StockBySZ2(AQ.Form) = 0
	AND LEN(AQ.Alloy)>0


PRINT 'Add summary of 365 days of Sales -without- Sz2.'
INSERT INTO dbo.NR_Sales_Summary_ps
([Shipped],[Mnth],[Qtr],[Year],[Alloy],[form],[CC],[CL],[Size],[Sz2],[PCs],[PT_QTY],[SO_QTY],[PT_P],[MatlWt],[MatlFt],[Typ],[ItemCost],[ItemSales],[SOitem],[Q_P],[Q_QTY],[PackingSli])

SELECT 
	PS.First_RSO AS Shipped 
	,Month(PS.First_RSO) AS Mnth
	,CASE WHEN Month(PS.First_RSO) < 4 THEN 1 WHEN Month(PS.First_RSO) < 7 THEN 2 WHEN Month(PS.First_RSO) < 10 THEN 3 ELSE 4 END AS Qtr
	,Year(PS.First_RSO) AS Yr
	,AQ.Alloy, AQ.form, dbo.f_CC_ESR(AQ.CC) AS CC, AQ.CL
	,ERP_2.dbo.f_SizeStandard(AQ.Thck) AS Size
	,AQ.Sz2 AS Sz2
	,PS.PCs  --( CASE ERP_2.dbo.f_GetFormPU(AQ.Form) WHEN 3 THEN AQ.Pieces ELSE 0 END ) As Pc
	,PS.PT_QTY
	,PS.SO_QTY
	,PS.PT_P

	,S.MatlWt
	,ERP_2.dbo.f_Est_Ft(PS.PT_QTY,AQ.Form,AQ.Thck,AQ.Alloy,AQ.Sz2,AQ.Pieces) AS MatlFt

	,S.Typ
	,S.ItemCost
	,S.ItemSale

	,S.SOitem
	,AQ.Q_P
	,AQ.Q_QTY
	,PS.PackingSli

FROM dbo.PackingSlip PS
--inner join dbo.PackingSlip_No PSN ON PS.Packingsli = PSN.PackingSli
inner join dbo.AllQuotes AQ ON PS.SOitem = AQ.SOitem 
inner join dbo.Sales S ON PS.SOitem = S.SOitem

	WHERE LEN(S.SOitem) > 0
	--AND ISNULL(S.Cmplt,0) = 1
	AND ISNULL(S.Cncld,0) = 0
	AND ISNULL(S.IntP,0) = 0
	AND ISNULL(AQ.[Services],0) = 0
	AND PS.First_RSO >= @DateLastYear
	AND PS.First_RSO IS NOT NULL
	AND dbo.f_GetForm_StockBySZ2(AQ.Form) = 1
	AND LEN(AQ.Alloy)>0


RETURN

