Print 'f2 UPDATE dbo.McMaster_Quotes SET [FB_Min_PC] to where P_PC is to $75-100 Min';

UPDATE dbo.McMaster_Quotes
	SET [FB_Min_PC] = case 
		when P_Pc >= 75 then 1 
		when P_Pc < 75 AND P_PC >= 40 then 2 
		when P_Pc < 40 AND P_PC >= 30 then 3 
		when P_Pc < 30 AND P_PC >= 21 then 4 
		when P_Pc < 21 AND P_Pc >= 18 then 5 
		when P_Pc < 18 AND P_Pc >= 17 then 6
		when P_Pc < 17 AND P_Pc >= 14 then 7
		when P_Pc < 14 AND P_Pc >= 12 then 8
		when P_Pc < 12 AND P_Pc >= 11 then 9
		when P_Pc < 11 AND P_Pc >= 10 then 10
		when P_Pc < 10 AND P_Pc >= 9 then 11
		when P_Pc < 9  AND P_Pc >= 8 then 12
		when P_Pc < 8  AND P_Pc >= 7 then 14
		when P_Pc < 7  AND P_Pc >= 6 then 17
		when P_Pc < 6  AND P_Pc >= 5 then 20
		when P_Pc < 5  AND P_Pc >= 4 then 25
		when P_Pc < 4 AND P_Pc >= 3.3 then 33
		when P_Pc < 3.3 AND P_Pc >= 2 then 50
		when P_Pc < 2  AND P_Pc >= 1 then 100
		when P_Pc < 1   AND P_Pc >= .5 then 200
		when P_Pc < .5 AND P_Pc >= .33 then 300
		when P_Pc < .33 AND P_Pc >= .25 then 400
		when P_Pc < .25 AND P_Pc >= .1 then 1000
		when P_Pc < .10 AND P_Pc >= .05 then 2000
		when P_Pc < .05 AND P_Pc >= .01 then 10000
		when P_Pc < .01 AND P_Pc >= .001 then 100000
		when P_Pc < .001 AND P_Pc >= .0001 then 1000000
		else 10000000
		end
	WHERE Alloy = @Alloy AND [Period] = @Period 
		AND @PriceBreak = 0 ;
