--Price Break 0 has already been inserted.
-- Build off the previous PriceBreak records because that Price Break has been cleaned, bad records where removed.
--Copy old priceBreak, insert as the next current reord.
--new records based from the last PriceBreak data

	IF @PriceBreak > 0		--Create next PriceBreak rows
	begin
		PRINT 'Create next PriceBreak rows';

		INSERT INTO dbo.McMaster_Quotes
			  ([Period]
			  ,[Alloy]
			  ,[Form]
			  ,[CC]
			  ,[Pieces]
			  ,[Thck]
			  ,[Sz2]
			  ,[Sz3]
			  ,[StkWeight]
			  ,[Weight_PC]
			  ,[Quote_LBS]
			  ,[Descript]
		--      ,[P_Lb]
		--      ,[P_Pc]
			  ,P_Bracket
			  ,[Price_UoM]
			  ,[FB_LeadTime]
			  ,[FB_Min_PC]
			  ,[PI_Thck]
			  ,[PI_Width]
			  ,[PI_Length]
			  ,[PI_Diameter]
			  ,[CutLossLbs]
			  ,[TradeName]
			  ,[PriceBreak]
			  ,[Bracket_Lbs]
			  ,[Bracket_Min_PC]
		  )
		 SELECT  @Period
			  ,[Alloy]
			  ,[Form]
			  ,[CC]
			  ,([Pieces]+1) AS [Pieces]	--Make sure you do not try to price the same Piece Count twice
			  ,[Thck]
			  ,[Sz2]
			  ,[Sz3]
			  ,[StkWeight]  --Do not change
			  ,[Weight_PC]
			  , dbo.f_Bracket_Pounds([P_Bracket]+1 )  AS [Quote_LBS]
			  ,'' AS [Descript]
		--      ,[P_Lb]
		--      ,[P_Pc]
			  ,([P_Bracket]+1) AS [P_Bracket] 
			  ,[Price_UoM]
			  ,[FB_LeadTime]
			  ,([FB_Min_PC]+1) AS [FB_Min_PC]
			  ,[PI_Thck]
			  ,[PI_Width]
			  ,[PI_Length]
			  ,[PI_Diameter]
			  ,[CutLossLbs]
			  ,[TradeName]
			  ,([PriceBreak]+1) AS [PriceBreak]
			  ,dbo.f_Bracket_Pounds( [P_Bracket]+1 ) AS [Bracket_Lbs] 
			  ,0 AS [Bracket_Min_PC]
		 FROM dbo.McMaster_Quotes
			  WHERE Alloy = @Alloy AND [Period] = @Period
			  AND [PriceBreak] = ( @PriceBreak -1 )
			  AND [Bracket_Lbs] < 201	--Drop out the high Pound brackets 500,1000,2000
			   ;

		--end of @PriceBreak > 0
		--both P_Bracket and PriceBreak are 1 larger
