-- =============================================
-- Author:		David Kirchner
-- Create date: <2020-11-01>
-- Description:	<Make a Quote table/Report for McMaster-Carr>
-- =============================================

ALTER PROCEDURE [dbo].[p_McMaster_23]
	@Period	SmallDateTime,
	@Alloy	CHAR(12)
AS
BEGIN
--	SET NOCOUNT ON; --Count is NEEDED
--This is a holding place for McMaster Code
-- use Report Server to make XLS file. https://raptor/ReportS/browse/Price%20table

-- Introduced table dbo.McMaster_Inquire: removes the Stock check in p_McMaster_20, McMaster_WL and McMaster_CrossTab
-- DELETE FROM dbo.McMaster_Quotes WHERE [Period]='2021-11-04'; -- SELECT * FROM dbo.McMaster_Quotes WHERE [Period]='2021-11-04';

-- EXEC dbo.p_McMaster_23 @Period='2023-02-03',  @Alloy='400  '; 
-- EXEC dbo.p_McMaster_23 @Period='2023-02-03',  @Alloy='6B   '; 
-- EXEC dbo.p_McMaster_23 @Period='2023-02-03',  @Alloy='C-276  '; 
-- EXEC dbo.p_McMaster_23 @Period='2023-02-03',  @Alloy='HPA N50'; 
-- EXEC dbo.p_McMaster_23 @Period='2023-02-10',  @Alloy='HPA N60'; 
-- EXEC dbo.p_McMaster_23 @Period='2023-02-12',  @Alloy='NI 200 / 201'; 

--SELECT Distinct [Alloy] FROM dbo.McMaster_Inquire WHERE Quote = 1

--SELECT * FROM dbo.McMaster_Quotes
DECLARE @testP_Pc Numeric(8,2)=0

DECLARE @NewRecCount INT = 1

-- Test Alloy
IF NOT EXISTS( SELECT * FROM dbo.McMaster_Inquire WHERE Alloy = @Alloy AND [Quote]=1)
begin
	PRINT 'the McMaster_Inquire table does not have this alloy yet ! '+ @Alloy+ ' or [Quote]=0'
	
	PRINT ' Return from dbo.p_McMaster ';
	SELECT * FROM dbo.McMaster_Inquire ;
	SELECT Distinct [Alloy] FROM dbo.McMaster_Inquire WHERE Quote = 1
	RETURN -1
end

--Set Priceing Factor by Alloy
--DECLARE	@Alloy	CHAR(12)='HPA N60'
DECLARE @Factor NUMERIC(3,2) = 1.00
SET @Factor = Case  
	When @Alloy = 'HPA N60     ' Then 1.10
	When @Alloy = 'HPA N50     ' Then 1.15
	When @Alloy = '6B          ' Then 1.10
	When @Alloy = '6BH         ' Then 1.10
	When @Alloy = 'C-276       ' Then 1.40
	When @Alloy = 'NI 200 / 201' Then 1.40
	Else 1.50 End 


PRINT 'Price Factor = '+RTRIM(CAST(@Factor AS CHAR(10)))+' Increase';
--SELECT Distinct [Alloy] FROM dbo.McMaster_Inquire WHERE Quote = 1


-- dbo.McMaster_Inquire is where sizes to be Quote are keeped
-- dbo.McMaster_Stock hold the McMaster_Inquire with the Period being added
-- sometime Inquire to Stock value can be skipped where a query of current stock is used.

-- dbo.McMaster_Quotes holds the data that the Report Sever uses per Alloy,Period

--no need to delete from dbo.McMaster_Inquire
PRINT 'DELETE FROM dbo.McMaster_Stock WHERE AND Alloy = '''+RTRIM(@Alloy)+''' AND [Period] = '''+CONVERT( VarChar(10), @Period, 120);

DELETE FROM dbo.McMaster_Stock
	WHERE Alloy = @Alloy AND [Period] = @Period  ;

---
PRINT 'DELETE FROM dbo.McMaster_Quotes WHERE AND Alloy = '''+RTRIM(@Alloy)+''' AND [Period] = '''+CONVERT( VarChar(10), @Period, 120);

DELETE FROM dbo.McMaster_Quotes
	WHERE Alloy = @Alloy AND [Period] = @Period  ;


--1. Sum collect common Stock INTO dbo.McMaster_Stock
PRINT 'Insert into McMaster_Stock';
--select * FROM McMaster_Inquire as the needed items to quote, add Quote Peroid

	INSERT INTO dbo.McMaster_Stock
		  ([Period],[Alloy],[Form],[CC]
		  ,Thck
		  ,StkWeight  )
		SELECT 
			@Period AS [Period],Alloy,Form,CC
			,thck
			, 0 AS StkWeight
			FROM dbo.McMaster_Inquire WHERE Alloy = @Alloy AND [Quote]=1;


--INSERT INTO dbo.McMaster_Stock ([Period],Alloy,Form,CC,Thck,StkWeight) Values ('2020-12-07 00:00:00','6BH','40','1',0.187,0)
--0.065 0.078  0.125 0.156 0.187


--2. See if McMaster_Stock or McMaster_Inquire has this alloy yet.


IF NOT EXISTS( SELECT * FROM dbo.McMaster_Stock WHERE Alloy = @Alloy)
begin
	PRINT 'the McMaster_Stock table does not have this alloy yet ! '+ @Alloy;
	
	PRINT ' Return from dbo.p_McMaster ';
	SELECT * FROM dbo.McMaster_Stock 
	RETURN -1
end

--SELECT * FROM dbo.McMaster_Inquire  WHERE Alloy = 'HPA N60'  AND [Quote]=1




--4. Use the McMaster_Inquire table to Create Quotes that can be imported into the McMaster SpreadSheet.
--use whatever date for Period, just do not use the same Period on differen Alloys

-----------
--DELETE FROM dbo.McMaster_Quotes WHERE [Period] = '2020-11-09' 
--SELECT * FROM dbo.McMaster_Quotes WHERE [Period] = '2020-11-03' 

--PRINT 'Delete existing Period and Alloy contents'
--DELETE FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period 
--AND [PriceBreak] = @PriceBreak
--Declare @Period SmallDateime = '2020-11-09'
PRINT 'INSERT INTO dbo.McMaster_Quotes';

DECLARE @PriceBreak TINYINT = 0
--Keep PriceBreak under 10

--SELECT * FROM dbo.McMaster_Quotes Order by ID DESC
--Build Table with mins (@PriceBreak=0)
INSERT INTO dbo.McMaster_Quotes
      ([Period]
      ,[Alloy]
      ,[Form]
      ,[CC]
      ,[Pieces]
      ,[Thck]
      ,[Sz2]
      ,[Sz3]
      ,[StkWeight]
	  ,[Weight_PC]
	  ,[Quote_LBS]
      ,[Descript]
--      ,[P_Lb]
--      ,[P_Pc]
      ,P_Bracket
      ,[McM_Desc]
--      ,[Price_Net]
      ,[Price_UoM]
      ,[FB_LeadTime]
--      ,[FB_Min_PC]
      ,[PI_Thck]
      ,[PI_Width]
      ,[PI_Length]
      ,[PI_Diameter]
	  ,[CutLossLbs]
	  ,[TradeName]
	  ,[PriceBreak]
	  ,[Bracket_Lbs]
	  ,[Bracket_Min_PC]
	  ,[PF]
	  ,[McMaster_ID]
  )
SELECT @Period AS [Period],S.Alloy,S.Form,S.CC
,1 AS [Pieces]
,S.Thck
,0 AS Sz2
,0 AS Sz3
--,(SELECT MAX(ISNULL(D.Dim2,0)) FROM dbo.StockLst_Master M 	INNER JOIN dbo.StockLst_Detail D ON M.ID = D.ID 	WHERE M.Alloy = S.Alloy AND Form = S.Form AND CC= S.CC AND Size=S.Thck) AS Sz2
--,case when S.Form <> '40' then 0 else (SELECT MAX(ISNULL(D.Dim3,0)) FROM dbo.StockLst_Master M 	INNER JOIN dbo.StockLst_Detail D ON M.ID = D.ID	WHERE M.Alloy = S.Alloy AND Form = S.Form AND CC= S.CC AND Size=S.Thck) end AS Sz3
,0 AS [StkWeight]
,0 AS [Weight_PC]
,5 AS [Quote_LBS]
--, RTRIM(S.Alloy)+' '+RTRIM(dbo.f_DescriptionMetricReport(Pieces, Form, Thck, SZ2, SZ3, Weight, RandLen, Metric, Sz1orig, Sz2orig, Sz3orig))  AS [Descript]
,'' AS [Descript]
--,[P_Lb]
--,[P_Pc]
,1 AS P_Bracket
,S.[McMaster] AS [McM_Desc]
--,[Price_Net]
,S.[Price_UoM]
,S.[FB_LeadTime]
--,[FB_Min_Pc]
,S.Thck AS [PI_Thck]  --,Case S.Form when '40' then S.Thck else 0 end AS [PI_Thck]
,[PI_Width]
,[PI_Length]
,Case when S.Form ='10' or S.Form='20' then S.Thck else 0 end AS [PI_Diameter]
,0 AS [CutLossLbs]
,S.[TradeName]
, @PriceBreak AS [PriceBreak]
,5 AS [Bracket_Lbs]
,1 AS [Bracket_Min_PC]
,@Factor AS [PF]
,dbo.[f_McMaster_ID] (Alloy,Form,CC,Thck,PI_Width,PI_Length) AS F_McMaster_ID
FROM dbo.McMaster_Inquire S
WHERE S.Alloy = @Alloy AND S.[Quote]=1;


--4.5 Thin down using Min/Max

--5. Make sure there is a PriceTable entry to match
PRINT 'Make sure there is a PriceTable entry to match McMaster_Inquire';

IF EXISTS(
 SELECT ISNULL(P.Alloy,'No Alloy') AS [PriceTable Alloy],Q.*
 FROM dbo.McMaster_Inquire Q
 left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form 
	AND P.CC = Q.CC AND P.Size = dbo.f_SizeStandard(Q.Thck)
 WHERE Q.Alloy = @Alloy AND Q.[Quote]=1
AND P.Alloy IS Null  )
	begin
	PRINT 'Missing PriceTable Entry -Inquire';

	SELECT DISTINCT Q.Alloy,Q.Form,Q.CC,dbo.f_SizeStandard(Q.Thck) AS [SizeStandard]--,Q.StkWeight
		,'No Price Table Entry' AS [comment]
		FROM dbo.McMaster_Inquire Q
		left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form 
			AND P.CC = Q.CC AND P.Size = dbo.f_SizeStandard(Q.Thck)
		WHERE Q.Alloy = @Alloy --AND Q.[Period] = @Period
			AND P.Alloy IS Null 
			AND Q.[Quote]=1;
		
		PRINT 'Missing PriceTable Entry';
		
		PRINT 'SELECT DISTINCT Q.Alloy,Q.Form,Q.CC,Q.Thck AS [SizeStandard],Q.StkWeight,''No Price Table Entry'' AS [comment] FROM dbo.McMaster_Inquire Q left outer join dbo.PriceTable P ON P.Alloy = Q.Alloy AND P.Form = Q.Form AND P.CC = Q.CC AND P.Size = Q.Thck WHERE P.Alloy IS Null  AND Q.[Quote]=1';
		PRINT 'OR try ';
		PRINT 'SELECT Q.* FROM dbo.McMaster_Inquire Q left outer join dbo.PriceTable P ON P.Alloy = Q.Alloy AND P.Form = Q.Form AND P.CC = Q.CC AND P.Size = Q.Thck WHERE  P.Alloy IS Null AND Q.[Quote]=1';

		--RETURN -1;	continue, just Delete after where P_LB IS NULL
	
	end

PRINT 'Make sure there is a PriceTable entry to match McMaster_Quotes';

IF EXISTS(
 SELECT Q.*
 FROM dbo.McMaster_Quotes Q
 left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form 
	AND P.CC = Q.CC AND P.Size = dbo.f_SizeStandard(Q.Thck)
 WHERE Q.Alloy = @Alloy AND Q.[Period] = @Period
	AND P.Alloy IS Null  
)  
	begin
	PRINT 'Missing PriceTable Entry - Quote';

	SELECT DISTINCT Q.Alloy,Q.Form,Q.CC,dbo.f_SizeStandard(Q.Thck) AS [SizeStandard],Q.StkWeight,'No Price Table Entry' AS [comment]
		FROM dbo.McMaster_Quotes Q
		left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form 
			AND P.CC = Q.CC AND P.Size = dbo.f_SizeStandard(Q.Thck)
		WHERE Q.Alloy = @Alloy AND Q.[Period] = @Period
			AND P.Alloy IS Null  ;
		
		PRINT 'Missing PriceTable Entry';
		
		PRINT 'SELECT DISTINCT Q.Alloy,Q.Form,Q.CC,Q.Thck AS [SizeStandard],Q.StkWeight,''No Price Table Entry'' AS [comment] FROM dbo.McMaster_Quotes Q left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form AND P.CC = Q.CC AND P.Size = Q.Thck WHERE P.Alloy IS Null ';
		PRINT 'OR try ';
		PRINT 'SELECT Q.* FROM dbo.McMaster_Quotes Q left outer join dbo.PriceTable P ON P.Alloy = dbo.f_Price_Alloy(Q.Alloy) AND P.Form = Q.Form AND P.CC = Q.CC AND P.Size = Q.Thck WHERE  P.Alloy IS Null ';

		--RETURN -1;	continue, just Delete after where P_LB IS NULL
	

	end

