PRINT 'Count dbo.McMaster_Quote Records WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ';
SELECT COUNT(*) AS McMaster_Quotes_Cnt FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ;
PRINT ' '


Print 'a  ******************************************************';
PRINT 'a UPDATE dbo.McMaster_Quotes SET [CutLossLbs] WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0';

--SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 Order by ID DESC
UPDATE dbo.McMaster_Quotes
	SET [CutLossLbs] = case 
		when [Form] = '10' then dbo.f_Get_Weight(10,Alloy,'10',CC,[PI_Diameter]*1.02,.2,0,0)/10 
		when [Form] = '20' then dbo.f_Get_Weight(10,Alloy,'20',CC,[PI_Diameter]*1.01,.01,0,0)/10 
		when [Form] = '40' AND [PI_Thck] <= .19 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.01,.07,.07,0)/10 
		when [Form] = '40' AND [PI_Thck] > .19 AND [PI_Thck] <= .3 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.125,.25,0)/10 
		when [Form] = '40' AND [PI_Thck] > .3  AND [PI_Thck] <= .5 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.2,.2,0)/10 
		when [Form] = '40' AND [PI_Thck] > .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.3,.3,0)/10 
		else 0.0001 end
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ;

