PRINT 'UPDATE dbo.McMaster_Quotes SET [Weight_PC]  WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0' ;
UPDATE dbo.McMaster_Quotes
	SET [Weight_PC] = case 
		when [Form] = '10' then dbo.f_Get_Weight(10,Alloy,'10',CC,[PI_Diameter]*1.05,[PI_Length],0,0)/10 + [CutLossLbs]
		when [Form] = '20' then dbo.f_Get_Weight(10,Alloy,'20',CC,[PI_Diameter]*1.05,[PI_Length],0,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .19 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.1,[PI_Width]+.07,  [PI_Length]+.07,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .3  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.09,[PI_Width]+.125,[PI_Length]+.25,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.04,[PI_Width]+.15, [PI_Length]+.15,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] >  .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,[PI_Width]+.2,  [PI_Length]+.00,0)/10 + [CutLossLbs]
		else 0 end
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0;

