	IF @PriceBreak > 0		--Create next PriceBreak rows
	begin
		PRINT 'Create next PriceBreak rows';

		INSERT INTO dbo.McMaster_Quotes
			  ([Period]
			  ,[Alloy]
			  ,[Form]
			  ,[CC]
			  ,[Pieces]
			  ,[Thck]
			  ,[Sz2]
			  ,[Sz3]
			  ,[StkWeight]
			  ,[Weight_PC]
			  ,[Quote_LBS]
			  ,[Descript]
		      ,[P_Lb]
