			  ,[PF]
			  ,[McMaster_ID]
		  )
		 SELECT  @Period
			  ,[Alloy]
			  ,[Form]
			  ,[CC]
			  ,0 AS [Pieces]	
			  ,[Thck]
			  ,[Sz2]
			  ,[Sz3]
			  ,[StkWeight]  --Do not change
			  ,[Weight_PC]
			  ,[Bracket_Lbs]+[Weight_PC] AS [Quote_LBS] --, [Quote_LBS]+1 AS [Quote_LBS]  --, dbo.f_Bracket_Pounds([P_Bracket]+1 )  AS [Quote_LBS]
			  ,'' AS [Descript]
		      ,0 AS [P_Lb]
		      ,0 AS [P_Pc]
			  ,[McM_Desc]
			  ,([P_Bracket]+1) AS [P_Bracket] 
			  ,[Price_UoM]
			  ,[FB_LeadTime]
			  ,0 AS [FB_Min_PC]
			  ,[PI_Thck]
			  ,[PI_Width]
			  ,[PI_Length]
			  ,[PI_Diameter]
			  ,[CutLossLbs]
			  ,[TradeName]
			  ,([PriceBreak]+1) AS [PriceBreak]
			  ,dbo.f_Bracket_Pounds( [P_Bracket]+1 ) AS [Bracket_Lbs] 
			  ,[Bracket_Min_PC]+1 AS [Bracket_Min_PC]
			  ,@Factor 
			  ,[McMaster_ID]
		 FROM dbo.McMaster_Quotes
			  WHERE Alloy = @Alloy AND [Period] = @Period
			  AND [PriceBreak] = ( @PriceBreak -1 )
