		---------------------------------------
		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND Pieces < 1)
		begin
			--SET [Descript] = 'Adjusting Pieces'  --to Signal so next code can find it
			PRINT 'Found Pieces = 1 in PriceBreak ' +CAST( @PriceBreak AS CHAR(3));
			PRINT 'Fix so 1 Pieces happens in PriceBreak 0, not here';
			SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND Pieces < 1
			RETURN -1
		END

		PRINT '1b UPDATE dbo.McMaster_Quotes SET P_Lb';
		---------


		UPDATE dbo.McMaster_Quotes
			SET [P_Lb] = case 
				when form = '10' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor
				when form = '20' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor
				when Form = '40' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck]    ,[PI_Width],[PI_Length],[Quote_Lbs])*@Factor
				else 0 end
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak  ;




