			SET [P_Lb] = ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length],[Quote_Lbs])*@Factor,2) 
