				when form = '20' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0,([Weight_Pc]+[CutLossLbs])*Pieces)*@Factor
