				else 0 end
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak  ;
*/

		-------------------------------------
		PRINT '1b2 See if P_LB is greater than previous';
		PRINT 'current PriceBreak ='+CAST(@PriceBreak AS CHAR(3));







		PRINT 'look for bad prices';
		IF EXISTS( SELECT Q1.ID, Q2.[PriceBreak] AS PBa, Q2.P_LB AS Pa, Q1.[PriceBreak] AS PBb, Q1.P_LB AS Pb 
			FROM dbo.McMaster_Quotes AS Q1
				INNER JOIN dbo.McMaster_Quotes AS Q2 ON Q2.[Period] = @Period AND Q2.[PriceBreak] = @PriceBreak-1
				AND Q1.Alloy = Q2.Alloy AND Q1.Form = Q2.Form AND Q1.CC = Q2.CC 
				AND Q1.PI_Thck = Q2.PI_Thck AND Q1.PI_Width = Q2.PI_Width AND Q1.PI_Length = Q2.PI_Length AND Q1.PI_Diameter = Q2.PI_Diameter 
			WHERE Q1.Alloy = @Alloy AND Q1.[Period] = @Period AND Q1.[PriceBreak] = @PriceBreak 
				AND  Q1.P_LB > Q2.P_LB )
		begin

			PRINT ' the next higher PriceBreak should be a lower price!';
			

			SELECT 'Price Should increase error.' AS txt, Q2.[PriceBreak] AS PBa, Q2.P_LB AS Pa,Q2.[Bracket_Lbs] AS LBa, Q1.[PriceBreak] AS PBb, Q1.P_LB AS Pb,Q1.[Bracket_Lbs] AS LBb
				,dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Q2.Alloy),Q2.Form,Q2.CC,'',Q2.[PI_Diameter],Q2.[PI_Length],0,(Q2.[Weight_Pc]+Q2.[CutLossLbs])*Q2.Pieces)*@Factor AS calcPa
				,dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Q1.Alloy),Q1.Form,Q1.CC,'',Q1.[PI_Diameter],Q1.[PI_Length],0,(Q1.[Weight_Pc]+Q1.[CutLossLbs])*Q1.Pieces)*@Factor AS calcPb
				,( SELECT W0*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS w0
				,( SELECT W5*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W5
				,( SELECT W10*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W10
				,( SELECT W25*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W25
				,( SELECT W50*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W50
				,( SELECT W100*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W100
				,( SELECT W200*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W200
				,( SELECT W500*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W500
				,( SELECT W1000*@Factor FROM dbo.PriceTable WHERE Alloy=Q1.Alloy AND Form = Q1.Form AND CC =Q1.cc AND Size =Q1.Thck ) AS W1000
				
				, Q1.*
				FROM dbo.McMaster_Quotes AS Q1
					INNER JOIN dbo.McMaster_Quotes AS Q2 ON Q2.[Period] = @Period AND Q2.[PriceBreak] = @PriceBreak-1
					AND Q1.Alloy = Q2.Alloy AND Q1.Form = Q2.Form AND Q1.CC = Q2.CC 
					AND Q1.PI_Thck = Q2.PI_Thck AND Q1.PI_Width = Q2.PI_Width AND Q1.PI_Length = Q2.PI_Length AND Q1.PI_Diameter = Q2.PI_Diameter 
				WHERE Q1.Alloy = @Alloy AND Q1.[Period] = @Period AND Q1.[PriceBreak] = @PriceBreak  
					AND  Q1.P_LB > Q2.P_LB ;

			PRINT 'These Prices need fixed in Price Table.';

			RETURN -1
		end

		--UPDATE dbo.McMaster_Quotes  SET P_Lb = dbo.f_GetPriceCC_CL(Alloy,'10',CC,'',[PI_Diameter],[PI_Length],0,([Weight_Pc]+[CutLossLbs])*Pieces) WHERE [Period] = @Period AND Form = '10' AND [PriceBreak] = @PriceBreak



		---------
		--Update P_PC with new P_LB
		PRINT '1c UPDATE dbo.McMaster_Quotes SET P_PC';

		UPDATE dbo.McMaster_Quotes  
			SET [P_Pc] = ROUND( ( [P_Lb] * ([Weight_Pc]+[CutLossLbs]) ),2) 
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak ;

		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE P_Pc = 0 AND Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak )
		begin	
			PRINT '1d FOUND where P_PC = 0';

			SELECT * FROM dbo.McMaster_Quotes WHERE [P_Pc] = 0 AND Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak ;
			-- EXEC dbo.p_McMaster @Period='2020-12-14',  @Alloy='C-276'
			RETURN -1
		end

		----********************
		------------************************************
		--*make sure there is a price increase worth listing


		PRINT '5 Updated [P_Bracket] [Bracket_Lbs] [P_Pc]=0 [Descript] = Geting Next Bracket [P_Lb] ';
		PRINT 'Set Pieces = Pieces + 1,P_Bracket = P_Bracket+1 ,[Descript] = Geting Next Bracket' ;
		UPDATE dbo.McMaster_Quotes 
			SET Pieces = Pieces + 1
				,P_Bracket = P_Bracket+1
				, Bracket_Lbs = dbo.f_Bracket_Pounds([P_Bracket]+1)
				,[P_Pc]=0	--Set to 0 find in next query
				,[Descript] = 'Geting Next Bracket' 
	/*			,[P_Lb] = case 
						when form = '10' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0, dbo.f_Bracket_Pounds([P_Bracket]+1))*@Factor,2)
						when form = '20' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0, dbo.f_Bracket_Pounds([P_Bracket]+1))*@Factor,2) 
						when Form = '40' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length], dbo.f_Bracket_Pounds([P_Bracket]+1))*@Factor,2) 
						else 0 end   */

				,[P_Lb] = case 
					when form = '10' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor
					when form = '20' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor
					when Form = '40' then dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck]    ,[PI_Width],[PI_Length],[Quote_Lbs])*@Factor
					else 0 end
					
			WHERE ID IN (
			SELECT DISTINCT t.ID1
			-- t.P_PC0, t.P_PC1 , t.P_Bracket1 
			--,[Period],Alloy,Form,CC,thck,Sz2,Sz3
		FROM (
			SELECT DISTINCT Q.[Period],Q.Alloy,Q.Form,Q.CC,Q.thck,Q.Sz2,Q.Sz3,Q.PriceBreak 
				,( SELECT TOP 1 Q0.P_Pc FROM dbo.McMaster_Quotes AS Q0 WHERE
					Q0.[Period]=[Period] AND Q0.Alloy=Q.Alloy AND Q0.Form=Q.Form AND Q0.CC=Q.CC AND Q0.thck=Q.Thck AND Q0.Sz2=Q.Sz2 AND Q0.Sz3=Q.Sz3 
					AND Q0.PriceBreak = @PriceBreak -1) AS P_PC0
				,( SELECT TOP 1 Q1.P_Pc FROM dbo.McMaster_Quotes AS Q1 WHERE
					Q1.[Period]=[Period] AND Q1.Alloy=Q.Alloy AND Q1.Form=Q.Form AND Q1.CC=Q.CC AND Q1.thck=Q.Thck AND Q1.Sz2=Q.Sz2 AND Q1.Sz3=Q.Sz3 
					AND Q1.PriceBreak = @PriceBreak) AS P_PC1
				,( SELECT TOP 1 Q1.ID FROM dbo.McMaster_Quotes AS Q1 WHERE
					Q1.[Period]=[Period] AND Q1.Alloy=Q.Alloy AND Q1.Form=Q.Form AND Q1.CC=Q.CC AND Q1.thck=Q.Thck AND Q1.Sz2=Q.Sz2 AND Q1.Sz3=Q.Sz3 
					AND Q1.PriceBreak = @PriceBreak) AS ID1
				,( SELECT TOP 1 Q1.P_Bracket FROM dbo.McMaster_Quotes AS Q1 WHERE
					Q1.[Period]=[Period] AND Q1.Alloy=Q.Alloy AND Q1.Form=Q.Form AND Q1.CC=Q.CC AND Q1.thck=Q.Thck AND Q1.Sz2=Q.Sz2 AND Q1.Sz3=Q.Sz3 
					AND Q1.PriceBreak = @PriceBreak) AS P_Bracket1
				
			FROM dbo.McMaster_Quotes Q WHERE Q.Alloy = @Alloy AND Q.[Period]=@Period 
				AND PriceBreak = @PriceBreak 
			) t
				WHERE  ( t.P_PC1 >= 500                   AND t.P_PC1*1.05 > t.P_PC0 ) 
					OR ( t.P_PC1 >= 100 AND t.P_PC1 < 500 AND t.P_PC1*1.07 > t.P_PC0 ) 
					OR ( t.P_PC1 >= 10  AND t.P_PC1 < 100 AND t.P_PC1*1.1  > t.P_PC0 ) 
					OR (                    t.P_PC1 < 10  AND t.P_PC1*1.13 > t.P_PC0 ) 
			--or 10% on less than $10 items and 7% on up to $100 item and 5% for over $500 items?
			) ;

		---------------------------
		PRINT '5 [Pieces] and [Bracket_Min_PC] if [Descript] = Geting Next Bracket';

		UPDATE dbo.McMaster_Quotes
			SET [Pieces] = CEILING( [Weight_Pc]+[Bracket_Lbs]/([Weight_Pc]+[CutLossLbs]) )
			,[Bracket_Min_PC] = CEILING( [Weight_Pc]+[Bracket_Lbs]/([Weight_PC]+[CutLossLbs]) )
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
				AND [Descript] = 'Geting Next Bracket'  ;


			PRINT '5 Quote_LBS 10bar  if [Descript] = Geting Next Bracket';
					--Need to adjust Quote_LBS to Calculated LBS	
			UPDATE dbo.McMaster_Quotes  
				SET [Quote_LBS] = dbo.f_Get_Weight(Pieces,Alloy,'10',CC,[PI_Diameter],[PI_Length],0,0)+(Pieces*[CutLossLbs])
					WHERE Alloy = @Alloy AND [Period] = @Period AND Form = '10' 
						AND [PriceBreak] = @PriceBreak
						AND [Descript] = 'Geting Next Bracket' ;

			PRINT '5 Quote_LBS 20wire  if [Descript] = Geting Next Bracket';
			UPDATE dbo.McMaster_Quotes  
				SET [Quote_LBS] = dbo.f_Get_Weight(Pieces,Alloy,'20',CC,[PI_Diameter],[PI_Length],0,0)+(Pieces*[CutLossLbs])
					WHERE Alloy = @Alloy AND [Period] = @Period AND Form = '20' 
						AND [PriceBreak] = @PriceBreak
						AND [Descript] = 'Geting Next Bracket' ;

			PRINT '5 Quote_LBS 40plate sheet  if [Descript] = Geting Next Bracket'
			UPDATE dbo.McMaster_Quotes  
				SET [Quote_LBS] = dbo.f_Get_Weight(Pieces,Alloy,'40',CC,[PI_Thck],[PI_Width],[PI_Length],0)+(Pieces*[CutLossLbs])
					WHERE Alloy = @Alloy AND [Period] = @Period AND Form = '40' 
						AND [PriceBreak] = @PriceBreak
						AND [Descript] = 'Geting Next Bracket' ;


			PRINT '5 P_LB   if [Descript] = Geting Next Bracket';
			UPDATE dbo.McMaster_Quotes
/*				SET [P_Lb] = case 
						when form = '10' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0, [Bracket_Lbs]) ,2) 
						when form = '20' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0, [Bracket_Lbs]) ,2) 
						when Form = '40' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length], [Bracket_Lbs]) ,2) 
						else 0 end  */
				SET [P_Lb] = case 
					when form = '10' then ROUND(dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor ,2)
					when form = '20' then ROUND(dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0         ,[Quote_Lbs])*@Factor ,2)
					when Form = '40' then ROUND(dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck]    ,[PI_Width],[PI_Length],[Quote_Lbs])*@Factor ,2)
					else 0 end

					WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak  
						AND [Descript] = 'Geting Next Bracket' ;

			PRINT '5 P_PC   if [Descript] = Geting Next Bracket';
			UPDATE dbo.McMaster_Quotes  
				SET [P_Pc] = ROUND( ( P_Lb * ([Weight_Pc]+[CutLossLbs]) ),2) 
				WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
					AND [Descript] = 'Geting Next Bracket' ;


		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE P_Pc = 0 AND [Period] = @Period AND [PriceBreak] = @PriceBreak )
		begin	
			PRINT '5 FOUND where P_PC = 0   if [Descript] = Geting Next Bracket';

			SELECT * FROM dbo.McMaster_Quotes WHERE P_Pc = 0 AND Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak ;
			RETURN -1
		end

			PRINT '5 Done -change Description from Adjusting Pieces to empty  if [Descript] = Geting Next Bracket';
			UPDATE dbo.McMaster_Quotes
				SET [Descript] = ''
					WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
						AND [Descript] = 'Adjusting Pieces'
						OR [Descript] = 'Geting Next Bracket' ;
	
		--* end of price increase check
