FROM 
(SELECT DISTINCT Q.[Period],Q.Alloy,Q.Form,Q.CC,Q.PI_Thck,q.PI_Length,q.PI_Diameter,q.PI_Width,Q.PriceBreak,Q.P_Pc
	FROM dbo.McMaster_Quotes Q WHERE Alloy = @Alloy AND [Period] = @Period )
