--update dbo.McMaster_Stock set thck =0.078 where id = 5720
--Just Copy, Edit and run the new INSERT commands.

--SELECT * from [dbo].[McMaster_WL]
/*
INSERT INTO [dbo].[McMaster_WL] 
	SELECT DISTINCT '6BH' AS [Alloy]
	,[Form],[CC],[Width],[Length] 
	FROM dbo.McMaster_CrossTab WHERE [Alloy] = '6B'
	and form = '40'

*/
