DECLARE @Form [char](2)
DECLARE @CC [char](1)
DECLARE @ThicknessMin [numeric](7, 4) = 0.062
DECLARE @ThicknessMax [numeric](7, 4) = .187
DECLARE @Width [numeric](8, 3) = 0
DECLARE @Length [numeric](8, 3) = 0
DECLARE @DiameterMin [numeric](7, 4) = 0
DECLARE @DiameterMax [numeric](7, 4) = 0
DECLARE @TradeName [varchar](30) = 'Cobalt 6BH'
DECLARE @Price_UoM [varchar](20) = 'Each Piece'
DECLARE @FB_LeadTime [varchar](50) = '7 Days'
--DECLARE @Packaging [varchar](50) = ''  This is done at end of Proc dbo.p_McMaster 
--SELECT * FROM dbo.McMaster_Stock WHERE Alloy = @Alloy 
--Select * FROM dbo.McMaster_CrossTab 
--SELECT * FROM McMaster_WL  -- DELETE FROM McMaster_WL WHERE Alloy = 'HPA N60' AND Form = '40' AND Width = 24 and Length = 48
/*
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) 
SELECT DISTINCT @Alloy AS Alloy,'10' AS Form, WL.CC ,0 AS [ThicknessMin],0 AS ThicknessMax, 0 AS [Width], WL.[Length],@DiameterMin AS [DiameterMin], @DiameterMax AS [DiameterMax], @TradeName, @Price_UoM, @FB_LeadTime
FROM dbo.McMaster_Stock S
Inner join dbo.McMaster_WL AS WL ON S.Alloy = WL.Alloy AND S.Form = WL.Form
WHERE S.Alloy = @Alloy AND S.Form = '10'
*/

INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) 
SELECT DISTINCT @Alloy AS Alloy,'40' AS Form, WL.CC ,@ThicknessMin AS [ThicknessMin],@ThicknessMax AS ThicknessMax, WL.Width, WL.[Length],0 AS [DiameterMin], 0 AS [DiameterMax], @TradeName, @Price_UoM, @FB_LeadTime
FROM dbo.McMaster_Stock S
Inner join dbo.McMaster_WL AS WL ON S.Alloy = WL.Alloy AND S.Form = WL.Form
WHERE S.Alloy = @Alloy AND S.Form = '40'



--SELECT * FROM dbo.McMaster_CrossTab WHERE Alloy = 'HPA N60' AND Form = '40'
--DELETE FROM dbo.McMaster_CrossTab WHERE Alloy = 'HPA N60' AND Form = '40'

--SELECT * FROM  dbo.McMaster_WL WHERE Alloy = 'HPA N60' AND Form = '40'
--INSERT INTO dbo.McMaster_WL (Alloy,Form,CC,Width,Length) VALUES ('HPA N60','40','1',24, 48)


--	('HPA N60','10','1',0,0,0,12,.125,7,'Nitronic 60','Each Piece','1-2 weeks')


/*  --The McMaster_WL join is fastest, use the INSERT one at a time if small. ------------------------
------------------------------------------------------------------------------------
INSERT INTO dbo.McMaster_CrossTab 
([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName]  ,[Price_UoM],[FB_LeadTime]) Values 
('HPA N60','10','1' ,0             ,0             ,0      ,6       ,.125         ,16            ,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','10','1',0,0,0,12,.125,7,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','10','1',0,0,0,48,.125,7,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','10','1',0,0,0,72,.125,7,'Nitronic 60','Per Pound','1-2 weeks')

INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.025,1,6,6,0,0,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.025,1,6,12,0,0,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.025,1,12,12,0,0,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.025,1,12,24,0,0,'Nitronic 60','Each Piece','1-2 weeks')

INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.25,1,36,36,0,0,'Nitronic 60','Each Piece','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.25,1,36,96,0,0,'Nitronic 60','Per Pound','1-2 weeks')

INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.25,1,48,48,0,0,'Nitronic 60','Per Pound','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.25,1,48,120,0,0,'Nitronic 60','Per Pound','1-2 weeks')
INSERT INTO dbo.McMaster_CrossTab ([Alloy],[Form],[CC],[ThicknessMin],[ThicknessMax],[Width],[Length],[DiameterMin],[DiameterMax],[TradeName],[Price_UoM],[FB_LeadTime]) Values 
	('HPA N60','40','1',0.25,1,48,144,0,0,'Nitronic 60','Per Pound','1-2 weeks')

*/

