/****** Object:  StoredProcedure [dbo].[p_Move_BrokerLst_StockLst]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_Move_BrokerLst_StockLst]') AND type in (N'P', N'PC'))
BEGIN
