ALTER    PROCEDURE [dbo].[p_Move_BrokerLst_StockLst]
	@ID		int,
	@ID_Detail	int
AS

Set NoCount On

--select top 5 ID,ID_Detail from dbo.BrokerLst_Detail ORDER BY ID_Detail DESC

--DECLARE	@ID		int = 13062,	@ID_Detail	int = 13036
--DELETE FROM dbo.BrokerLst_Master WHERE ID=13064
--DELETE FROM dbo.BrokerLst_Detail WHERE ID=13064
--DELETE FROM dbo.BrokerLst_Process WHERE ID_Detail=13038
--DELETE FROM dbo.StockLst_Process_Detail 
--FROM dbo.StockLst_Master SM WITH (NOLOCK)
--	inner Join dbo.StockLst_Detail SD WITH (NOLOCK) ON SM.ID = SD.ID
--	INNER JOIN dbo.StockLst_Process SP WITH (NOLOCK) ON SD.ID_Detail = SP.ID_Detail
--	WHERE SD.[ID] = 13064

--EXEC p_Move_BrokerLst_StockLst 13059,13033

--RETURN CODES
-- 0 No Scope Identity
-- 1 NO ID
-- 2 NO ID_Detail
-- 3 
-- 4 StockLst_Master Did not Insert
-- 5 StockLst_Detail Did not Insert
-- 6 StockLst_Process Did not Insert
-- 7 StockLst_Detail_Process Did not Insert
-- 8 Could not Delete BrokerLst_Process
-- 9 Could not UPDATE BrokerLst_Process_History  
-- 10 Could not Delete BrokerLst_Process_Detail
-- 11 Could not Delete BrokerLst_Detail
-- 12 Could not Delete BrokerLst_Master

DECLARE @nSCOPE_IDENTITY AS INT
DECLARE @nReturnCode AS INT = 0

DECLARE @err INT = 0
DECLARE @RC INT = 0
--select @RC = @@ROWCOUNT, @err = @@ERROR
DECLARE @Body varchar(4000) = ''

DECLARE @nNewID INT = 0
DECLARE @nNewID_Detail INT = 0
DECLARE @nNewID_Detail_Process INT = 0

--Check INPUTS
IF NOT EXISTS (SELECT [ID] FROM dbo.BrokerLst_Master WITH(NOLOCK) WHERE [ID] = @ID )
	BEGIN
		SET @nReturnCode = -1
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

IF NOT EXISTS (SELECT [ID_Detail] FROM dbo.BrokerLst_Detail WHERE [ID_Detail] = @ID_Detail )
	BEGIN
		SET @nReturnCode = -2
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

--SET @nReturnCode = -3

BEGIN TRANSACTION Move_BrokerLst_StockLst

----------------------------------
PRINT 'ADD Master'
INSERT INTO dbo.StockLst_Master 
	(
	   [Alloy]
      ,[Form]
      ,[CC]
      ,[CL]
      ,[Size]
      ,[Cond]
      ,[MWeight]
      ,[Specs]
      ,[Heat]
      ,[Lot]
      ,[Paid]
      ,[PO_item]
      ,[PoDueDate]
      ,[Mill]
      ,[StkDate]
      ,[History]
      ,[Num]
      ,[POStatus]
      ,[BrandName],[MillTrace]
      ,[FROM_ID]
      ,[Melt]

      ,[mS_QTY]
      ,[WO_Detail]
      ,[ProjID]
      )

SELECT [Alloy]
      ,[Form]
      ,[CC]
      ,[CL]
      ,[Size]
      ,[Cond]
      ,[MWeight]
      ,[Specs]
      ,[Heat]
      ,[Lot]
      ,[Paid]
      ,[PO_item]
      ,[PoDueDate]
      ,[Mill]
      ,GetDate() AS [StkDate]
      ,[History]
      ,[Num]
      ,[POStatus]
      ,[BrandName],[MillTrace]
      ,[FROM_ID]
      ,[Melt]
    
      ,[mS_QTY]
      ,[WO_Detail]
      ,[ProjID]
   FROM dbo.BrokerLst_Master
   WITH (NOLOCK)
   WHERE [ID] = @ID


SET @nNewID = SCOPE_IDENTITY()
PRINT @nNewID
SET @nReturnCode = @nNewID

IF @nNewID < 1
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))+'. Failed to INSERT INTO dbo.StockLst_Master'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END



----------------------------------
PRINT 'Move Details'
INSERT INTO dbo.StockLst_Detail
	(
	   [Size_H]
      ,[Size_L]
      ,[PC]
      ,[Dim1]
      ,[Dim2]
      ,[Dim3]
      ,[Length]
      ,[Weight]
      ,[CostValue]
      ,[Descript]
      ,[Location]
      ,[FloorStatus]
      ,[Class]
      ,[Unit]
      ,[RandLen]
      ,[InvCheck]
      ,[ID]
      ,[ReceivingID]
      ,[LiveCheck]
      ,[AccountingCheck]
      ,[InvoiceValue]
      ,[Quarantine]
      ,[S_QTY]
      ,[S_P]
      ,[S_Total]
      ,[S_PU]
      ,[Prime]
      ,[WO]
	  )
SELECT [Size_H]
      ,[Size_L]
      ,[PC]
      ,[Dim1]
      ,[Dim2]
      ,[Dim3]
      ,[Length]
      ,[Weight]
      ,[CostValue]
      ,[Descript]
      ,[Location]
      ,[FloorStatus]
      ,[Class]
      ,[Unit]
      ,[RandLen]
      ,GETDATE()
      ,@ID
      ,ISNULL([ReceivingID],0)
      ,0 AS [LiveCheck]
      ,1 AS [AccountingCheck]
      ,[InvoiceValue]
      ,0 AS [Quarantine]
      ,[S_QTY]
      ,ISNULL([S_P],0)
      ,ISNULL([S_Total],0)
      ,ISNULL([S_PU],0)
      ,ISNULL([Prime],1)
      ,ISNULL([WO],0)
  FROM dbo.BrokerLst_Detail
   WITH (NOLOCK)
   WHERE [ID] = @ID


SET @nNewID_Detail = SCOPE_IDENTITY()
PRINT @nNewID_Detail

IF @nNewID_Detail < 1
	BEGIN
		SET @nReturnCode = -5
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.StockLst_Detail blank'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END


----------------------------------
PRINT 'Move Process'
INSERT INTO dbo.StockLst_Process
	(
	   [SOitem]
      ,[PO_item]
      ,[SalesPerson]
      ,[StartDate]
      ,[DueDate]
      ,[Comment]
      ,[Process_ID]
      ,[Processor]
      ,[AllowSub]
      
      ,[PU]
      ,[QTY]
      ,[Ordered_QTY]
      ,[Ordered_P]
      ,[Pounds]
      ,[ID_Detail]
      
      ,[ReceivingID]
      ,[WO]
      ,[WO_Detail]
      ,[InqNumP]
      
      ,[Prc_Form]
      ,[Prc_PCs]
      ,[Prc_Dim1]
      ,[Prc_Dim2]
      ,[Prc_Dim3]
      ,[Prc_Q_QTY]
      ,[Prc_Q_PU]
	)
SELECT [SOitem]
      ,[PO_item]
      ,[SalesPerson]
      ,GETDATE()
      ,[DueDate]
      ,'Moved from BrokerLst ID:'+CAST(@ID AS CHAR(10))
      ,[Process_ID]
      ,[Processor]
      ,[AllowSub]
      
      ,[PU]
      ,[QTY]
      ,[Ordered_QTY]
      ,[Ordered_P]
      ,[Pounds]
      ,SD.[ID_Detail]
      
      ,ISNULL(SD.[ReceivingID],0)
      ,ISNULL(BP.[WO],0)
      ,ISNULL(BP.[WO_Detail],0)
      ,[InqNumP]
      
      ,[Prc_Form]
      ,[Prc_PCs]
      ,[Prc_Dim1]
      ,[Prc_Dim2]
      ,[Prc_Dim3]
      ,[Prc_Q_QTY]
      ,[Prc_Q_PU]
  FROM dbo.BrokerLst_Process BP WITH (NOLOCK)
   inner Join dbo.StockLst_Detail SD WITH (NOLOCK) ON BP.ID_Detail = SD.ID_Detail
   WHERE SD.[ID] = @ID


SET @nNewID_Detail_Process = SCOPE_IDENTITY()
PRINT @nNewID_Detail_Process

IF @nNewID_Detail_Process < 1
	BEGIN
		SET @nReturnCode = -6
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.StockLst_Process'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END


----------------------------------
PRINT 'Add Process Detail'
INSERT INTO dbo.StockLst_Process_Detail 
    ( [What], [ID], [ID_Detail], [ID_Detail_Process], WO ) 
SELECT 'ADD'
	, SM.ID
	, SD.ID_Detail
	, SP.ID_Detail_Process 
	, ISNULL(SD.WO,0)
FROM dbo.StockLst_Master SM WITH (NOLOCK)
	inner Join dbo.StockLst_Detail SD WITH (NOLOCK) ON SM.ID = SD.ID
	INNER JOIN dbo.StockLst_Process SP WITH (NOLOCK) ON SD.ID_Detail = SP.ID_Detail
	WHERE SD.[ID] = @ID


----------------------------------
--MWeight=0,  Calc from Detail
PRINT 'UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID'
UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR
IF @err <> 0
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		--RETURN @nReturnCode
	END

----------------------------------
PRINT 'Insert dbo.Ar_BrokerLst_Process_History to show WHAT as MOVED'


INSERT INTO dbo.Ar_BrokerLst_Process_History  
	([What], Comment, Process_ID, [ID_Detail], [Removed], ReceivingID, WO ) 
	 SELECT 'MOVED', 'Moved to StockLst from BrokerLst', ISNULL(BP.Process_ID,'NULL'), BP.ID_Detail, GetDate()
	 , ISNULL(BP.ReceivingID,0), ISNULL(BP.WO,0) 
	 FROM dbo.BrokerLst_Process BP WITH (NOLOCK)
		inner Join dbo.StockLst_Detail SD WITH (NOLOCK) ON BP.ID_Detail = SD.ID_Detail
		WHERE SD.[ID] = @ID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -9
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))

		PRINT 'Error = '+CAST(@err AS CHAR(10))
		PRINT 'RowCount = '+CAST(@RC AS CHAR(10))
		--PRINT '@Process_ID = '+ISNULL(@Process_ID,'NULL')

		PRINT 'Failed to INSERT BrokerLst_Process_History'
		SET @Body = @Body + 'Failed to INSERT BrokerLst_Process_History' +CHAR(13)

		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		--RETURN @nReturnCode
		PRINT 'Continuing with the MOVE.'
	END

--PRINT 'COMMIT TRANSACTION Move_BrokerLst_StockLst'

--COMMIT TRANSACTION Move_BrokerLst_StockLst

--BEGIN TRANSACTION Move_BrokerLst_StockLst

--*****************
-- DELETE
--*****************
PRINT 'Delete BrokerLst_Process WHERE (Process_ID = ''INCOMING  '' OR Process_ID = ''PARTRECV'')'

--BrokerLst_Process  Process_ID = 'INCOMING  '
DELETE FROM dbo.BrokerLst_Process 
WHERE [ID_Detail] IN 
	(SELECT DISTINCT BD.ID_Detail FROM
		dbo.BrokerLst_Master BM WITH(NOLOCK)
		INNER JOIN dbo.BrokerLst_Detail BD WITH(NOLOCK) ON BM.ID = BD.ID 
		WHERE BM.[ID] = @ID );
	

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -8
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to Delete BrokerLst_Process'
		SET @Body = @Body + 'Failed to Delete BrokerLst_Process.'+CHAR(13)

		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		--RETURN @nReturnCode
		PRINT 'Continue with MOVE.'
	END
	
-------------------------------------
PRINT 'BrokerLst_Process DELETE - Anything by ID_Detail'

DELETE FROM dbo.BrokerLst_Detail 
	WHERE ID_Detail IN (SELECT DISTINCT BD.ID_Detail 
		FROM dbo.BrokerLst_Master BM WITH(NOLOCK)
		INNER JOIN dbo.BrokerLst_Detail BD WITH(NOLOCK) ON BM.ID = BD.ID 
		WHERE BM.[ID] = @ID )



SELECT @RC = @@ROWCOUNT, @err = @@ERROR


IF @err <> 0
	BEGIN
		SET @nReturnCode = -11
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to DELETE BrokerLst_Detail WHERE ID_Detail = '+CAST(@ID_Detail AS CHAR(10))
		SET @Body = @Body + 'Failed to DELETE BrokerLst_Detail WHERE ID_Detail = '+CAST(@ID_Detail AS CHAR(10)) +CHAR(13)
				
		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		--RETURN @nReturnCode
		PRINT 'Continue with MOVE.'
	END

----------------------------------
IF @nReturnCode > 0
	PRINT 'DELETE the BrokerLst_Master WHERE [ID] = @ID'
	DELETE FROM dbo.BrokerLst_Master WHERE [ID] = @ID

	SELECT @RC = @@ROWCOUNT, @err = @@ERROR

	IF @err <> 0
 		BEGIN
			SET @nReturnCode = -12
			PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
			PRINT 'Failed to DELETE the BrokerLst_Master WHERE [ID] = '+CAST(@ID AS CHAR(10))	
			SET @Body = @Body + 'Failed to DELETE the BrokerLst_Master WHERE [ID] = '+CAST(@ID AS CHAR(10)) +CHAR(13)

			SET @nReturnCode = 0
			--ROLLBACK TRANSACTION Move_BrokerLst_StockLst
			--RETURN @nReturnCode
			PRINT 'Continue with MOVE.'
		END

----------------------------------
--Edit Receiving data
UPDATE dbo.Receiving SET StockTable = 'S'
	,ID_Master = @nNewID
	,ID_Detail = @nNewID_Detail
WHERE StockTable <> 'B' AND ID = @ID


----------------------------------
--Email

DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()

IF LEN(TRIM(@Body)) > 1
begin
	--Email Error			
	SET @Body = @Body+'.'+CHAR(10)+CHAR(13)
		+'User '+RTRIM(suser_sname())+' on '+RTRIM(CAST(GETDATE()AS CHAR))+' '+CHAR(13)
		+@@SERVERNAME+' TRIGGER '+' p_Move_BrokerLst_StockLst '+CHAR(13)	
		+' [ID] = '+CAST(@ID AS CHAR(10))
		+' [ID_Detail] = '+CAST(@ID_Detail AS CHAR(10))
		+' Error Code = '+CAST(@nReturnCode AS CHAR)

	EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'David.Kirchner@ERP_1s.com;Admin.Alert@ERP_1s.com', 
	@SubjectEmail = 'p_Move_BrokerLst_StockLst FAILED.',
		@BodyEmail = @Body,
		@BodyType = 'TEXT'
	
	--Save to SQL Error MSG
	RAISERROR( @Body, 16, -1)

end
ELSE
begin
	SET @Body = @Body+CHAR(13)
		+'User '+RTRIM(suser_sname())+' on '+RTRIM(CAST(GETDATE()AS CHAR))+' '+CHAR(13)
		+@@SERVERNAME+' TRIGGER '+' p_Move_BrokerLst_StockLst '+CHAR(13)
		+' [ID] = '+CAST(@ID AS CHAR(10))
		+' [ID_Detail] = '+CAST(@ID_Detail AS CHAR(10))
		+' TO StockLst '+CHAR(13)
		+' [ID] = '+CAST(@nNewID AS CHAR(10))
		+' [ID_Detail] = '+CAST(@nNewID_Detail AS CHAR(10))

	EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'David.Kirchner@ERP_1s.com', 
	@SubjectEmail = 'p_Move_BrokerLst_StockLst.',
		@BodyEmail = @Body,
		@BodyType = 'TEXT'
					
	--RAISERROR( @Body, 16, -1)
end
----------------------------------

IF @nReturnCode < 0
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
	 SELECT @nReturnCode
     PRINT 'ROLLBACK TRANSACTION Move_BrokerLst_StockLst'
     ROLLBACK TRANSACTION Move_BrokerLst_StockLst
    end
ELSE
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
     SET @nReturnCode = @nNewID_Detail
     SELECT @nReturnCode
     PRINT 'COMMIT TRANSACTION Move_BrokerLst_StockLst'
     COMMIT TRANSACTION Move_BrokerLst_StockLst
	end
	
RETURN @nReturnCode



 --GRANT EXECUTE ON [dbo].[p_Move_BrokerLst_StockLst] TO [WINDFALL\HPA] AS [dbo]; 
  
GO
/****** Object:  StoredProcedure [dbo].[p_Move_StockLst_BrokerLst]    Script Date: 12/26/2025 5:48:52 PM ******/
