ALTER    PROCEDURE [dbo].[p_Move_StockLst_BrokerLst]
	@ID		int,
	@ID_Detail	int
AS

--Set NoCount On
--Move Stock to Broker

--DECLARE	@ID		int
--DECLARE	@ID_Detail	int
--
--SET @ID = 116
--SET @ID_Detail = 103
--
--EXEC p_Move_StockLst_BrokerLst @ID, @ID_Detail
--EXEC p_Move_StockLst_BrokerLst 4133,3966

--RETURN CODES
-- 0 No Scope Identity
-- 1 NO ID
-- 2 NO ID_Detail
-- 3 
-- 4 StockLst_Master Did not Insert
-- 5 StockLst_Detail Did not Insert
-- 6 StockLst_Process Did not Insert
-- 7 StockLst_Detail_Process Did not Insert
-- 8 Could not Delete BrokerLst_Process
-- 9 Could not UPDATE BrokerLst_Process_History  
-- 10 Could not Delete BrokerLst_Process_Detail
-- 11 Could not Delete BrokerLst_Detail
-- 12 Could not Delete BrokerLst_Master

DECLARE @nSCOPE_IDENTITY AS INT
DECLARE @nReturnCode AS INT = 0

DECLARE @err INT = 0
DECLARE @RC INT = 0
--select @RC = @@ROWCOUNT, @err = @@ERROR
DECLARE @Body varchar(4000) = ''

DECLARE @nNewID INT = 0
DECLARE @nNewID_Detail INT = 0
DECLARE @nNewID_Detail_Process INT = 0

--Check INPUTS
IF NOT EXISTS (SELECT [ID] FROM dbo.StockLst_Master WHERE [ID] = @ID )
	BEGIN
		SET @nReturnCode = -1
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

IF NOT EXISTS (SELECT [ID_Detail] FROM dbo.StockLst_Detail WHERE [ID_Detail] = @ID_Detail )
	BEGIN
		SET @nReturnCode = -2
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

--SET @nReturnCode = -3

BEGIN TRANSACTION Move_StockLst_BrokerLst
----------------------------------
PRINT 'Insert Master'
INSERT INTO dbo.BrokerLst_Master
	(
	   [Alloy]
      ,[Form]
      ,[CC]
      ,[CL]
      ,[Size]
      ,[Cond]
      ,[MWeight]
      ,[Specs]
      ,[Heat]
      ,[Lot]
      ,[Paid]
      ,[PO_item]
      ,[PoDueDate]
      ,[Mill]
      ,[StkDate]
      ,[History]
--      ,[Num]
      ,[POStatus]
      ,[BrandName]
--      ,[FROM_ID]
      ,[Melt]

      ,[mS_QTY]
      ,[WO_Detail]
      ,[ProjID]
	  ,[MillTrace]
      )

SELECT [Alloy]
      ,[Form]
      ,[CC]
      ,[CL]
      ,[Size]
      ,[Cond]
      ,[MWeight]
      ,[Specs]
      ,[Heat]
      ,[Lot]
      ,[Paid]
      ,[PO_item]
      ,[PoDueDate]
      ,[Mill]
      ,GetDate() AS [StkDate]
      ,[History]
--      ,[Num]
      ,[POStatus]
      ,[BrandName]
--      ,[FROM_ID]
      ,[Melt]
    
      ,[mS_QTY]
      ,[WO_Detail]
      ,[ProjID]
	  ,[MillTrace]
   FROM dbo.StockLst_Master M
   WITH (NOLOCK)
   WHERE M.[ID] = @ID


SET @nNewID = SCOPE_IDENTITY()
PRINT @nNewID
SET @nReturnCode = @nNewID

IF @nNewID < 1
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))+'. Failed to INSERT INTO dbo.BrokerLst_Master'
		ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		RETURN @nReturnCode
	END
	


----------------------------------
PRINT 'Move Details'
INSERT INTO dbo.BrokerLst_Detail
	(
	   [Size_H]
      ,[Size_L]
      ,[PC]
      ,[Dim1]
      ,[Dim2]
      ,[Dim3]
      ,[Length]
      ,[Weight]
      ,[CostValue]
      ,[Descript]
      ,[Location]
      ,[FloorStatus]
      ,[Class]
      ,[Unit]
      ,[RandLen]
      ,[InvCheck]
      ,[ID]

      ,[ReceivingID]
      ,[LiveCheck]
      ,[AccountingCheck]
      ,[InvoiceValue]
      ,[Quarantine]
      ,[S_QTY]
      ,[S_P]
      ,[S_Total]
      ,[S_PU]
      ,[Prime]
      ,[WO]
	  )
SELECT [Size_H]
      ,[Size_L]
      ,[PC]
      ,[Dim1]
      ,[Dim2]
      ,[Dim3]
      ,[Length]
      ,[Weight]
      ,[CostValue]
      ,[Descript]
      ,[Location]
      ,[FloorStatus]
      ,[Class]
      ,[Unit]
      ,[RandLen]
      ,GETDATE()
      ,@nNewID

      ,[ReceivingID]
      ,[LiveCheck]
      ,[AccountingCheck]
      ,[InvoiceValue]
      ,[Quarantine]
      ,[S_QTY]
      ,[S_P]
      ,[S_Total]
      ,[S_PU]
      ,[Prime]
      ,[WO]
  FROM dbo.StockLst_Detail D
   WHERE D.[ID] = @ID


SET @nNewID_Detail = SCOPE_IDENTITY()
PRINT @nNewID_Detail

IF @nNewID_Detail < 1
	BEGIN
		SET @nReturnCode = -5
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.BrokerLst_Detail '
		ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		RETURN @nReturnCode
	END

----------------------------------
--PRINT 'Update Detail'


-----------------------------------
PRINT 'Move Process'
INSERT INTO dbo.BrokerLst_Process
	(
	   [SOitem]
      ,[PO_item]
      ,[SalesPerson]
      ,[StartDate]
      ,[DueDate]
      ,[Comment]
      ,[Process_ID]
      ,[Processor]
      ,[AllowSub]
      
      ,[PU]
      ,[QTY]
      ,[Ordered_QTY]
      ,[Ordered_P]
      ,[Pounds]
      ,[ID_Detail]
      
      ,[ReceivingID]
      ,[WO]
      ,[WO_Detail]
      ,[InqNumP]
      
      ,[Prc_Form]
      ,[Prc_PCs]
      ,[Prc_Dim1]
      ,[Prc_Dim2]
      ,[Prc_Dim3]
      ,[Prc_Q_QTY]
      ,[Prc_Q_PU]
	  ,[FoundSTK]
	)
SELECT [SOitem]
      ,[PO_item]
      ,[SalesPerson]
      ,GETDATE()
      ,[DueDate]
      ,'Moved from StockLst ID:'+CAST(@ID AS CHAR(10))
      ,[Process_ID]
      ,[Processor]
      ,[AllowSub]
      
      ,[PU]
      ,[QTY]
      ,[Ordered_QTY]
      ,[Ordered_P]
      ,[Pounds]
      ,@nNewID_Detail
      
      ,P.[ReceivingID]
      ,P.[WO]
      ,P.[WO_Detail]
      ,P.[InqNumP]
      
      ,[Prc_Form]
      ,[Prc_PCs]
      ,[Prc_Dim1]
      ,[Prc_Dim2]
      ,[Prc_Dim3]
      ,[Prc_Q_QTY]
      ,[Prc_Q_PU]
	  ,[FoundSTK]
  FROM dbo.StockLst_Process P
  inner Join dbo.StockLst_Detail D ON P.ID_Detail = D.ID_Detail
   WHERE D.[ID_Detail] = @ID_Detail

SET @nNewID_Detail_Process = SCOPE_IDENTITY()
PRINT @nNewID_Detail_Process


IF @nNewID_Detail_Process < 1
	BEGIN
		SET @nReturnCode = -6
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.BrokerLst_Process'
		ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		RETURN @nReturnCode
	END
------------------------------------------------------------

--MWeight=0,  Calc from Detail  --WHY
PRINT 'UPDATE dbo.BrokerLst_Master SET MWeight=0 WHERE ID = @nNewID'
UPDATE dbo.BrokerLst_Master SET MWeight = dbo.f_GetMWeight_BrokerLst_ID(@nNewID) WHERE ID = @nNewID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR
IF @err <> 0
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to UPDATE dbo.BrokerLst_Master SET MWeight=0 WHERE ID = @nNewID'
		ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		RETURN @nReturnCode
	END


------------------------------------------------------------
PRINT 'Add Process Detail for BrokerLst_Detail Delete'
INSERT INTO dbo.BrokerLst_Process_Detail 
    ( [What], [ID], [ID_Detail], [ID_Detail_Process] ) 
SELECT 'ADD'
	, @nNewID
	, @nNewID_Detail
	, @nNewID_Detail_Process
	--, SD.WO, SD.SOitem
FROM dbo.BrokerLst_Master M WITH (NOLOCK)
	inner Join dbo.BrokerLst_Detail D WITH (NOLOCK) ON M.ID = D.ID
	WHERE D.[ID_Detail] = @ID_Detail

SELECT @RC = @@ROWCOUNT, @err = @@ERROR
IF @err <> 0
	BEGIN
		SET @nReturnCode = -7
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to UPDATE dbo.BrokerLst_Process_Detail'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END


----------------------------------
PRINT 'Insert dbo.Ar_StockLst_Process_History to show WHAT as MOVED'

INSERT INTO dbo.Ar_StockLst_Process_History  
	([What], Comment, Process_ID, [ID_Detail], [Removed], ReceivingID, WO ) 
	 SELECT 'MOVED', 'Moved to BrokerLst from StockLst', 'Moved', P.ID_Detail, GetDate(), P.ReceivingID, P.WO 
	 FROM dbo.StockLst_Process P 
		inner Join dbo.StockLst_Detail D  ON P.ID_Detail = D.ID_Detail
		WHERE D.[ID] = @ID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -9
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))

		PRINT 'Error = '+CAST(@err AS CHAR(10))
		PRINT 'RowCount = '+CAST(@RC AS CHAR(10))
		--PRINT '@Process_ID = '+ISNULL(@Process_ID,'NULL')

		PRINT 'Failed to INSERT StockLst_Process_History'
		SET @Body = @Body + 'Failed to INSERT StockLst_Process_History' +CHAR(13)

		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		--RETURN @nReturnCode
		PRINT 'Continuing with the MOVE.'
	END

PRINT 'COMMIT TRANSACTION Move_StockLst_BrokerLst'
COMMIT TRANSACTION Move_StockLst_BrokerLst
BEGIN TRANSACTION Move_StockLst_BrokerLst






--**********************************
-- Now DELETE StockLst
--**********************************

PRINT 'Delete StockLst_Process '

--StockLst_Process  Process_ID = 'INCOMING  '
DELETE FROM dbo.StockLst_Process 
WHERE [ID_Detail] IN 
	(SELECT DISTINCT D.ID_Detail FROM
		dbo.StockLst_Master M WITH(NOLOCK)
		INNER JOIN dbo.StockLst_Detail D WITH(NOLOCK) ON M.ID = D.ID 
		WHERE M.[ID] = @ID )
	

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -8
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to Delete StockLst_Process'
		SET @Body = @Body + 'Failed to Delete StockLst_Process.'+CHAR(13)

		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		--RETURN @nReturnCode
		PRINT 'Continue with MOVE.'
	END
	
-------------------------------------
PRINT 'StockLst_Process DELETE - Anything by ID_Detail'

DELETE FROM dbo.StockLst_Detail 
	WHERE ID_Detail IN (SELECT DISTINCT D.ID_Detail 
		FROM dbo.StockLst_Master M 
		INNER JOIN dbo.StockLst_Detail D ON M.ID = D.ID 
		WHERE M.[ID] = @ID )



SELECT @RC = @@ROWCOUNT, @err = @@ERROR


IF @err <> 0
	BEGIN
		SET @nReturnCode = -11
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to DELETE StockLst_Detail WHERE ID_Detail = '+CAST(@ID_Detail AS CHAR(10))
		SET @Body = @Body + 'Failed to DELETE StockLst_Detail WHERE ID_Detail = '+CAST(@ID_Detail AS CHAR(10)) +CHAR(13)
				
		SET @nReturnCode = 0
		--ROLLBACK TRANSACTION Move_StockLst_BrokerLst
		--RETURN @nReturnCode
		PRINT 'Continue with MOVE.'
	END

----------------------------------
IF @nReturnCode > 0
	PRINT 'DELETE the StockLst_Master WHERE [ID] = @ID'
	DELETE FROM dbo.StockLst_Master WHERE [ID] = @ID

	SELECT @RC = @@ROWCOUNT, @err = @@ERROR

	IF @err <> 0
 		BEGIN
			SET @nReturnCode = -12
			PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
			PRINT 'Failed to DELETE the StockLst_Master WHERE [ID] = '+CAST(@ID AS CHAR(10))	
			SET @Body = @Body + 'Failed to DELETE the StockLst_Master WHERE [ID] = '+CAST(@ID AS CHAR(10)) +CHAR(13)

			SET @nReturnCode = 0
			--ROLLBACK TRANSACTION Move_StockLst_BrokerLst
			--RETURN @nReturnCode
			PRINT 'Continue with MOVE.'
		END


----------------------------------
--Email Error			

DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()

IF LEN(@Body) > 1
begin

	SET @Body = @Body+CHAR(13)
		+'User '+RTRIM(suser_sname())+' on '+RTRIM(CAST(GETDATE()AS CHAR))+' '+CHAR(13)
		+@@SERVERNAME+' TRIGGER '+' p_Move_StockLst_BrokerLst '+CHAR(13)
		+' [ID] = '+CAST(@ID AS CHAR(10))
		+' [ID_Detail] = '+CAST(@ID_Detail AS CHAR(10))+CHAR(13)
		+' [@nNewID] = '+CAST(@nNewID AS CHAR(10))
		+' [@nNewID_Detail] = '+CAST(@nNewID_Detail AS CHAR(10))


	EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'Admin.Alerts@ERP_1s.com;David.Kirchner@ERP_1s.com', 
	@SubjectEmail = 'p_Move_StockLst_BrokerLst.',
		@BodyEmail = @Body,
		@BodyType = 'TEXT'
					
	RAISERROR( @Body, 16, -1)

end
----------------------------------

IF @nReturnCode < 0
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
	 SELECT @nReturnCode
     PRINT 'ROLLBACK TRANSACTION MoveStockLst_BrokerLst'
     ROLLBACK TRANSACTION Move_StockLst_BrokerLst
    end
ELSE
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
     SET @nReturnCode = @nNewID_Detail
     SELECT @nReturnCode
     PRINT 'COMMIT TRANSACTION Move_StockLst_BrokerLst'
     COMMIT TRANSACTION Move_StockLst_BrokerLst
	end
	
RETURN @nReturnCode



