ALTER    PROCEDURE [dbo].[p_Move_WIPLst_StockLst]
	@ID		int,
	@ID_Detail	int
AS

Set NoCount On

--DECLARE	@ID		int
--DECLARE	@ID_Detail	int
--
--SET @ID = 116
--SET @ID_Detail = 103
--
--EXEC p_Move_WIPLst_StockLst @ID, @ID_Detail
--EXEC p_Move_WIPLst_StockLst 4133,3966

--RETURN CODES
-- 0 No Scope Identity
-- 1 NO ID
-- 2 NO ID_Detail
-- 3 
-- 4 StockLst_Master Did not Insert
-- 5 StockLst_Detail Did not Insert
-- 6 StockLst_Process Did not Insert
-- 7 StockLst_Detail_Process Did not Insert
-- 8 Could not Delete WIPlst_Process
-- 9 Could not UPDATE WIPlst_Process_History  
-- 10 Could not Delete WIPlst_Process_Detail
-- 11 Could not Delete WIPlst_Detail
-- 12 Could not Delete WIPlst_Master

DECLARE @nSCOPE_IDENTITY AS INT
DECLARE @nReturnCode AS INT
SET @nReturnCode = 0

DECLARE @err INT
SET @err = 0
DECLARE @RC INT
SET @rc = 0
--select @RC = @@ROWCOUNT, @err = @@ERROR

DECLARE @nNewID INT
DECLARE @nNewID_Detail INT
DECLARE @nNewID_Detail_Process INT

--Check INPUTS
IF NOT EXISTS (SELECT [ID] FROM dbo.WIPLst_Master WITH(NOLOCK) WHERE [ID] = @ID )
	BEGIN
		SET @nReturnCode = -1
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

IF NOT EXISTS (SELECT [ID_Detail] FROM dbo.WIPLst_Detail WITH(NOLOCK) WHERE [ID_Detail] = @ID_Detail )
	BEGIN
		SET @nReturnCode = -2
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

--SET @nReturnCode = -3

BEGIN TRANSACTION Move_WIPLst_StockLst
----------------------------------
PRINT 'ADD Master'
INSERT INTO dbo.StockLst_Master 
	([Alloy],[Form],[cc],[CL],[Size],[Cond],[MWeight],[specs],[Heat],[Lot],[PAID],[PO_Item]
	,[PODueDate],[Mill],[StkDate],[History],[Num],[POStatus],[BrandName],[MillTrace],[From_ID]
	,Melt,mS_QTY,WO_Detail)
SELECT [Alloy],[Form],[cc],[CL],[Size],[Cond],[MWeight],[specs],[Heat],[Lot],[PAID],[PO_Item]
	,[PODueDate],[Mill],GetDate(),[History],[Num],[POStatus],[BrandName],[MillTrace],[From_ID]
	,Melt,mS_QTY,WO_Detail 
   FROM dbo.WIPLst_Master WITH(NOLOCK) 
   WHERE [ID] = @ID


SET @nNewID = SCOPE_IDENTITY()
PRINT 'NewID '+CAST(@nNewID AS CHAR(10));
SET @nReturnCode = @nNewID

IF @nNewID < 1
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))+'. Failed to INSERT INTO dbo.StockLst_Master'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END
	
----------------------------------
--MWeight=0,  Calc from Detail
PRINT 'UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID'
UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR
IF @err <> 0
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to UPDATE dbo.StockLst_Master SET MWeight=0 WHERE ID = @nNewID'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END

--Change the WIPlst_Detail ID to show the new StockLst ID, before the Add Detail
--UPDATE dbo.WIPlst_Detail SET ID = @nNewID WHERE [ID_Detail] = @ID_Detail

----------------------------------
PRINT 'Add Detail, NOT null fields'
INSERT INTO dbo.StockLst_Detail 
	(Dim1,[Weight],costvalue,unit,RandLen,ID,InvoiceValue,LiveCheck,AccountingCheck,Quarantine) VALUES 
	(0     ,0        ,0     ,''    ,0 ,@nNewID   ,0           ,0            ,0          ,0)

SET @nNewID_Detail = SCOPE_IDENTITY()
PRINT '@nNewID_Detail '+CAST(@nNewID_Detail AS CHAR(10));

IF @nNewID_Detail < 1
	BEGIN
		SET @nReturnCode = -5
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.StockLst_Detail blank'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END

----------------------------------
PRINT 'Update Detail'
DECLARE @size_h [decimal](9, 4),
	@size_l [decimal](9, 4),
	@pc [INT],
	@dim1 [decimal](18, 4),
	@dim2 [decimal](18, 4),
	@dim3 [decimal](18, 4),
	@length [char](160),
	@weight [decimal](18,8),
	@costvalue [money],
	@descript [char](20) ,
	@location [char](10) ,
	@floorstatus [char](1) ,
	@class [char](1),
	@unit [char](6),
	@RandLen [bit] ,
	@InvCheck [datetime],
	@ReceivingID [int] ,
	@InvoiceValue [money],
	@Quarantine [bit]
DECLARE @S_QTY [money],
	@S_P [money],
	@S_Total [money],
	@S_PU [tinyint],
	@Prime [bit],
	@WO	[INT]
	
SELECT @size_h=dbo.f_Return_Higher_Num ([size_h], Dim1)
	,@size_l=dbo.f_Return_Lower_Num ([size_l], Dim1)
	,@pc=[pc]
	,@Dim1=[dim1]
	,@Dim2=[dim2]
	,@Dim3=[dim3]
	,@Length=[length]
	,@Weight=[weight]
	,@CostValue=[costvalue]
	,@Descript=[descript]
	,@Location=[location]
	,@FloorStatus=[floorstatus]
	,@Class=[class]
	,@Unit=ISNULL([unit],' ')
	,@RandLen=[RandLen]
	,@InvCheck=GETDATE()
	,@ReceivingID=ISNULL([ReceivingID],0)
	,@InvoiceValue=[InvoiceValue]
	,@Quarantine=[Quarantine]
	,@S_QTY=ISNULL([S_QTY],0)
	,@S_P=ISNULL([S_P],0)
	,@S_Total=ISNULL([S_Total],0)
	,@S_PU=ISNULL([S_PU],0)
	,@Prime=[Prime]
	,@WO=0  --ISNULL([WO],0)
   FROM dbo.WIPLst_Detail WITH(NOLOCK) 
   WHERE [ID_Detail] = @ID_Detail 
   
SET @InvCheck = GETDATE()
   
UPDATE dbo.StockLst_Detail SET 
   [size_h]=@Size_H,[size_l]=@Size_L,[pc]=@PC,[dim1]=@Dim1,[dim2]=@Dim2,[dim3]=@Dim3,
   [length]=@Length,[weight]=@Weight,[costvalue]=@CostValue,[descript]=@Descript,
   [location]=@Location,[floorstatus]=@FloorStatus,[class]=@Class,[unit]=@Unit,
   [RandLen]=@RandLen,[InvCheck]=@InvCheck,[ReceivingID]=@ReceivingID,
   [InvoiceValue]=@InvoiceValue,[LiveCheck]=0,[AccountingCheck]=0,[Quarantine]=@Quarantine
   	,[S_QTY]=@S_QTY
	,[S_P]=@S_P
	,[S_Total]=@S_Total
	,[S_PU]=@S_PU
	,[Prime]=@Prime
   WHERE [ID_Detail] = @nNewID_Detail

SELECT @RC = @@ROWCOUNT, @err = @@ERROR
IF @err <> 0
	BEGIN
		SET @nReturnCode = -5
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to UPDATE dbo.StockLst_Detail'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END

--PRINT 'UPDATE dbo.StockLst_Detail SET ReceivingID = 0 WHERE ID_Detail = @nNewID_Detail'
--UPDATE dbo.StockLst_Detail SET ReceivingID = @ReceivingID WHERE ID_Detail = @nNewID_Detail
--ReceivingID = 0

DECLARE @Comment VARCHAR(100)
SET @Comment = 'Moved from WIPLst ID:'+CAST(@ID AS CHAR(10))

----------------------------------
PRINT 'Add Process'
INSERT INTO dbo.StockLst_Process
    ([StartDate], [comment], [Process_ID], [Processor], [AllowSub], [pWeight], [pPc], [ID_Detail], [ReceivingID]) VALUES
    (GETDATE(), @Comment, 'RECEIVED', 'ShopEdit', 'N', 0, 0, @nNewID_Detail, @ReceivingID)

SET @nNewID_Detail_Process = SCOPE_IDENTITY()
PRINT '@nNewID_Detail_Process '+CAST(@nNewID_Detail_Process AS CHAR(10));

IF @nNewID_Detail_Process < 1
	BEGIN
		SET @nReturnCode = -6
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.StockLst_Process'
		ROLLBACK TRANSACTION Move_WIPLst_StockLst
		RETURN @nReturnCode
	END

----------------------------------
PRINT 'Add Process Detail'
INSERT INTO dbo.StockLst_Process_Detail 
    ( [What], [ID], [ID_Detail], [ID_Detail_Process] ) VALUES 
    ( 'ADD', @nNewID, @nNewID_Detail, @nNewID_Detail_Process )

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -7
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to (Add Process Detail) INSERT INTO dbo.StockLst_Process_detail '
	END
	
--*****************
-- DELETE
--*****************

----------------------------------
PRINT  'Move WIPLst SELECTED process to the new StockLst_Process if SOitem not STOCK'

INSERT INTO dbo.StockLst_Process 
	([SOitem],[PO_Item],[SalesPerson],[StartDate],[duedate], [comment],[Process_ID],[Processor]
		, [AllowSub],[pWeight], [pPc],[ID_Detail],[ReceivingID],[WO])
SELECT [SOitem],[PO_Item],[SalesPerson], GETDATE() AS [StartDate],[duedate], 'Moved from WIPLst' AS [comment], 'SELECTED  ' AS [Process_ID], 'ShopEdit' AS [Processor]
		, [AllowSub],[pWeight], [pPc], @nNewID_Detail AS [ID_Detail], @ReceivingID AS [ReceivingID],[WO]
		FROM dbo.WIPLst_Process WITH(NOLOCK) 
		WHERE [ID_Detail] = @ID_Detail AND Process_ID = 'SELECTED  '
		AND NOT ( [SOitem] LIKE 'STOCK%' OR [SOitem] LIKE 'ConvertSVC%' )

----------------------------------    
PRINT 'WIPlst_Process DELETE SELECTED  '
DELETE FROM dbo.WIPLst_Process WHERE [ID_Detail] = @ID_Detail
	--AND Process_ID = 'SELECTED  '   --All Process need to go!

----------------------------------
PRINT 'Update dbo.Ar_WIPlst_Process_History to show WHAT as MOVED'

INSERT INTO dbo.Ar_WIPLst_Process_History  
	([What], Comment, [Process_ID], [ID_Detail], [Removed], [Validated], ReceivingID, WO )
	 VALUES ( 'MOVED', 'Moved to StockLst from WIPLst', 'MOVE', @ID_Detail, GetDate(), ' ', @ReceivingID, @WO )

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -9
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to Update WIPlst_Process_History to show as MOVED'
	END

----------------------------------
PRINT 'Update dbo.Ar_WIPlst_Master_History to show as MOVED'
UPDATE dbo.Ar_WIPLst_Master_History  
	SET [Specs] = 'Moved to StockLst ID:'+CAST(@nNewID AS CHAR(10))
	WHERE [ID] = @ID
	AND [What] = 'DELETE'

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -9
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to Update WIPlst_Process_History to show as MOVED'
	END
	
----------------------------------	
PRINT 'WIPlst_Process DELETE - Anything not INCOMING or SELECTED'
DELETE FROM dbo.WIPLst_Process WHERE [ID_Detail] = @ID_Detail

SELECT @RC = @@ROWCOUNT, @err = @@ERROR


IF @err <> 0
	BEGIN
		SET @nReturnCode = -11
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to WIPlst_Process DELETE'
	END

----------------------------------
PRINT 'DELETE the WIPlst_Master WHERE [ID] = @ID'
DELETE FROM dbo.WIPlst_Master WHERE [ID] = @ID

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
 	BEGIN
		SET @nReturnCode = -12
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to DELETE the WIPlst_Master WHERE [ID] = @ID'
	END


----------------------------------

IF @nReturnCode < 0
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
	 SELECT @nReturnCode
     PRINT 'ROLLBACK TRANSACTION Move_WIPlst_StockLst'
     ROLLBACK TRANSACTION Move_WIPlst_StockLst
    end
ELSE
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
     SET @nReturnCode = @nNewID_Detail
     SELECT @nReturnCode
     PRINT 'COMMIT TRANSACTION Move_WIPlst_StockLst'
     COMMIT TRANSACTION Move_WIPlst_StockLst
	end
	
RETURN @nReturnCode







GO
/****** Object:  StoredProcedure [dbo].[p_OT_Migration]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_OT_Migration]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_OT_Migration] AS' 
END
GO
-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 11/25/2018
-- Description:	Used to migrate OT data from NR to ERP_1 with the new data structure. Accepts a maxdate to import data from before the date
-- =============================================
ALTER PROCEDURE [dbo].[p_OT_Migration] 
	-- Add the parameters for the stored procedure here
	@maxdate datetime
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	declare @OldTrackId uniqueidentifier
		,@NewTrackId int
		,@orderNumber varchar(15)
		,@NewJobId int
		,@NewOrderTypeId varchar(4)
		,@StartTime datetime
		,@Start_StatusId int
		,@StopTime datetime
		,@Stop_StatusId int
		,@NewTimeId int
	declare MyCursor cursor for 
		SELECT ot.[trackID]
			,RTRIM(LTRIM([orderItem])) AS [orderItem]
			,otj2.[JobId]
			,otot2.[OrderTypeId]
		FROM [dbo].[OT] ot
		left outer join [dbo].[OT_Migration] otm on ot.trackID = otm.OldTrackId
		join [dbo].[OT_OrderType] otot on ot.orderType = otot.Id
		join [dbo].[OT_OrderType] otot2 on otot.OrderType = otot2.TypeAbr
		join [dbo].[OT_Job] otj on ot.jobID = otj.jobID
		join [dbo].[OT_Job] otj2 on otj.jobDescription = otj2.Description
		left outer join [dbo].[OT_Time] ott on ot.trackID = ott.trackID
		where otm.OldTrackId is null AND ott.[status] = 'start' AND ott.time < @maxdate
		order by ott.[time]

	open MyCursor
	FETCH NEXT FROM MyCursor INTO @OldTrackId, @orderNumber, @NewJobId, @NewOrderTypeId
	while @@FETCH_STATUS = 0 
	begin
		insert into [dbo].[OT] (OrderNumber, JobId, OrderTypeId)
		values (@orderNumber, @NewJobId, @NewOrderTypeId)
		SELECT @NewTrackId = TrackId FROM [dbo].[OT] WHERE TrackId = @@Identity;

		if (@NewTrackId is null) return

		insert into [dbo].[OT_Migration] (OldTrackId, NewTrackId)
		values (@OldTrackId, @NewTrackId)

		-- Cursor to insert time and Employee data
		declare TrackingTimeCursor cursor for 
			SELECT [time] AS [StartTime]
				,otts.StatusId AS [Start_StatusId]
					,(SELECT min(ott2.[time])
						FROM [dbo].[OT_Time] ott2
						where ott2.trackID = ott.trackID
						AND ([status] = 'pause' OR [status] = 'finish')
						AND ott2.[time] > ott.[time]
					) AS [StopTime]
					,(SELECT TOP (1) otts2.[StatusId]
						FROM [dbo].[OT_Time] ott2
						join [dbo].[OT_Times_Status] otts2 on ott2.[status] = otts2.[Status]
						where ott2.trackID = ott.trackID
						AND (ott2.[status] = 'pause' OR ott2.[status] = 'finish')
						AND ott2.[time] in (SELECT min(ott3.[time])
							FROM [dbo].[OT_Time] ott3
							where ott3.trackID = ott.trackID
							AND ([status] = 'pause' OR [status] = 'finish')
							AND ott3.[time] > ott.[time]
						)
					) AS [Stop_StatusId]
			FROM [dbo].[OT_Time] ott
			join [dbo].[OT_Times_Status] otts on ott.[status] = otts.[Status]
			where trackID = @OldTrackId
			AND (ott.[status] = 'start' OR ott.[status] = 'resume')
			order by [time]

		open TrackingTimeCursor
		FETCH NEXT FROM TrackingTimeCursor INTO @StartTime, @Start_StatusId, @StopTime, @Stop_StatusId
		while @@FETCH_STATUS = 0 
		begin
			insert into [dbo].[OT_Times] (StartTime, Start_StatusId, StopTime, Stop_StatusId, TrackId)
			values (@StartTime, @Start_StatusId, @StopTime, @Stop_StatusId, @NewTrackId)
			SELECT @NewTimeId = TimeId FROM [dbo].[OT_Times] WHERE TimeId = @@Identity;

			if (@NewTimeId is null) return

			insert into [dbo].[OT_Times_Employees] (EmployeeId, TimeId, TrackId)
			SELECT EmployeeId, @NewTimeId, @NewTrackId
			FROM [dbo].[OT_Employee] ote
			WHERE ote.trackID = @OldTrackId

			FETCH NEXT FROM TrackingTimeCursor INTO @StartTime, @Start_StatusId, @StopTime, @Stop_StatusId
		end
		close TrackingTimeCursor
		DEALLOCATE TrackingTimeCursor

		FETCH NEXT FROM MyCursor INTO @oldTrackId, @orderNumber, @NewJobId, @NewOrderTypeId
	end
	close MyCursor
	DEALLOCATE MyCursor
END

