ALTER PROCEDURE [dbo].[p_Process_QTY]
(
@ID_Detail	INT
)
AS
BEGIN

--Returns QTY and Weight for StockLst ID_Detal, and Summary of Process against it!
--EXEC dbo.p_Process_QTY 23185


DECLARE @MasterLB	INT,
	@MasterQTY INT,
	@MProcQTY	INT ,
	@MProcPounds INT,
	@DetailLB	INT,
	@DetailQTY INT,
	@DProcQTY	INT,
	@DProcPounds INT


SET NOCOUNT ON

DECLARE @err INT,
        @RC INT

SET @err = 0
SET @RC = 0

DECLARE @MasterID INT

SELECT @MasterLB = M.mWeight, @MasterID = M.ID, @MasterQTY = D.S_QTY FROM dbo.StockLst_Master M, dbo.StockLst_Detail D WHERE M.ID = D.ID AND D.ID_Detail = @ID_Detail

SELECT @MasterQTY = SUM(D.S_QTY) FROM dbo.StockLst_Detail D WHERE D.ID_Detail = @ID_Detail

SELECT @MProcQTY = SUM(P.QTY) 
	,@MProcPounds = SUM(P.Pounds) 
	FROM dbo.StockLst_Master M, dbo.StockLst_Detail D, dbo.StockLst_Process P 
	WHERE M.ID = @MasterID AND D.ID = M.ID AND P.ID_Detail = D.ID_Detail
	AND ( P.Process_ID  = 'SELECTED' 
		OR P.Process_ID  = 'Shipped'
		OR P.Process_ID  = 'Partl Ship' )

SELECT @DetailLB = Weight, @DetailQTY = S_QTY FROM dbo.StockLst_Detail WHERE ID_Detail = @ID_Detail 

SELECT @DProcQTY = SUM(QTY) FROM dbo.StockLst_Process 
	WHERE ID_Detail = @ID_Detail 
	AND ( Process_ID  = 'SELECTED' 
		OR Process_ID  = 'Shipped'
		OR Process_ID  = 'Partl Ship' )

SELECT @DProcPounds = SUM(Pounds) FROM dbo.StockLst_Process 
	WHERE ID_Detail = @ID_Detail 
	AND ( Process_ID  = 'SELECTED' 
		OR Process_ID  = 'Shipped'
		OR Process_ID  = 'Partl Ship' )

--NOT 'INCOMING','PARTRECV','CORRECTION','Receiving'

SELECT @MasterLB AS MasterLBS,
	@MasterQTY AS MasterQTY,
	@DetailLB AS DetailLBS,
	@DetailQTY AS DetailQTY,
	@MProcPounds AS MProcLBS,
	@MProcQTY AS MProcQTY,
	@DProcPounds AS DProcLBS,
	@DProcQTY AS DProcQTY
	
END



GO
