ALTER PROCEDURE [dbo].[p_PurchaseOrder_Change_POitem]
(
@NewPOitem	CHAR(12),
@OldPOitem	CHAR(12)
)
AS
BEGIN
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501918-01','  5001067-01'
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501918-02','  5001067-02'
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501918-03','  5001067-03'
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501141-01','  5001069-01'

SET NOCOUNT ON

DECLARE @err INT,
        @RC INT

SET @err = 0
SET @RC = 0

DECLARE @Count INT


--SELECT @Count = COUNT(*) FROM dbo.PurchaseOrder WHERE POitem = @NewPOitem
--IF @Count > 0
--	begin
--	PRINT 'New PO item:'+@NewPOitem+' allready exist, cannot use!'  
--	RETURN
--	end

	
DECLARE @NewHPAPO INT
SET @NewHPAPO = CAST(LEFT(@NewPOitem,9) AS INT)
DECLARE @OldHPAPO INT	
SET @OldHPAPO = CAST(LEFT(@OldPOitem,9) AS INT)


BEGIN TRAN Change_POitem WITH MARK 'p_PurchaseOrder_Change_POitem'

SELECT @Count = COUNT(*) FROM dbo.AllQuotes WHERE POitem = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in AllQuotes'
	UPDATE dbo.AllQuotes SET HPAPO = @NewHPAPO WHERE HPAPO = @OldHPAPO
  END
	
SELECT @Count = COUNT(*) FROM dbo.WorkOrder WHERE POitem = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in WorkOrder'
	UPDATE dbo.WorkOrder SET POitem = @NewPOitem WHERE POitem = @OldPOitem 
  END
	
SELECT @Count = COUNT(*) FROM dbo.StartingStock WHERE POitem = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in StartingStock'
	UPDATE dbo.StartingStock SET POitem = @NewPOitem WHERE POitem = @OldPOitem 
  END

SELECT @Count = COUNT(*) FROM dbo.PurchaseOrder WHERE POitem = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in PurchaseOrder'
    UPDATE dbo.PurchaseOrder SET POitem = @NewPOitem, HPAPO = @NewHPAPO WHERE POitem = @OldPOitem 
  END
  
SELECT @Count = COUNT(*) FROM dbo.BrokerLst_Master WHERE PO_item = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in BrokerLst_Master'
    UPDATE dbo.BrokerLst_Master SET PO_Item = @NewPOitem WHERE PO_item = @OldPOitem 
  END
  
SELECT @Count = COUNT(*) FROM dbo.StockLst_Master WHERE PO_item = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in StockLst_Master'
    UPDATE dbo.StockLst_Master SET PO_Item = @NewPOitem WHERE PO_item = @OldPOitem
  END
   
SELECT @Count = COUNT(*) FROM dbo.BrokerLst_Process WHERE PO_item = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in BrokerLst_Process'
    UPDATE dbo.BrokerLst_Process SET PO_item = @NewPOitem WHERE PO_item = @OldPOitem 
  END

SELECT @Count = COUNT(*) FROM dbo.StockLst_Process WHERE PO_item = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in StockLst_Process'
    UPDATE dbo.StockLst_Process SET PO_item = @NewPOitem WHERE PO_item = @OldPOitem 
  END

SELECT @Count = COUNT(*) FROM dbo.StockLst_Value WHERE POitem = @OldPOitem
IF @Count > 0
  BEGIN
	PRINT 'Change in StockLst_Value'
    UPDATE dbo.StockLst_Value SET POitem = @NewPOitem WHERE POitem = @OldPOitem 
  END
    
--    UPDATE dbo.UserTrack SET MESS1 = @NewPOitem WHERE mess1 Like '%PO '+LTRIM(RTRIM(@OldPOitem))+'%'

INSERT INTO dbo.NR_UserTrack (mess1,cProgram) VALUES (LEFT('Changed POitem from:'+@OldPOitem+' to '+@NewPOitem,1024),'dbo.p_PurchaseOrder_Change_POitem')  
	
PRINT 'Changed POitem from:'+@OldPOitem+' to '+@NewPOitem
	
COMMIT TRAN Change_POitem
    
--	END
--ELSE
--  PRINT 'PO item:'+@OldPOitem+' was not Found!'  
 
/*
DECLARE @OldPOitem	CHAR(12)
SET @OldPOitem = '  5000000-01'
SELECT * FROM dbo.AllQuotes WHERE POitem > @OldPOitem
SELECT * FROM dbo.WorkOrder WHERE POitem > @OldPOitem
SELECT * FROM dbo.StartingStock WHERE POitem > @OldPOitem
SELECT * FROM dbo.PurchaseOrder WHERE POitem > @OldPOitem
SELECT * FROM dbo.BrokerLst_Master WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Master WHERE PO_item > @OldPOitem 
SELECT * FROM dbo.BrokerLst_Process WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Process WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Value WHERE POitem > @OldPOitem
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501918-03','
*/
RETURN
END

