-- =============================================
-- Author:		Sean Lykins
-- Create date: 2015 April 13
-- Description:	for PR 62-01 [QA_CP_Action]
-- =============================================
ALTER PROCEDURE [dbo].[p_QA_PR_62_01] 
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
DECLARE @startMonthDate DATETIME = DATEADD(year, -2, GETDATE())

		SELECT cpa.[ActionID]
		  ,[Action_Type]
		  ,[Date_Initiated]
		  ,[Problem_Description]
		  ,[Abridged_Problem_Description]
		  ,[Root_Cause]
		  ,[Disposition]
		  ,[Prevention]
		  ,[Interim_Date]
		  ,[Filed_Date]
		  ,[Closed_Date]
		  ,[Contact_Name]
		  ,[Contact_Type]
		  ,d.Disposition_Name
		  ,cpapo.POItem
		  ,p.Prevention_Name
		  ,cpars.Reporting_Source_Description
		  ,rs.ReportingSourceName
		  ,rcs.RootCause_Name
		  ,od.Dept_Name
		  ,cpaso.SOItem
	  FROM [dbo].[QA_CP_Action] cpa
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_Disposition_Type cpad on cpa.ActionID = cpad.ActionID
	  LEFT JOIN ERP_2.dbo.QA_Disposition_Types d on cpad.DispositionID = d.DispositionID
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_PO_Items cpapo on cpa.ActionID = cpapo.ActionID
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_Prevention_Type cpap on cpa.ActionID = cpap.ActionID
	  LEFT JOIN ERP_2.dbo.QA_Prevention_Types p on cpap.PreventionID = p.PreventionID
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_Reporting_Source cpars on cpa.ActionID = cpars.ActionID
	  LEFT JOIN ERP_2.dbo.QA_Reporting_Source rs on cpars.ReportingSourceID = rs.ReportingSourceID
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_RootCauseSource_OrgDept cparcs on cpa.ActionID = cparcs.ActionID
	  LEFT JOIN ERP_2.dbo.QA_RootCause_Source rcs on cparcs.RootCauseID = rcs.RootCauseID
	  LEFT JOIN ERP_2.dbo.QA_Org_Dept od on od.DeptID = cparcs.DeptID
	  LEFT JOIN ERP_2.dbo.QA_CP_Action_SO_Items cpaso on cpa.ActionID = cpaso.ActionID
	  WHERE [Filed_Date] > @startMonthDate
	  AND Action_Type = 'C'
	  AND LOWER(p.Prevention_Name) LIKE '%refresher training%'
	  ORDER BY [Date_Initiated] desc
END
GO
