-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 06/06/2019
-- Description:	Queries and returns a dataset for reports
--
-- Updated:
-- 07/08/2019:	@filterCanceled now does not filter out canceled orders within the date range
-- 07/09/2019:	@includeOpen is now ignored. Dave Morrow wants to always show open, non-canceled orders, regardless of date range.
--				All orders within the date range will be shown, regardless of status.
-- 08/13/2019:	@includeOpen is no longer ignored. Dave Morrow wants to always show open orders from the current date range and previous open orders, but not future.
-- =============================================
ALTER PROCEDURE [dbo].[p_QA_PR_75_02_WParams] 
	-- Add the parameters for the stored procedure here
	@dateMin datetime
	,@dateMax datetime
	,@includeOpen bit
	,@filterCanceled bit
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    --Insert statements for procedure here
	--declare @dateMin datetime = '7/1/2019',
	--		@dateMax datetime = '7/30/2019',
	--		@includeOpen bit = 1,
	--		@filterCanceled bit = 0

	SELECT [QA_PS_ID]
		  ,[QA_PS_Description]
		  ,[QA_PS_HoldDate]
		  ,[QA_PS_DateReleased]
	FROM [dbo].[QA_Packaging_Shipping] ps
	WHERE 
	(
		-- We Want to include everything in the date range
		[QA_PS_HoldDate] >= @dateMin
		AND [QA_PS_HoldDate] <= @dateMax
	)
	OR 
	(	
		-- We want to include **ALL** OPEN ORDERS that are before and within the date range and have not been canceled
		[QA_PS_DateReleased] is NULL 
		--AND @includeOpen = 1
		AND [QA_PS_HoldDate] <= @dateMax
		AND [QA_PS_Description] not like '%CANCELED%'
	)
	OR 
	(	
		-- We want to include **ALL** OPEN ORDERS if includeOpen is true
		@includeOpen = 1
		AND [QA_PS_DateReleased] is NULL 
		AND [QA_PS_Description] not like '%CANCELED%'
	)
	OR 
	(
		--IFF we are not filtering out canceled orders, these are only canceled orders outside the given date range, then include them here
		@filterCanceled = 0
		AND
		(
			[QA_PS_Description] like '%CANCELED%'
		)
	)
END
GO
