	  INNER JOIN ERP_2.dbo.QA_CP_Action_Disposition_Type cpad on cpa.ActionID = cpad.ActionID
	  INNER JOIN ERP_2.dbo.QA_Disposition_Types d on cpad.DispositionID = d.DispositionID
	  --INNER JOIN ERP_2.dbo.QA_CP_Action_PO_Items cpapo on cpa.ActionID = cpapo.ActionID
	  --INNER JOIN ERP_2.dbo.QA_CP_Action_Prevention_Type cpap on cpa.ActionID = cpap.ActionID
	  --INNER JOIN ERP_2.dbo.QA_Prevention_Types p on cpap.PreventionID = p.PreventionID
	  --INNER JOIN ERP_2.dbo.QA_CP_Action_Reporting_Source cpars on cpa.ActionID = cpars.ActionID
	  --INNER JOIN ERP_2.dbo.QA_Reporting_Source rs on cpars.ReportingSourceID = rs.ReportingSourceID
	  --INNER JOIN ERP_2.dbo.QA_CP_Action_RootCauseSource_OrgDept cparcs on cpa.ActionID = cparcs.ActionID
	  --INNER JOIN ERP_2.dbo.QA_RootCause_Source rcs on cparcs.RootCauseID = rcs.RootCauseID
	  --INNER JOIN ERP_2.dbo.QA_Org_Dept od on od.DeptID = cparcs.DeptID
	  INNER JOIN ERP_2.dbo.QA_CP_Action_SO_Items cpaso on cpa.ActionID = cpaso.ActionID
	  INNER JOIN ERP_2.dbo.RMA_Detail rmad on cpaso.SOItem = rmad.so_item
	  INNER JOIN ERP_2.dbo.Receiving r on rmad.rma_no = r.RMA_No
	  WHERE r.Received > @startMonthDate
