ALTER   PROCEDURE [dbo].[p_Receiving_ins]
	@Received	SmallDateTime,
	@POitem		CHAR(12),
	@SOitem		CHAR(10),
	@Alloy		CHAR(12),
	@Heat		VARCHAR(50),
	@Cert		BIT,
	@Pieces		NUMERIC(10,0),
	@Description	TEXT,
	@Specs		TEXT,
	@Comments	TEXT,
	@Init		CHAR(10),
	@Date		SmallDateTime,
	@Pass		BIT,
	@GoodPapers	BIT,
	@ActualW	NUMERIC(9,1),
	@BillW		NUMERIC(9,1),
	@Vendor		CHAR(30),
	@RejectPC	INT,
	@RejectReason VARCHAR(255)
AS
BEGIN

SET NOCOUNT ON

--SET @POitem = dbo.ProperPO(@POitem)
--SET @SOitem = dbo.ProperPO(@SOitem)

DECLARE @CO_ID int
DECLARE @Cancelled BIT
SET @Cancelled = 0

INSERT INTO [dbo].[Receiving] WITH (ROWLOCK)  (
	Received
	, POitem
	, SOitem
	, Alloy
	, Heat
	, Cert
	, Pieces
	, Description
	, Specs
	, Comments
	, Init
	, Date
	, Pass
	, GoodPapers
	, ActualW
	, BillW
	, Vendor
	, RejectPC
	, RejectReason
	, Cancelled )
    Values (
	@Received,
	@POitem,
	@SOitem,
	@Alloy,
	@Heat,
	@Cert,
	@Pieces,
	@Description,
	@Specs,
	@Comments,
	@Init,
	@Date,
	@Pass,
	@GoodPapers,
	@ActualW,
	@BillW,
	@Vendor,
	@RejectPC,
