ALTER PROCEDURE [dbo].[p_rtr_Ins]
	@SOitem	CHAR(10)
    ,@WO INT
    ,@WO_Detail INT
	,@Quote_ID INT
AS

  Set NoCount On
  
  --Return 0 if All are Null
  IF @SOitem IS NULL AND @WO IS NULL AND @WO_Detail IS NULL AND @Quote_ID IS NULL
	RETURN 0

  --Fail if all are the same
--  IF @SOitem = @WO AND @WO = @WO_Detail
--	begin
--		PRINT 'in dbo.p_rtr_ins SOitem = WO = WO_Detail --All Equal'
--		RAISERROR('in dbo.p_rtr_ins SOitem = WO = WO_Detail, All are Equal', 16, 1) 
--	end

  IF @Quote_ID IS NULL
	SET @Quote_ID = 0

  --------------------
  IF @WO IS NULL
	SET @WO = 0

  IF @WO_Detail IS NULL
	SET @WO_Detail = 0

  --IF @SOitem = @WO AND @WO = @WO_Detail AND @SOitem = @WO_Detail
  IF @WO = @WO_Detail AND (@WO*@WO_Detail) > 0
	begin
	
	PRINT ' Email Error in Stored Procedure dbo.p_rtr_ins '

	DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
	DECLARE @Body varchar(8000)

	SET @Body = ' Stored Procedure dbo.p_rtr_ins '

	SET @Body = @Body + CHAR(13)+CHAR(10) + '@WO:'+ISNULL(@WO,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@WO_Detail:'+ISNULL(@WO_Detail,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + ''					
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Entered by '+RTRIM(suser_sname())+' on '+RTRIM(GETDATE())+'.' 
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Stored Procedure dbo.p_rtr_ins '
			
	EXEC dbo.p_eMail_Send
		 @FromEmail = cEmailFrom, 
		 @ToEmail = 'David.Kirchner@ERP_1s.com', 
		 @SubjectEmail = 'dbo.p_rtr_ins WO=WO_Detail.',
		 @BodyEmail = @Body,
		 @BodyType = 'TEXT'		

	SET @SOitem = ''
    SET @WO=0

	end

  ------------------
  

   INSERT INTO dbo.[rtr] WITH (ROWLOCK)  (
	SOitem
    ,WO
    ,WO_Detail
	,Quote_ID
	)
    Values (
	@SOitem
    ,@WO
    ,@WO_Detail
	,@Quote_ID
	)

  DECLARE @ID_rtr INT
  SET @ID_rtr = SCOPE_IDENTITY()


