/****** Object:  StoredProcedure [dbo].[p_rtr_Oper]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_rtr_Oper]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_rtr_Oper] AS' 
END
GO


ALTER PROCEDURE [dbo].[p_rtr_Oper]
	 @cOrderType CHAR(10)
	,@cOrderNumber CHAR(10)
	,@nOper_ID INT
	,@bStart BIT

AS
-- EXEC dbo.p_rtr_Oper 'WO',CAST(1183 AS CHAR),520,1	--Start CG Operation

SET NOCOUNT ON

DECLARE @nOrderNumber INT = 0
--Correct OrderNumber, SOitem uses char(10)

IF @cOrderType = 'WO'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'WO_Detail'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'Quote_ID'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)

----------------------------------------------------------
DECLARE @rtr_ID INT = 0
--Retrieve ID
DECLARE @cSOitem CHAR(10)=''
DECLARE @WO INT = 0
DECLARE @WO_Detail INT = 0
DECLARE @Quote_ID INT = 0

IF @cOrderType = 'WO'
	begin
	SET @WO = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0
	end
ELSE 
IF @cOrderType = 'WO_Detail'
	begin
	SET @WO_Detail = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0
	end
ELSE 
IF @cOrderType = 'SOitem'
	begin 
	SET @cSOitem = dbo.f_ProperSOitem(@cOrderNumber)
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('')
	end
ELSE 
IF @cOrderType = 'Quote_ID'
	begin
	SET @Quote_ID = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber
	end

----------------------------------------------------------
IF @rtr_ID = 0
	begin
	--Not found, need to insert rtr

	PRINT 'INSERT dbo.rtr '

	INSERT INTO dbo.[rtr] WITH (ROWLOCK)  (
		SOitem
		,WO
		,WO_Detail
		,Quote_ID
		,[Started]
		,[Finished]
	) Values (
		 @cSOitem
		,@WO
		,@WO_Detail
		,@Quote_ID
		,1
		,case when @bStart=0 then 1 else 0 end
		)

	--Retrieve ID
	IF @cOrderType = 'WO'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0;
	ELSE 
	IF @cOrderType = 'WO_Detail'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0;
	ELSE 
	IF @cOrderType = 'SOitem'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('');
	ELSE 
	IF @cOrderType = 'Quote_ID'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber ;
	


	IF @rtr_ID = 0
		begin
			PRINT 'INSERT dbo.rtr Failed!'

			--insert Email here
			DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
			DECLARE @Body varchar(4000)
			
			SET @Body = '<!DOCTYPE html> <html><head><title>HPA Notice</title></head><body>'

			SELECT TOP 1 @Body = @Body+ 'dbo.p_rtr_Oper @cOrderType CHAR(10), @cOrderNumber CHAR(10)	,@nOper_ID INT'+CHAR(10)+CHAR(13) 
				+' cOrderType:'+@cOrderType +CHAR(10)+CHAR(13) 
				+' cOrderNumber:'+@cOrderNumber +CHAR(10)+CHAR(13) 
				+' nOper_ID:'+CAST(@nOper_ID AS CHAR(10)) +CHAR(10)+CHAR(13) 

			
			SET @Body = @Body + SUSER_SNAME()+' on '+RTRIM(CAST(GETDATE()AS CHAR ))+CHAR(10)+CHAR(13)

			SET @Body = @Body +@@SERVERNAME+' dbo.p_rtr_Oper'+CHAR(10)+CHAR(13)

			SET @Body = @Body +'</body>'

			EXEC dbo.p_eMail_Send
				 @FromEmail = @cEmailFrom, 
				 @ToEmail = 'David.Kirchner@ERP_1s.com', 
				 @SubjectEmail = 'Insert dbo.rtr Failed! ',
				 @BodyEmail = @Body,
				 @BodyType = 'HTML'		

			RETURN
		end

	end
 ELSE
	begin
	--Found rtr
	PRINT 'UPDATE dbo.rtr --removing finished flag because still starting Details. '
	--reverse a finished when still starting!

	IF @bStart=1
		UPDATE dbo.rtr SET Finished = 0 
			WHERE ID = @rtr_ID
			AND ISNULL(Finished,0) = 1

	end

 --------------------------------------------------
 -- Done with ID
 -- get Operation Detail
DECLARE @cOperation VarChar(20) = ''
SELECT @cOperation=Operation FROM dbo.rtr_Operation WHERE Oper_ID = @nOper_ID;

-----------------------------------------------------
 -- Start on Detail

DECLARE @nDetail INT = 99	--Always adds atleast 1
DECLARE @bUpdate BIT = 0

--Get Max Detail for same Oper_ID
SELECT @nDetail = ISNULL(MAX(Detail),0)
	FROM dbo.rtr_Detail 
	WHERE rtr_ID = @rtr_ID 
	AND Oper_ID = @nOper_ID;

IF @nDetail > 99
	SET @bUpdate = 1
ELSE
	SELECT @nDetail = ISNULL(MAX(Detail),0) FROM dbo.rtr_Detail 
		WHERE rtr_ID = @rtr_ID AND Oper_ID = @nOper_ID;
	--Get Max or last Detail used
	--can return 0

IF @nDetail = 0
	SET @nDetail = 110

PRINT 'Max Detail='+CAST(@nDetail AS CHAR(10) )

-----------------------------------------------------

IF @bUpdate = 1
	begin

	--Found the Operation, so update that Detail
	PRINT 'UPDATE dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );

	IF @bStart=1
		UPDATE dbo.rtr_Detail 
			SET StartDate = GetDate()
			,[Started] = 1
			,Oper_Note = TRIM(Oper_Note) + ': ReStarted '
			WHERE rtr_Detail.rtr_ID = @rtr_ID 
			AND rtr_Detail.Oper_ID = @nOper_ID;
	ELSE
		UPDATE dbo.rtr_Detail 
			SET FinishDate = GetDate()
			,[Finished] = 1
			WHERE rtr_Detail.rtr_ID = @rtr_ID 
			AND rtr_Detail.Oper_ID = @nOper_ID;

	end
ELSE
	begin

	IF ISNULL(@nDetail,0) < 99
		SET @nDetail = 99;

	SET @nDetail = @nDetail + 1;
	PRINT 'INSERT dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );

	INSERT INTO dbo.rtr_Detail 
		([rtr_ID],[Detail]
		,[Started],[StartDate], [Finished]
		,[Oper_ID],[Oper_Note]
		)
			VALUES 
		(@rtr_ID ,@nDetail 
		,case when @bStart=1 then 1 else 0 end ,GetDate() ,case when @bStart=1 then 0 else 1 end
		,@nOper_ID
		,'Operation '+case when @bStart=1 then 'start' else 'end' end
		) ;

	end



--GRANT EXECUTE ON [dbo].[p_rtr_Oper] TO [WINDFALL\HPA] AS [dbo]

  



GO
/****** Object:  StoredProcedure [dbo].[p_rtr_Oper_Cancel]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_rtr_Oper_Cancel]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_rtr_Oper_Cancel] AS' 
END
GO


ALTER PROCEDURE [dbo].[p_rtr_Oper_Cancel]
	 @cOrderType CHAR(10)
	,@cOrderNumber CHAR(10)
	,@nOper_ID INT

AS
-- EXEC dbo.p_rtr_Oper_Cancel 'WO',CAST(1183 AS CHAR),520	--Stop and Cancel CG Operation
--like dbo.p_rtr_Oper
-- A Cancel is always like a STOP operation

SET NOCOUNT ON

DECLARE @nOrderNumber INT = 0
--Correct OrderNumber, SOitem uses char(10)

IF @cOrderType = 'WO'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'WO_Detail'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'Quote_ID'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)


----------------------------------------------------------
DECLARE @rtr_ID INT = 0
--Retrieve ID
DECLARE @cSOitem CHAR(10)=''
DECLARE @WO INT = 0
DECLARE @WO_Detail INT = 0
DECLARE @Quote_ID INT = 0

IF @cOrderType = 'WO'
	begin
	SET @WO = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0
	end
ELSE 
IF @cOrderType = 'WO_Detail'
	begin
	SET @WO_Detail = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0
	end
ELSE 
IF @cOrderType = 'SOitem'
	begin 
	SET @cSOitem = dbo.f_ProperSOitem(@cOrderNumber)
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('')
	end
ELSE 
IF @cOrderType = 'Quote_ID'
	begin
	SET @Quote_ID = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber
	end

----------------------------------------------------------
IF @rtr_ID = 0
	begin
	--Not found, need to insert rtr

	PRINT 'INSERT dbo.rtr '

	INSERT INTO dbo.[rtr] WITH (ROWLOCK)  (
		SOitem
		,WO
		,WO_Detail
		,Quote_ID
		,[Started]
		,[Finished]
	) Values (
		 @cSOitem
		,@WO
		,@WO_Detail
		,@Quote_ID
		,1
		,1		--Finished; if there is no other rtr, then this Cancel also finishes
		)

	--Retrieve ID
	IF @cOrderType = 'WO'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0;
	ELSE 
	IF @cOrderType = 'WO_Detail'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0;
	ELSE 
	IF @cOrderType = 'SOitem'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('');
	ELSE 
	IF @cOrderType = 'Quote_ID'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber ;



	IF @rtr_ID = 0
		begin
			PRINT 'INSERT dbo.rtr Failed!'

			--insert Email here
			DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
			DECLARE @Body varchar(4000)
			
			SET @Body = '<!DOCTYPE html> <html><head><title>HPA Notice</title></head><body>'

			SELECT TOP 1 @Body = @Body+ 'dbo.p_rtr_Oper_Cancel @cOrderType CHAR(10), @cOrderNumber CHAR(10)	,@nOper_ID INT'+CHAR(10)+CHAR(13) 
				+' cOrderType:'+@cOrderType +CHAR(10)+CHAR(13) 
				+' cOrderNumber:'+@cOrderNumber +CHAR(10)+CHAR(13) 
				+' nOper_ID:'+CAST(@nOper_ID AS CHAR(10)) +CHAR(10)+CHAR(13) 

			
			SET @Body = @Body + SUSER_SNAME()+' on '+RTRIM(CAST(GETDATE()AS CHAR))+CHAR(10)+CHAR(13)

			SET @Body = @Body +@@SERVERNAME+' dbo.p_rtr_Oper_Cancel'+CHAR(10)+CHAR(13)

			SET @Body = @Body +'</body>'

			EXEC dbo.p_eMail_Send
				 @FromEmail = @cEmailFrom, 
				 @ToEmail = 'David.Kirchner@ERP_1s.com', 
				 @SubjectEmail = 'Insert dbo.rtr Failed! ',
				 @BodyEmail = @Body,
				 @BodyType = 'HTML'		

			

			RETURN
		end

	end
  
 --------------------------------------------------
 -- Done with ID
 -- get Operation Detail
DECLARE @cOperation VarChar(20) = ''
SELECT @cOperation=Operation FROM dbo.rtr_Operation WHERE Oper_ID = @nOper_ID;

-----------------------------------------------------
 -- Start on Detail

DECLARE @nDetail INT = 99	--Always adds atleast 1
DECLARE @bUpdate BIT = 0

SELECT @nDetail = ISNULL(MAX(Detail),0)
	FROM dbo.rtr_Detail 
	WHERE rtr_ID = @rtr_ID 
	AND Oper_ID = @nOper_ID;

IF @nDetail > 99
	SET @bUpdate = 1
ELSE
	SELECT @nDetail = ISNULL(MAX(Detail),0) FROM dbo.rtr_Detail WHERE rtr_ID = @rtr_ID AND Oper_ID = @nOper_ID;
	--Get Max or last Detail used
	--can return 0

IF @nDetail = 0
	SET @nDetail = 110

PRINT 'Max Detail='+CAST(@nDetail AS CHAR(10) )

----------------------------------------------

IF @bUpdate = 1
	begin

	--Found the Operation, so update that Detail
	PRINT 'UPDATE dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );
--		UPDATE dbo.rtr_Detail 
--			SET StartDate = GetDate()
--			,[Started] = 1
--			,Oper_Note = TRIM(Oper_Note) + ': ReStarted '
--			WHERE rtr_Detail.rtr_ID = @rtr_ID 
--			AND rtr_Detail.Oper_ID = @nOper_ID;
--	ELSE
		UPDATE dbo.rtr_Detail 
			SET FinishDate = GetDate()
			,[Finished] = 1
			,Cncld = 1
			,CnclDate = GetDate()
			,Oper_Note = TRIM(Oper_Note) + ': Cancelled '
			WHERE rtr_Detail.rtr_ID = @rtr_ID 
				AND rtr_Detail.Oper_ID = @nOper_ID
				AND ISNULL(Cncld,0) = 0;

	end
ELSE
	begin

	IF ISNULL(@nDetail,0) < 99
		SET @nDetail = 99;

	SET @nDetail = @nDetail + 1;
	PRINT 'INSERT dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );

	INSERT INTO dbo.rtr_Detail 
		([rtr_ID],[Detail]
		,[Started],[StartDate], [Finished]
		,[Oper_ID],[Oper_Note]
		,Cncld, CnclDate
	) VALUES (
		 @rtr_ID ,@nDetail 
		,1, GetDate() ,1
		,@nOper_ID
		,'Operation Cancel'
		,1, GetDate()
		) ;

	end




--GRANT EXECUTE ON [dbo].[p_rtr_Oper_Cancel] TO [WINDFALL\HPA] AS [dbo]

  



GO
