ALTER PROCEDURE [dbo].[p_rtr_Sched]
	 @cOrderType CHAR(10)
	,@cOrderNumber CHAR(10)
	,@nOper_ID INT
	

AS
-- EXEC dbo.p_rtr_Detail_Sched 'WO',CAST(1183 AS CHAR),520	--Schedule CG Operation

SET NOCOUNT ON

DECLARE @nOrderNumber INT = 0
--Correct OrderNumber, SOitem uses char(10)

IF @cOrderType = 'WO'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'WO_Detail'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)
ELSE 
IF @cOrderType = 'Quote_ID'
	SET @nOrderNumber = CAST(@cOrderNumber AS INT)

----------------------------------------------------------
DECLARE @rtr_ID INT = 0
--Retrieve ID
DECLARE @cSOitem CHAR(10)=''
DECLARE @WO INT = 0
DECLARE @WO_Detail INT = 0
DECLARE @Quote_ID INT = 0

IF @cOrderType = 'WO'
	begin
	SET @WO = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0
	end
ELSE 
IF @cOrderType = 'WO_Detail'
	begin
	SET @WO_Detail = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0
	end
ELSE 
IF @cOrderType = 'SOitem'
	begin 
	SET @cSOitem = dbo.f_ProperSOitem(@cOrderNumber)
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('')
	end
ELSE 
IF @cOrderType = 'Quote_ID'
	begin
	SET @Quote_ID = @nOrderNumber
	SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber
	end

----------------------------------------------------------
IF @rtr_ID = 0
	begin
	--Not found, need to insert dbo.rtr

	PRINT 'INSERT dbo.rtr '

	INSERT INTO dbo.[rtr] WITH (ROWLOCK)  (
		SOitem
		,WO
		,WO_Detail
		,Quote_ID
		,[Started]
		,[Finished]
	) Values (
		 @cSOitem
		,@WO
		,@WO_Detail
		,@Quote_ID
		,0
		,0
		)

	--Retrieve ID
	IF @cOrderType = 'WO'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO = @nOrderNumber AND WO > 0;
	ELSE 
	IF @cOrderType = 'WO_Detail'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nOrderNumber AND WO_Detail > 0;
	ELSE 
	IF @cOrderType = 'SOitem'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cOrderNumber) AND NOT SOitem = dbo.f_ProperSOitem('');
	ELSE 
	IF @cOrderType = 'Quote_ID'
		SELECT @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @nOrderNumber ;


	IF @rtr_ID = 0
		begin
			PRINT 'INSERT dbo.rtr Failed!'

			--insert Email here
			DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
			DECLARE @Body varchar(4000)
			
			SET @Body = '<!DOCTYPE html> <html><head><title>HPA Notice</title></head><body>'

			SELECT TOP 1 @Body = @Body+ 'dbo.p_rtr_Sched @cOrderType CHAR(10), @cOrderNumber CHAR(10)	,@nOper_ID INT'+CHAR(10)+CHAR(13) 
				+' cOrderType:'+@cOrderType +CHAR(10)+CHAR(13) 
				+' cOrderNumber:'+@cOrderNumber +CHAR(10)+CHAR(13) 
				+' nOper_ID:'+CAST(@nOper_ID AS CHAR(10)) +CHAR(10)+CHAR(13) 

			
			SET @Body = @Body + SUSER_SNAME()+' on '+RTRIM(CAST(GETDATE()AS CHAR))+CHAR(10)+CHAR(13)

			SET @Body = @Body +@@SERVERNAME+' dbo.p_rtr_Sched'+CHAR(10)+CHAR(13)

			SET @Body = @Body +'</body>'

			EXEC dbo.p_eMail_Send
				 @FromEmail = @cEmailFrom, 
				 @ToEmail = 'David.Kirchner@ERP_1s.com', 
				 @SubjectEmail = 'Insert dbo.rtr Failed! ',
				 @BodyEmail = @Body,
				 @BodyType = 'HTML'		

			RETURN
		end

	end
 ELSE
	begin
	--Found rtr
	PRINT 'UPDATE dbo.rtr --removing finished flag because still starting Details. '
	--reverse a finished when still starting!

	--IF @bStart=1
		UPDATE dbo.rtr SET Finished = 0 
			WHERE ID = @rtr_ID
			AND ISNULL(Finished,0) = 1

	end

 --------------------------------------------------
 -- Done with ID
 -- get Operation Detail
DECLARE @cOperation VarChar(20) = ''
SELECT @cOperation=Operation FROM dbo.rtr_Operation WHERE Oper_ID = @nOper_ID;

-----------------------------------------------------
 -- Start on Detail

DECLARE @nDetail INT = 100
DECLARE @bUpdate BIT = 0

--Get Detail for same Oper_ID
SELECT @nDetail = ISNULL(MAX(Detail),0)
	FROM dbo.rtr_Detail 
	WHERE rtr_ID = @rtr_ID 
	AND Oper_ID = @nOper_ID;

IF @nDetail > 99
	begin

	SET @bUpdate = 1
	PRINT 'the Detail='+CAST(@nDetail AS CHAR(10) )

	end
ELSE
	begin
	--look for default Detail for Operation
	SELECT TOP 1 @nDetail = ISNULL(StdDetail,108) 
		FROM dbo.rtr_Operation WHERE Oper_ID = @nOper_ID;

	--Now check for next available Detail
	SET @nDetail = dbo.f_rtr_Next_Detail_Allowed( @rtr_ID, @nDetail )

	SET @bUpdate = 0	--must insert

	PRINT 'Next Detail='+CAST(@nDetail AS CHAR(10) )

	end

--Double check
IF @nDetail = 0
	SET @nDetail = 109



-----------------------------------------------------

IF @bUpdate = 1
	begin

	--Found the Operation, so update that Detail
	PRINT 'UPDATE dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation: '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );


	UPDATE dbo.rtr_Detail 
		SET StartDate = GetDate()
		,[Started] = 0
		,Oper_Note = ''
		WHERE rtr_Detail.rtr_ID = @rtr_ID 
			AND rtr_Detail.Detail = @nDetail
			AND rtr_Detail.Oper_ID = @nOper_ID;
	
	end
ELSE
	begin

	IF ISNULL(@nDetail,0) < 99
		SET @nDetail = 100;

	--SET @nDetail = @nDetail + 1;
	PRINT 'INSERT dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Operation: '+@cOperation+' '
		+CAST(@nOper_ID AS CHAR(10) )+ 'rtr_ID='+CAST(@rtr_ID AS CHAR(10) );

	INSERT INTO dbo.rtr_Detail 
		([rtr_ID],[Detail]
		,[Started],[StartDate], [Finished]
		,[Oper_ID],[Oper_Note]
		)
			VALUES 
		(@rtr_ID ,@nDetail 
		,0,GetDate() ,0
		,@nOper_ID
		,'Schedule '
		) ;

	end



--GRANT EXECUTE ON [dbo].[p_rtr_Sched] TO [WINDFALL\HPA] AS [dbo]

  



GO
