ALTER PROCEDURE [dbo].[p_rtr_Select_Material]
	 @cOrderType CHAR(10)
	,@cOrderNumber CHAR(10)
	,@TBL CHAR(1)
	,@ID_Detail_Process INT

AS
-- EXEC dbo.p_rtr_Select_Material 'WO',CAST(1183 AS CHAR),'S',159658

SET NOCOUNT ON

--DECLARE @nOrderNumber INT = 0
DECLARE @nWO		INT = 0
DECLARE @nWO_Detail	INT = 0
DECLARE @cSOitem	CHAR(10) = ''
DECLARE @Quote_ID INT = 0

IF @cOrderType = 'WO_Detail'
begin
	SET @nWO_Detail = CAST(@cOrderNumber AS INT)
	PRINT 'dbo.p_rtr_Select_Material @cOrderType=WO_Detail with @cOrderNumber='+@cOrderNumber
end
ELSE 
IF @cOrderType = 'WO'
begin
	SET @nWO = CAST(@cOrderNumber AS INT)
	PRINT 'dbo.p_rtr_Select_Material @cOrderType=WO with @cOrderNumber='+@cOrderNumber
end
ELSE 
IF @cOrderType = 'SOitem'
begin
	SET @cSOitem = CAST(@cOrderNumber AS CHAR(10) )
	PRINT 'dbo.p_rtr_Select_Material @cOrderType=SOitem with @cOrderNumber='+@cOrderNumber
end
ELSE 
IF @cOrderType = 'Quote_ID'
begin
	SET @Quote_ID = CAST(@cOrderNumber AS INT)
	PRINT 'dbo.p_rtr_Select_Material @cOrderType=Quote_No with @cOrderNumber='+@cOrderNumber
end
ELSE
	PRINT 'error EXEC dbo.p_rtr_Select_Material -Did not get @cOrderType'

------------------------------------
DECLARE @rtr_ID INT = 0

IF @cOrderType = 'WO_Detail'
begin
	SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WHERE WO_Detail = @nWO_Detail AND WO_Detail > 0
	PRINT 'WO_Detail record is rtr.ID ='+TRIM(CAST( @rtr_ID AS CHAR(10)))
end
ELSE 
IF @cOrderType = 'WO'
begin
	SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WHERE WO = @nWO AND WO > 0
	PRINT 'WO record is rtr.ID ='+TRIM(CAST( @rtr_ID AS CHAR(10)))
end
ELSE 
IF @cOrderType = 'SOitem'
begin
	SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WHERE SOitem = dbo.f_ProperSOitem(@cSOitem) AND NOT SOitem = dbo.f_ProperSOitem('')
	PRINT 'SOitem record is rtr.ID ='+TRIM(CAST( @rtr_ID AS CHAR(10)))
end
IF @cOrderType = 'Quote_ID'
begin
	SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WHERE Quote_ID = @Quote_ID
	PRINT 'Quote_ID record is rtr.ID ='+TRIM(CAST( @rtr_ID AS CHAR(10)))
end


PRINT 'cSOitem='+@cSOitem+', WO='+CAST(@nWO AS CHAR(10))+', WO_Detail='+CAST(@nWO_Detail AS CHAR(10))+', Quote_ID='+CAST(@Quote_ID AS CHAR(10))
PRINT 'RouterID='+CAST(@rtr_ID AS CHAR(20))+'  TBL '+@TBL

------------------------------------
IF @rtr_ID = 0
	begin
	--need to insert rtr
	PRINT 'need to insert rtr'
	PRINT 'Start: EXEC dbo.p_rtr_Select_Material '+@cOrderType+' INSERT dbo.rtr [Started]'

	INSERT INTO dbo.rtr WITH (ROWLOCK)  (
	SOitem
    ,WO
    ,WO_Detail
	,Quote_ID
	,[Started],[Finished]
	)
    Values (
	 @cSOitem
	,@nWO
    ,@nWO_Detail
	,@Quote_ID
	,1	,0
	);

	
	SET @rtr_ID = SCOPE_IDENTITY()
	--SCOPE_IDENTITY(): returns the last identity value generated in the current scope (i.e. stored procedure, trigger, function, etc).

	/*
	IF @cOrderType = 'WO'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE WO = @nWO AND WO > 0;
	ELSE 
	IF @cOrderType = 'WO_Detail'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE WO_Detail = @nWO_Detail AND WO_Detail > 0;
	ELSE 
	IF @cOrderType = 'SOitem'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE SOitem = dbo.f_ProperSOitem(@cSOitem) AND NOT SOitem = dbo.f_ProperSOitem('');
	*/

	IF @rtr_ID = 0
		begin
			PRINT 'Error: need to fix!';
			PRINT 'EXEC dbo.p_rtr_Select_Material '+@cOrderType+' INSERT dbo.rtr Failed!';
			RETURN
		end

	end
ELSE
	PRINT ' rtr.ID > 0, already have value, no INSERT into dbo.rtr '

--************************************************************************
--Figure out the next detail number to use in rtr_Detail for this rtr.ID
DECLARE @nDetail INT = 99
DECLARE @Update INT = 0

SELECT @nDetail = MAX(ISNULL(Detail,0)) 
	FROM dbo.rtr_Detail 
	WHERE rtr_ID = @rtr_ID 
		AND Oper_ID = 523 AND TBL = @TBL 
		AND ID_Detail_Process = @ID_Detail_Process;

PRINT '@nDetail='+CAST(ISNULL(@nDetail,0) AS CHAR(10))
SET @nDetail = ISNULL(@nDetail,0)

IF @nDetail > 99
begin
	SET @Update = 1
	PRINT 'Found Detail '+TRIM(CAST(@nDetail AS CHAR(10)))+' in rtr_Detail to UPDATE'
end
ELSE
begin
	SELECT @nDetail = MAX(ISNULL(Detail,0)) FROM dbo.rtr_Detail WHERE rtr_ID = @rtr_ID AND Oper_ID = 523;
	

	PRINT 'Did not find Oper_ID=523 Detail in dbo.rtr_Detail, updating Detail to '+TRIM(CAST(@nDetail AS CHAR(10)))
	PRINT ' to make the Select_Material INSERT for this @cOrderType '+TRIM(@cOrderType)+' and Order Number '+@cOrderNumber
end


PRINT 'Detail = '+TRIM(CAST(@nDetail AS CHAR(10)))+', for Oper_ID = 523, TBL = '+@TBL 
PRINT 'Update is '+CAST(@Update AS CHAR(1))+'; --1 for Yes UPDATE, 0 is No UPDATE then INSERT instead'
PRINT '********';

IF @Update = 1
	begin

	PRINT 'UPDATE dbo.rtr_Detail '+CAST(@nDetail AS CHAR(10) )+' Select_Material 523 Process for:'+@TBL+' ID_Detail_Process='+CAST(@ID_Detail_Process AS CHAR )+' rtr.ID='+CAST(@rtr_ID AS CHAR)

	UPDATE dbo.rtr_Detail 
		SET StartDate = GetDate(), [Started] = 1, TBL = @TBL
		WHERE rtr_Detail.rtr_ID = @rtr_ID 
		AND rtr_Detail.Oper_ID = 523	--SELECT
		AND TBL = @TBL
		AND rtr_Detail.Detail = @nDetail;
	
	end
ELSE
	begin
	PRINT 'looking for next Detail number to use with rtr_Detail Insert' 

	IF ISNULL(@nDetail,0) = 0
		begin
		 SELECT @nDetail=ISNULL(StdDetail,0) FROM dbo.[rtr_Operation] WHERE Oper_ID = 523;
		 -- next step will add 1
		 IF @nDetail > 0
			SET @nDetail = @nDetail -1;
		end

	IF ISNULL(@nDetail,0) < 99
		SET @nDetail = 99;


	DECLARE @nCountDetail INT = 0;
	
	--No dublicates!
	SET @nDetail = @nDetail + 1;

	PRINT 'Detail to insert '+TRIM(CAST(@nDetail AS CHAR(10)))

	SELECT @nCountDetail=Count(*) FROM dbo.rtr_Detail WHERE [rtr_ID]=@rtr_ID AND [Detail]=@nDetail;
	WHILE @nCountDetail > 0
		BEGIN
			SET @nDetail = @nDetail + 1;
			SELECT @nCountDetail=Count(*) FROM dbo.rtr_Detail WHERE [rtr_ID]=@rtr_ID AND [Detail]=@nDetail;
		END;

	PRINT 'INSERT dbo.rtr_Detail Detail= '+TRIM(CAST(@nDetail AS CHAR(10) ))+', Selected Material 523 Process for TBL:'+@TBL+', ID_Detail_Process='+CAST(@ID_Detail_Process AS CHAR )+' rtr.ID='+CAST(@rtr_ID AS CHAR)

	INSERT INTO dbo.rtr_Detail 
		([rtr_ID],[Detail],[Started],[StartDate], [Finished]
		,[Oper_ID]
		,[Oper_Note]
		,[POitem],[Cncld],[EstTime],[ActTime]
		,[TBL],[ID_Detail_Process])
			VALUES 
		(@rtr_ID ,@nDetail ,1 ,GetDate() ,0
		,523
		,'Select Material Process '+@TBL+' ID_Detail_Process='+CAST(@ID_Detail_Process AS CHAR )
		,''		,0		,0		,0		
		,@TBL ,@ID_Detail_Process ) ;

	end


PRINT ' End: EXEC dbo.p_rtr_Select_Material '+@cOrderType

