ALTER PROCEDURE [dbo].[p_rtr_TimeLine]
(
@cOrderType CHAR(2),
@cOrderNumber CHAR(20)
)
AS
BEGIN
--Returns data table FROM OT with OT.OrderItem, OTE.EmployeeID ,OTT.status, OTT.time ,rO.Oper_ID ,rO.Operation
-- in chonologic Order


--EXEC dbo.p_rtr_TimeLine 'SI','104476-01'

--SET NOCOUNT ON
DECLARE @err INT,
        @RC INT
	
SET @err = 0
SET @RC = 0


SELECT 
OT.OrderItem,
OTE.EmployeeID
,OTT.status, OTT.time
,rO.Oper_ID
,rO.Operation
  FROM [dbo].OT OT
INNER JOIN [dbo].OT_Job OTJ ON OT.jobID = OTJ.jobID
INNER JOIN [dbo].OT_Employee OTE ON OT.trackID = OTE.trackID
INNER JOIN [dbo].OT_Time OTT ON OT.trackID = OTT.trackID
INNER JOIN [dbo].OT_OrderType OTtype ON OT.orderType = OTtype.Id

INNER JOIN dbo.rtr_Operation rO ON OTJ.jobClass = rO.jobClass AND OTJ.jobType = rO.jobType

WHERE OTtype.OrderType = @cOrderType AND --'SI' 
	--ERP_2.dbo.f_ProperSOitem(OT.OrderItem) = ERP_2.dbo.f_ProperSOitem('104476-01')
	ERP_2.dbo.f_ProperSOitem(OT.OrderItem) = ERP_2.dbo.f_ProperSOitem(@cOrderNumber)
ORDER BY OTT.time


RETURN
END
GO
