ALTER PROCEDURE [dbo].[p_Sales_Stock_UPDATE_Sales]
 @SOitem VARCHAR(10) 

AS

--EXEC dbo.p_Sales_Stock_UPDATE_Sales '  78703-01'

Set NoCount On
 
declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @StkCost_Sales MONEY
DECLARE @StkCost_Select MONEY
DECLARE @POCost MONEY
DECLARE @ItemCost MONEY


SET @StkCost_Sales = ISNULL(dbo.f_CalcStkCost_Sales_Stock(@SOitem),0)

SELECT @StkCost_Select = ISNULL(dbo.f_CalcStkCost_SOitem(@SOitem),0)
--SELECT @StkCost = CASE WHEN ISNULL(SUM(SP.QTY * SD.S_P) ,0) > 0 THEN SUM(SP.QTY * SD.S_P ) ELSE SUM(SP.QTY * SD.CostValue) END FROM dbo.StockLst_Process SP

SELECT @POCost = ISNULL(dbo.f_CalcPOCost_SOitem(@SOitem),0)
--Get from StockLst_Detail, StockLst_Process when not Complete
	--SELECT @StkPaid = SUM(SP.QTY * SD.InvoiceValue ) 

SELECT @ItemCost = ( @StkCost_Select + @StkCost_Sales + @POCost )

UPDATE dbo.Sales
	SET ItemCost = @ItemCost
	,StkCost = ( @StkCost_Select + @StkCost_Sales )
	,POCost = @POCost
	WHERE SOitem = dbo.ProperSO(@SOitem)


GO
