/****** Object:  Stored Procedure dbo.p_Show_StockLst_sum    Script Date: 4/10/2006 4:47:56 PM ******/

ALTER  Procedure [dbo].[p_Show_StockLst_sum]
(
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(18,4),
@nSize3 DECIMAL(18,4)
)

AS

--EXEC dbo.p_Show_StockLst_sum 'C-276','40','1',.5,48,120
--EXEC dbo.p_Show_StockLst_sum '6B','40','1',0,0,0
-- Used in HPA-Quotes-STK - Does not work for Thck = 0!!

SET NOCOUNT ON

DECLARE @nSize NUMERIC(9,3)
SET @nSize = CAST(@nThickness AS NUMERIC(9,3) )

DECLARE @sh NUMERIC(9,4)
DECLARE @sl NUMERIC(9,4)
SET @sh = @nThickness * 1.25
SET @sl = @nThickness * .8


IF @cForm >= '60' 
begin
     IF @nSize2 > 0
	SELECT 
	M.[Size]
	,D.Dim2 AS 'Sz2'
	,COUNT( D.Weight) AS 'Items'
	,CAST( SUM(D.Weight) AS INT) AS 'Lbs'


	,( SELECT 
	 ISNULL( SUM(StockLst_Process.PWeight) ,0)
	FROM dbo.Stocklst_Master 
	INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
	LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
	 WHERE Stocklst_Master.Alloy = @cAlloy
	  AND Stocklst_Master.Form = @cForm 
	  AND Stocklst_Master.CC = @cCC
	  AND ( Stocklst_Master.[Size] = M.[Size]
--	  OR (ISNULL(Stocklst_Detail.size_h,99) <= @sh AND ISNULL(Stocklst_Detail.size_H,99) >= @sl )  OR
--	  (ISNULL(Stocklst_Detail.size_l,.001) <= @sh AND ISNULL(Stocklst_Detail.size_l,.001) >= @sl ) 
	) AND Stocklst_Detail.Dim2 = @nSize2
	 AND StockLst_Process.Process_ID = 'SELECTED'
	) AS 'Sold'
	

	,( SELECT CAST(
	 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
	FROM dbo.Stocklst_Master 
	INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
	LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
	 WHERE Stocklst_Master.Alloy = @cAlloy
	  AND Stocklst_Master.Form = @cForm 
	  AND Stocklst_Master.CC = @cCC
	  AND ( Stocklst_Master.[Size] = M.[Size]
--	  OR (ISNULL(Stocklst_Detail.size_h,99) <= @sh AND ISNULL(Stocklst_Detail.size_H,99) >= @sl )  OR
--	  (ISNULL(Stocklst_Detail.size_l,.001) <= @sh AND ISNULL(Stocklst_Detail.size_l,.001) >= @sl ) 
	) AND Stocklst_Detail.Dim2 = @nSize2
	 AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
	) AS 'Incoming'
	


	,( SELECT CAST(
     ISNULL( SUM(AQ.Weight) ,0) AS INT)
	FROM dbo.AllQuotes AQ
	 WHERE AQ.Alloy = @cAlloy
	  AND AQ.Form = @cForm
	  AND AQ.CC =  @cCC
      AND ( AQ.[thck] = M.[Size]
--	  OR (ISNULL(AQ.[thck],99) <= @sh AND ISNULL(AQ.[thck],99) >= @sl )  OR
--	  (ISNULL(AQ.[thck],.001) <= @sh AND ISNULL(AQ.[thck],.001) >= @sl ) 
      )
      AND AQ.InqDate > GETDATE()-30
	) AS 'Quoted'


	FROM dbo.Stocklst_Master M 
	INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
	LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
	
	  WHERE m.Alloy = @cAlloy
	  AND m.Form = @cForm 
	  AND m.CC = @cCC
	  AND
	  (M.[Size] = @nSize  
--	  OR (ISNULL(D.size_h,99) <= @sh AND ISNULL(D.size_H,99) >= @sl )  OR
--	  (ISNULL(D.size_l,.001) <= @sh AND ISNULL(D.size_l,.001) >= @sl )
	   ) AND D.Dim2 = @nSize2
	GROUP BY M.[Size], D.Dim2
	ORDER BY M.[Size], D.Dim2
end
ELSE
begin
	--@cForm < '60'
	--Form is below 60
	SELECT 
	M.[Size]
	, '-' AS 'Sz2'
	,COUNT( D.Weight) AS 'Items'
	,CAST( SUM(D.Weight) AS INT) AS 'Lbs'
	

	,( SELECT CAST(
	 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
	FROM dbo.Stocklst_Master 
	INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
	LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
	 WHERE Stocklst_Master.Alloy = @cAlloy
	  AND Stocklst_Master.Form = @cForm 
	  AND Stocklst_Master.CC = @cCC
	  AND ( Stocklst_Master.[Size] = M.[Size]
--	  OR (ISNULL(Stocklst_Detail.size_h,99) <= @sh AND ISNULL(Stocklst_Detail.size_H,99) >= @sl )  OR
--	  (ISNULL(Stocklst_Detail.size_l,.001) <= @sh AND ISNULL(Stocklst_Detail.size_l,.001) >= @sl ) 
	) AND StockLst_Process.Process_ID = 'SELECTED'
	) AS 'Sold'
	

	,( SELECT CAST(
	 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
	FROM dbo.Stocklst_Master 
	INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
	LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
	 WHERE Stocklst_Master.Alloy = @cAlloy
	  AND Stocklst_Master.Form = @cForm 
	  AND Stocklst_Master.CC = @cCC
	  AND ( Stocklst_Master.[Size] = M.[Size]
--	  OR (ISNULL(Stocklst_Detail.size_h,99) <= @sh AND ISNULL(Stocklst_Detail.size_H,99) >= @sl )  OR
--	  (ISNULL(Stocklst_Detail.size_l,.001) <= @sh AND ISNULL(Stocklst_Detail.size_l,.001) >= @sl ) 
	) AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
	) AS 'Incoming'
	


	,( SELECT CAST(
     ISNULL( SUM(AQ.Weight) ,0) AS INT)
	FROM dbo.AllQuotes AQ
	 WHERE AQ.Alloy =  @cAlloy
	  AND AQ.Form = @cForm 
	  AND AQ.CC =  @cCC
      AND ( AQ.[thck] = M.[Size]
--	  OR (ISNULL(AQ.[thck],99) <= @sh AND ISNULL(AQ.[thck],99) >= @sl )  OR
--	  (ISNULL(AQ.[thck],.001) <= @sh AND ISNULL(AQ.[thck],.001) >= @sl ) 
      )
      AND AQ.InqDate > GETDATE()-30
	) AS 'Quoted'


	FROM dbo.Stocklst_Master M 
	INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
	LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
	
	  WHERE m.Alloy = @cAlloy
	  AND m.Form = @cForm 
	  AND m.CC = @cCC
	  AND
	  (M.[Size] = @nSize OR 
	 	  ( dbo.f_Return_Lower_Num (ISNULL(D.size_h,99),D.Dim1) <= @sh AND dbo.f_Return_Higher_Num (ISNULL(D.size_H,99),D.Dim1) >= @sl )  OR
		  (dbo.f_Return_Lower_Num (ISNULL(D.size_l,.001),D.Dim1) <= @sh AND dbo.f_Return_Higher_Num (ISNULL(D.size_l,.001),D.Dim2) >= @sl )
	   )
	GROUP BY M.[Size]
	ORDER BY M.[Size]
end






GO
