	FROM dbo.Stocklst_Master M WITH(NOLOCK) 
	INNER JOIN dbo.Stocklst_Detail D WITH(NOLOCK) ON M.[id]=D.[id]
	LEFT OUTER JOIN dbo.StockLst_Process P WITH(NOLOCK) ON D.ID_Detail = P.ID_Detail
	
	  WHERE m.Alloy = @cAlloy
	  AND m.Form = @cForm 
	  AND m.CC = @cCC
	  AND m.CL = @cCL
	  AND
	  (M.[Size] = @nSize OR 
	 	  ( dbo.f_Return_Lower_Num (ISNULL(D.size_h,99),D.Dim1) <= @sh AND dbo.f_Return_Higher_Num (ISNULL(D.size_H,99),D.Dim1) >= @sl )  OR
		  (dbo.f_Return_Lower_Num (ISNULL(D.size_l,.001),D.Dim1) <= @sh AND dbo.f_Return_Higher_Num (ISNULL(D.size_l,.001),D.Dim2) >= @sl )
	   )
	GROUP BY M.[Size]
	ORDER BY M.[Size]
end






GO
