/****** Object:  StoredProcedure [dbo].[p_SOitem_Items_Fix]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_SOitem_Items_Fix]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_SOitem_Items_Fix] AS' 
END
GO
-- =============================================
-- Author:		David Kirchner
-- Create date: 10/10/2025
-- Description:	When a Quote ID has used the same SO, item count is up but there is a dublicate
-- =============================================
ALTER PROCEDURE [dbo].[p_SOitem_Items_Fix]
	-- Add the parameters for the stored procedure here
	@SalesNum INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	--EXEC dbo.p_SOitem_Items_Fix 142493

	--begin transaction fixSOitem

	--DECLARE @SalesNum INT = 142493;
	DECLARE @cSO CHAR(10) = CAST(@SalesNum AS CHAR(10))
	DECLARE @SOitem1 CHAR(10) = dbo.f_ProperSOitem(@cSO+'-01')
	PRINT '@SOitem1 '+@SOitem1 
	DECLARE @SOitem2 CHAR(10) = dbo.f_ProperSOitem(@cSO+'-02')
	DECLARE @SOitem3 CHAR(10) = dbo.f_ProperSOitem(@cSO+'-03')
	DECLARE @SOitem4 CHAR(10) = dbo.f_ProperSOitem(@cSO+'-04')

	/*SELECT * FROM dbo.AllQuotes WHERE SalesNum = @SalesNum
	SELECT * FROM dbo.Sales WHERE SalesNum = @SalesNum
	SELECT * FROM dbo.Sales_No WHERE SalesNum = @SalesNum
	SELECT * FROM dbo.Sales_Detail WHERE SalesNum = @SalesNum
	*/
	
	--Calc for bad Item Total
	DECLARE @nCount INT = 0
	SELECT @nCount = COUNT(*) FROM dbo.Sales WHERE SalesNum = @SalesNum
	DECLARE @nSItemTot INT = 0
	SELECT @nSItemTot = Itemtot FROM dbo.Sales WHERE SalesNum = @SalesNum

	DECLARE @nCountItot INT = 0
	SELECT @nCountItot = Itemtot FROM dbo.Sales_No WHERE SalesNum = @SalesNum

	DECLARE @nCountQuote INT = 0
	SELECT @nCountQuote = COUNT(*) FROM dbo.AllQuotes WHERE SalesNum = @SalesNum

	DECLARE @nCntInqID INT = 0
	SELECT @nCntInqID = COUNT(DISTINCT ID_AllQuotes) FROM dbo.Sales WHERE SalesNum = @SalesNum


	PRINT ' Count Item ' + STR(@nCount,2) +     ' in dbo.Sales Item Tot  ' + STR(@nSItemTot)+ ' in dbo.Sales'
	PRINT ' Count Tot  ' + STR(@nCountItot,2) + ' in dbo.Sales_No'
	PRINT ' Count Quote' + STR(@nCountQuote,2)+ ' in dbo.AllQuotes Dist ID' + STR(@nCntInqID)+ ' in dbo.AllQuotes'
	PRINT ''

	--find Miss SOitem
	DECLARE @MissSOitem CHAR(10) 
	DECLARE @MissAQID INT
	SELECT TOP 1 @MissSOitem = S.SOitem
	,@MissAQID = AQ.ID
	FROM dbo.Sales S WITH(NOLOCK) 
	left outer join dbo.AllQuotes AQ WITH(NOLOCK) ON S.SOitem = AQ.SOitem
	WHERE S.SalesNum = @SalesNum
	AND AQ.SOitem IS NULL
	PRINT '@MissSOitem '+@MissSOitem

	DECLARE @MissItem TinyInt = CAST(RIGHT(TRIM(@MissSOitem),1)AS TinyInt)
	PRINT '@MissItem '+CAST(@MissItem AS CHAR)
	PRINT '@MissAQID '+CAST(@MissAQID AS CHAR)

/*@SOitem1  142493-01
@MissSOitem  142493-01
@MissItem 1                             
 Count Item  3 in dbo.Sales Item Tot         3 in dbo.Sales
 Count Tot   3 in dbo.Sales_No
 Count Quote 2 in dbo.AllQuotes Dist ID         2 in dbo.AllQuotes */

	IF @nCount = 3 AND @nCountItot = 3 AND @nCountQuote = 2 AND @MissItem = 1
		begin
		print ' @nCount = 3 AND @nCountItot = 3 AND @nCountQuote = 2 AND @MissItem = 1';
		-- DECLARE @SalesNum INT = 138718
		--UPDATE dbo.AllQuotes SET SOitem=@MissSOitem, Item = @MissItem WHERE ID = @MissAQID

		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' );
		
		UPDATE dbo.Sales_PS SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' );
		UPDATE dbo.Sales_PS SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' );


		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=2 
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' );
		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ), Item = 2, ItemTot=2 
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' );
			
		UPDATE dbo.Sales_No SET ItemTot=2 WHERE SalesNum = @SalesNum;

		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) 
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' );
		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ) 
			WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' );
		
		UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) 
			WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' );
			UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ) 
			WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' );

		end

	IF @nCount = 3 AND @nCountItot = 3 AND @nCountQuote = 1
		begin
		print ' @nCount = 3 AND @nCountItot = 3 AND @nCountQuote = 1';
		-- DECLARE @SalesNum INT = 138718
		UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1 WHERE SalesNum = @SalesNum
		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )
		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=1 
		WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' ) 
		UPDATE dbo.Sales_No SET ItemTot=1 WHERE SalesNum = @SalesNum
		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) 
		WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
		UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) 
		WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
		end

	IF @nCount = 2 AND @nCountItot = 2 AND @nCountQuote = 1
		begin
		print ' @nCount = 2 AND @nCountItot = 2 AND @nCountQuote = 1';
		-- DECLARE @SalesNum INT = 138718
		UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1 WHERE SalesNum = @SalesNum
		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )
		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=1 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		UPDATE dbo.Sales_No SET ItemTot=1 WHERE SalesNum = @SalesNum
		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		end

	IF @nCount = 2 AND @nCountItot > 2
		begin
		--Too risky if Count is not 2
		PRINT 'Items = 2 and Item tot > 2'
		UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )
		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=1 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		UPDATE dbo.Sales_No SET ItemTot=1 WHERE SalesNum = @SalesNum
		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		end

	IF @nCount = 3 AND @nCountQuote = 2
		begin
		-- DECLARE @SalesNum INT = 138929
		DECLARE @nID_AllQuotes INT = 0


		IF @nCntInqID=2
			begin
			Print 'if item 2 and item 3 use the same quote record, delete 2 and update 3 as 2'
			UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ), Item = 2 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
			DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
			UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ), Item = 2, ItemTot=2 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
			UPDATE dbo.Sales_No SET ItemTot=2 WHERE SalesNum = @SalesNum
			UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
			UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-03' )
			SET @nCntInqID=0
			end

		ELSE
			begin
			SELECT @nID_AllQuotes = ID_AllQuotes FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
			SELECT @nCntInqID = COUNT(ID_AllQuotes) FROM dbo.Sales WHERE ID_AllQuotes=@nID_AllQuotes

			IF @nCntInqID=2
				begin
				Print 'if item 1 and item 2 use the same quote record, delete 1 and update 2 as 1'
				UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
				DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )
				UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=2 WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
				UPDATE dbo.Sales_No SET ItemTot=2 WHERE SalesNum = @SalesNum
				UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
				UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
				SET @nCntInqID=0
				end

			end
		end

	IF @nCount = 1 AND @nCountItot = 1 AND @nCountQuote = 1 AND @nCntInqID = 1
		begin
		print ' @nCount = 1 AND @nCountItot = 1 AND @nCountQuote = 1 AND @nCntInqID = 1';
		-- DECLARE @SalesNum INT = 138718
		PRINT 'UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +-01 ), Item = 1 WHERE SalesNum = @SalesNum'
		UPDATE dbo.AllQuotes SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1 WHERE SalesNum = @SalesNum

		PRINT 'DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem(STR(@SalesNum,7)+ -01)'
		DELETE FROM dbo.Sales WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' )

		PRINT 'UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7)+ -01 ), Item = 1, ItemTot=1 WHERE SalesNum = @SalesNum'
		UPDATE dbo.Sales SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ), Item = 1, ItemTot=1 WHERE SalesNum = @SalesNum

		PRINT 'UPDATE dbo.Sales_No SET ItemTot=1 WHERE SalesNum = @SalesNum'
		UPDATE dbo.Sales_No SET ItemTot=1 WHERE SalesNum = @SalesNum

		PRINT 'UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +-01 ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +-02 )'
		UPDATE dbo.Sales_Detail SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )

		PRINT 'UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +-01 ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +-02 )'
		UPDATE dbo.StockLst_Process SET SOitem=dbo.f_ProperSOitem( STR(@SalesNum,7) +'-01' ) WHERE SOitem = dbo.f_ProperSOitem( STR(@SalesNum,7) +'-02' )
		end

	--DECLARE @SalesNum INT =
	PRINT 'AFTER Update data'
	SELECT * FROM dbo.AllQuotes WHERE SalesNum = @SalesNum
	SELECT * FROM dbo.Sales WHERE SalesNum = @SalesNum
	SELECT * FROM dbo.Sales_No WHERE SalesNum = @SalesNum

	--Commit ;

END
--DECLARE @SalesNum INT = 133201, @SOitem1 CHAR(10) = ' 133201-01', @SOitem2 CHAR(10) = ' 133201-02'
