ALTER PROCEDURE [dbo].[p_SoundexCompany]
(
@Company char(30)
)

AS
BEGIN

--SELECT dbo.f_SoundexCompany ('AMERICAN STAINLESS CORP. ')

DECLARE @cReturn CHAR(12)

declare @err int,
        @RC int

set @err = 0
set @rc = 0

SET @cReturn = ''
DECLARE @nFirstSpace INT
DECLARE @nSecondSpace INT
--DECLARE @nThirdSpace INT

SET @nFirstSpace  = CHARINDEX(' ',@Company)
SET @nSecondSpace = CHARINDEX(' ',@Company,@nFirstSpace+1)
--SET @nThirdSpace  = CHARINDEX(' ',@Company,@nSecondSpace+1)

PRINT @nFirstSpace 
PRINT @nSecondSpace 
--PRINT @nThirdSpace

DECLARE @cFirstName VARCHAR(255)
SET @cFirstName = LEFT(@Company, @nFirstSpace)
PRINT @cFirstName

DECLARE @cSecondName VARCHAR(255)
SET @cSecondName = SUBSTRING (@Company, @nFirstSpace+1, @nSecondSpace-@nFirstSpace )
PRINT @cSecondName

--DECLARE @cThirdName VARCHAR(255)
--SET @cThirdName = SUBSTRING (@Company, @nSecondSpace+1, @nThirdSpace-@nSecondSpace )
--PRINT @cThirdName

SET @cReturn = SOUNDEX(@cFirstName)+SOUNDEX(@cSecondName)
PRINT 'Return Soundex;'+@cReturn


END

