ALTER   PROCEDURE [dbo].[p_Start_Session_ID]
(
@U_ID INT,
@CS_ID INT OUTPUT,
@PrevSessions INT OUTPUT
)
AS

SET NOCOUNT ON
DECLARE @err INT,
        @RC INT
	
SET @err = 0
SET @RC = 0


SELECT @PrevSessions = COUNT(CS_ID) FROM ID_Basket WHERE U_ID = @U_ID

INSERT CurrentSession (
   U_ID )
  VALUES (
   @U_ID)


IF @@ERROR <> 0
  GOTO ErrorRoutine

SELECT @CS_ID = @@Identity

RETURN

ErrorRoutine:
   SET @CS_ID = 0

RETURN






GO
