ALTER PROCEDURE [dbo].[p_StockLst_Make_Totals]

AS

--EXEC dbo.[p_StockLst_Make_Totals]
-- Records EOM Stock totals

DECLARE @dEoM SmallDateTime
SET @dEoM = GETDATE()

IF MONTH(GETDATE())=1
	DELETE FROM dbo.NR_StockLst_Totals WHERE [Mnth] = 1 AND [Year] = YEAR(@dEoM)
	
INSERT INTO dbo.NR_StockLst_Totals
	(EoM,Alloy,Form,CC,CL
	,Size,MWeight,TotalCost
	,mS_QTY,mS_Total
	,Mnth,Year)
SELECT @dEoM AS EoM,
Alloy,Form
,CASE CC WHEN 'R' THEN '1' ELSE CC END
,CL
,dbo.f_SizeStandard(Size)
,SUM(SD.Weight) AS MWeight
,SUM(SD.Weight*SD.CostValue) AS TotalCost

,ISNULL( CAST(SUM(SD.S_QTY) AS INT),0) AS nS_QTY
,ISNULL( CAST(SUM(SD.S_QTY*SD.S_P) AS INT),0) AS mS_Total

,MONTH(@dEoM)
,YEAR(@dEoM)
FROM dbo.StockLst_Master SM
INNER JOIN dbo.StockLst_Detail SD ON SD.id = SM.ID
WHERE (POStatus != 'D' AND POStatus != 'P')  --Due in, Partial receive, Waiting for bill, Accounted
GROUP BY Alloy,Form,CASE cc WHEN 'R' THEN '1' ELSE cc END,CL,[Size]
ORDER BY Alloy,Form,CASE cc WHEN 'R' THEN '1' ELSE cc END,CL,[Size] 

--SELECT * from dbo.StockLst_Master WHERE POStatus = 'D'
--SELECT * from dbo.StockLst_Value
--SELECT * from dbo.StockLst_Detail
IF @@ROWCOUNT = 0
	PRINT 'Warning: Nothing added!';

PRINT @dEoM

IF MONTH(GETDATE())=12
BEGIN
	--Do again as January so year does not start off empty
	
	SET @dEoM = @dEoM + 10
	
	INSERT INTO dbo.NR_StockLst_Totals
	(EoM,Alloy,Form,CC,CL,
	Size,MWeight,TotalCost
	,mS_QTY,mS_Total
	,Mnth,Year)
	SELECT @dEoM AS EoM,
	Alloy,Form,CASE CC WHEN 'R' THEN '1' ELSE CC END
	,CL
	,dbo.f_SizeStandard(Size)
	,SUM(SD.Weight) AS MWeight
	,SUM(SD.Weight*SD.CostValue) AS TotalCost
	
	,CAST(SUM(SD.S_QTY) AS INT) AS nS_QTY
	,CAST(SUM(SD.S_QTY*SD.S_P) AS INT) AS mS_Total

	,MONTH(@dEoM)
	,YEAR(@dEoM)
	FROM dbo.StockLst_Master SM
	INNER JOIN dbo.StockLst_Detail SD ON SD.id = SM.ID
	WHERE (POStatus != 'D' AND POStatus != 'P')  --Due in, Partial receive, Waiting for bill, Accounted
	GROUP BY Alloy,Form,CASE cc WHEN 'R' THEN '1' ELSE cc END,CL,[Size]
	ORDER BY Alloy,Form,CASE cc WHEN 'R' THEN '1' ELSE cc END,CL,[Size] 
END

RETURN
GO
