ALTER PROCEDURE [dbo].[p_StockLst_Mins_Make_Usage]

AS
--fills the Yearly and Quarterly Usage buckets
--EXEC dbo.p_StockLst_Mins_Make_Usage
-- SELECT * FROM ERP_2.dbo.StockLst_Mins

DECLARE @DateLastYear AS Date
SET @DateLastYear = GETDATE()-365

DECLARE @FullYear AS SmallInt
SET @FullYear = YEAR(@DateLastYear)

DECLARE @PrevYear AS SmallInt
SET @PrevYear = @FullYear-1

DECLARE @FullQuarter AS SmallInt
SET @FullQuarter = dbo.f_YearQuarter( GETDATE()-90)

DECLARE @PrevQuarter AS SmallInt
SET @PrevQuarter = dbo.f_YearQuarter(@DateLastYear)
	
--/*
PRINT @DateLastYear
PRINT @FullYear
PRINT @PrevYear
PRINT @FullQuarter
PRINT @PrevQuarter
--*/
--SELECT *  FROM [dbo].[StockLst_Mins]
-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

--IF EXISTS(SELECT * FROM #YearlyUsageFullYear)
--	DROP TABLE #YearlyUsageFullYear

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size
	INTO #YearlyUsageFullYear  
	FROM dbo.NR_Sales_Summary SS
		WHERE Year(SS.Shipped) = @FullYear
		AND dbo.f_GetForm_StockBySZ2(SS.Form) = 0
	GROUP BY Alloy,Form,CC,CL,Size

UPDATE dbo.StockLst_Mins SET YUsage = 
ISNULL(( SELECT MatlWt ) ,0)
FROM #YearlyUsageFullYear SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 

DROP TABLE #YearlyUsageFullYear

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size
	INTO #PrevYearUsage  
	FROM dbo.NR_Sales_Summary SS
		WHERE Year(SS.Shipped) = @PrevYear
		AND dbo.f_GetForm_StockBySZ2(SS.Form) = 0
	GROUP BY Alloy,Form,CC,CL,Size

UPDATE dbo.StockLst_Mins SET PrevYUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #PrevYearUsage SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 

DROP TABLE #PrevYearUsage

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size
	INTO #QuarterlyUsage  
	FROM dbo.NR_Sales_Summary SS
		WHERE dbo.f_YearQuarter(SS.Shipped) = @FullQuarter 
		AND dbo.f_GetForm_StockBySZ2(SS.Form) = 0
	GROUP BY Alloy,Form,CC,CL,Size

UPDATE dbo.StockLst_Mins SET QUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #QuarterlyUsage SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 


DROP TABLE #QuarterlyUsage

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size
	INTO #PrevQuarterlyUsage  
	FROM dbo.NR_Sales_Summary SS
		WHERE dbo.f_YearQuarter(SS.Shipped) = @PrevQuarter 
		AND dbo.f_GetForm_StockBySZ2(SS.Form) = 0
	GROUP BY Alloy,Form,CC,CL,Size

	
UPDATE dbo.StockLst_Mins SET PrevQUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #PrevQuarterlyUsage SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 


DROP TABLE #PrevQuarterlyUsage

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size,Sz2
	INTO #YearlyUsage2 
	FROM dbo.NR_Sales_Summary SS
		WHERE Year(SS.Shipped) = @FullYear 
	AND dbo.f_GetForm_StockBySZ2(SS.Form) = 1
	GROUP BY Alloy,Form,CC,CL,Size,Sz2


UPDATE dbo.StockLst_Mins SET YUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #YearlyUsage2 SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CC = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 
	AND SS.Sz2 = StockLst_Mins.Sz2

DROP TABLE #YearlyUsage2

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size,Sz2
	INTO #PrevYearUsage2 
	FROM dbo.NR_Sales_Summary SS
		WHERE Year(SS.Shipped) = @PrevYear 
	AND dbo.f_GetForm_StockBySZ2(SS.Form) = 1
	GROUP BY Alloy,Form,CC,CL,Size,Sz2

	
UPDATE dbo.StockLst_Mins SET PrevYUsage =
 ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #PrevYearUsage2 SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 
	AND SS.Sz2 = StockLst_Mins.Sz2
	
DROP TABLE #PrevYearUsage2

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size,Sz2
	INTO #QuarterlyUsage2 
	FROM dbo.NR_Sales_Summary SS
		WHERE dbo.f_YearQuarter(SS.Shipped) = @FullQuarter 
	AND dbo.f_GetForm_StockBySZ2(SS.Form) = 1
	GROUP BY Alloy,Form,CC,CL,Size,Sz2


UPDATE dbo.StockLst_Mins SET QUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #QuarterlyUsage2 SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 
	AND SS.Sz2 = StockLst_Mins.Sz2
	
DROP TABLE #QuarterlyUsage2

-----------------------------------------------------
--Create Temp Table with Sum(MatWt)

SELECT SUM(ISNULL(MatlWt,0)) AS MatlWt,Alloy,Form,CC,CL,Size,Sz2
	INTO #PrevQuarterlyUsage2 
	FROM dbo.NR_Sales_Summary SS
		WHERE dbo.f_YearQuarter(SS.Shipped) = @PrevQuarter  
	AND dbo.f_GetForm_StockBySZ2(SS.Form) = 1
	GROUP BY Alloy,Form,CC,CL,Size,Sz2

	
UPDATE dbo.StockLst_Mins SET PrevQUsage = 
ISNULL(( SELECT MatlWt ) ,0)
--, SafeLevelDate = GetDate()
FROM #PrevQuarterlyUsage2 SS
	WHERE SS.Alloy = StockLst_Mins.Alloy
	AND SS.Form = StockLst_Mins.Form
	AND SS.CC = StockLst_Mins.CC
	AND SS.CL = StockLst_Mins.CL
	AND SS.Size = StockLst_Mins.Thck 
	AND SS.Sz2 = StockLst_Mins.Sz2

DROP TABLE #PrevQuarterlyUsage2
-----------------------

UPDATE dbo.StockLst_Mins SET LastEdit = GETDATE()
	
RETURN
GO
