ALTER PROCEDURE [dbo].[p_Maintenance_Monthly]

AS

--EXEC dbo.p_Maintenance_Monthly
--ran from Maintenace Plans: ERP_1 Backup saturday
--'SQL Server Agent \ Jobs \ _ERP_1 End of Month Stock totals '
---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

PRINT 'p_Maintenance_Monthly';

SELECT @Body = ('EXEC dbo.p_Maintenance_Monthly '
	+CHAR(10)+CHAR(13)+'started on '+RTRIM(GETDATE())+'. '
	 +@@SERVERNAME+'. Agent Job _ERP_1 INSERT INTO dbo.NR_StockLst_Totals ' );
		

EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'David.Kirchner@ERP_1s.com', 
	@SubjectEmail = 'p_Maintenance_Monthly.',
	@BodyEmail = @Body,
	@BodyType = 'TEXT';


------------------------------------------------------------------------


--EXEC dbo.p_Maintenance_Monthly;

EXEC dbo.[p_StockLst_Make_Totals];

EXEC dbo.[p_Maintenance_Sales_Summary];

EXEC dbo.p_StockLst_Mins_Make_Usage; --DEPRICATED

RETURN

