	@ID_Detail	int,
	@SalesPerson	varchar(20),
	@StartDate	datetime,
	@DueDate	datetime,
	@AllowSub	char(1),
	@pWeight	numeric(18,8),
	@pPc		INT,
	@SOitem		char(10),
	@PO_item	char(12),
	@Process_ID	char(10),
	@Processor	varchar(20),
	@Comment	varchar(100)
--	,@ID_Detail_Process	INT OUTPUT
AS

  Set NoCount On
--Process_ID SELECTED,INCOMING,PARTRECV,RECEIVED,SHIPPED,CORRECTED,SUBED
--'CANCELLED,CORRECTION,INCOMING,RECEIVED,Receiving,PartRecv,SELECTED,PartSelect,Sell Stock,Shipped,SUBED'

  INSERT INTO dbo.[StockLst_Process] WITH (ROWLOCK)  (
	ID_Detail,
	salesperson,
	startdate,
	duedate,
	AllowSub,
	pWeight,
	pPc,
	soitem,
	po_item,
	process_id,
	processor,
	comment)
    Values (
	@ID_Detail,
	@salesperson,
	@startdate,
	@duedate,
	@AllowSub,
	@pWeight,
	@pPc,
	@soitem,
	@po_item,
	@process_id,
	@processor,
	@comment)

  DECLARE @ID_Detail_Process INT
  SET @ID_Detail_Process = SCOPE_IDENTITY()
  --------------------

  IF @process_id = 'PartSelect'
	begin
	
	PRINT '  Stored Procedure dbo.p_StockLst_Process_ins '

	DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
	DECLARE @Body varchar(8000)

	SET @Body = ' Stored Procedure dbo.p_StockLst_Process_ins '

--			+' PO item:'+RTRIM(inserted.POitem)+CHAR(13)
--			+'"'+ dbo.f_Reportlink_CHAR('POitem',inserted.POitem)+'"'+CHAR(13)
					
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@ID_Detail:'+CAST(ISNULL(@ID_Detail,0) AS CHAR(10) )
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@salesperson:'+ISNULL(@salesperson,'')
--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@startdate:'
--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@duedate:'
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@AllowSub:'+ISNULL(@AllowSub,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@pWeight:'+RTRIM(STR(ISNULL(@pWeight,0)))
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@pPc:'+RTRIM(STR(ISNULL(@pPc,0)))
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@soitem:'+ISNULL(@soitem,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@po_item:'+ISNULL(@po_item,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@process_id:'+ISNULL(@process_id,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@processor:'+ISNULL(@processor,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '@comment:'+ISNULL(@comment,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + ''					
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Entered by '+RTRIM(suser_sname())+' on '+RTRIM(GETDATE())+'.' 
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Stored Procedure dbo.p_StockLst_Process_ins'
			
	EXEC dbo.p_eMail_Send
		 @FromEmail = @cEmailFrom, 
		 @ToEmail = 'David.Kirchner@ERP_1s.com', 
		 @SubjectEmail = 'PartSelect.',
		 @BodyEmail = @Body,
		 @BodyType = 'TEXT'		

	end

