--SELECT top 10 * FROM dbo.StockLst_Process ORDER BY ID_Detail_Process DESC
--
--GRANT EXECUTE ON [dbo].[p_StockLst_Process_ins7] TO [WINDFALL\HPA]

INSERT INTO dbo.StockLst_Process_Grab WITH (ROWLOCK)  
	(
	[SOitem]
      ,[PO_item]
      ,[SalesPerson]
      ,[StartDate]
      ,[DueDate]
      ,[Comment]
      ,[Process_ID]
      ,[Processor]
      ,[AllowSub]
      ,[PWeight]
      ,[PU]
      ,[QTY]
      ,[S_P]
	  ,[Ordered_QTY]
      ,[Ordered_P]
      ,[Pounds]
	  ,[ID_Master]
      ,[ID_Detail]
      ,[ID_Detail_Process]
      ,[ReceivingID]
      ,[WO]
      ,[WO_Detail]
      ,[InqNumP]
      ,[Prc_Form]
      ,[Prc_PCs]
      ,[Prc_Dim1]
      ,[Prc_Dim2]
      ,[Prc_Dim3]
      ,[Descript]
      ,[FoundStk]
	  )
    SELECT TOP 1
	SP.[SOitem]
      ,SP.[PO_item]
      ,SP.[SalesPerson]
      ,SP.[StartDate]
      ,SP.[DueDate]
      ,SP.[Comment]
      ,SP.[Process_ID]
      ,SP.[Processor]
      ,SP.[AllowSub]
      ,SP.[PWeight]
      ,SP.[PU]
      ,SP.[QTY]
	  ,SD.[S_P]
      ,SP.[Ordered_QTY]
      ,SP.[Ordered_P]
      ,SP.[Pounds]
	  ,SD.[ID]
      ,SP.[ID_Detail]
      ,SP.[ID_Detail_Process]
      ,SD.[ReceivingID]
      ,SP.[WO]
      ,SP.[WO_Detail]
      ,SP.[InqNumP]
      ,SP.[Prc_Form]
      ,SP.[Prc_PCs]
      ,SP.[Prc_Dim1]
      ,SP.[Prc_Dim2]
      ,SP.[Prc_Dim3]
	  ,dbo.f_DescriptCL(SM.Alloy,SM.CC,SM.CL,SM.Form,SP.[Prc_Dim1],SP.[Prc_Dim2],SP.[Prc_Dim3],SP.[PWeight],SD.RandLen) AS Descript 
      ,SP.[FoundStk]
--	  ,GETDATE()
	  FROM dbo.StockLst_Process SP
	  INNER JOIN dbo.StockLst_Detail SD WITH(NOLOCK) ON SP.ID_Detail= SD.ID_Detail
	  inner join dbo.StockLst_Master SM WITH(NOLOCK) ON SD.ID = SM.ID
	  WHERE ID_Detail_Process = @ID_Detail_Process
	  



