ALTER   PROCEDURE [dbo].[p_StockLst_Process_ins7-Del]
	@ID_Detail	int,
	@SalesPerson	varchar(20),
	@StartDate	datetime,
	@DueDate	datetime,
	@AllowSub	char(1),
	@PU			TINYINT,
	@QTY		MONEY,
	@Pounds		DECIMAL(9,1),
	@SOitem		char(10),
	@PO_Item	CHAR(12),
	@WO			INT,
	@Process_ID	char(10),
	@Processor	varchar(20),
	@Comment	varchar(100),
	@ReceivingID INT,
	@Prc_QTY	MONEY
AS

  Set NoCount On

--Process_ID = SELECTED,INCOMING,PARTRECV,RECEIVED,SHIPPED,CORRECTED,SUBED
--'CANCELLED,CORRECTION,Receiving,PartSelect,Sell Stock'
--
--EXEC dbo.p_StockLst_Process_ins7  @ID_Detail = 0,@SalesPerson = 'Wayne Roe',@StartDate = '07/11/18 12:03:34 PM',@DueDate = '',@AllowSub = 'Y',@PU=0,@QTY = 0, @Pounds=0,@SOitem = ' 104432-01',@PO_Item = '',@WO=0,@Process_ID = 'PARTSELECT',@Processor = 'Partial SELECT Process',@Comment = 'Selected Stock was used, but more stock is needed to finish.',@ReceivingID=0 , @Prc_QTY=0
--SELECT top 10 * FROM dbo.StockLst_Process ORDER BY ID_Detail_Process DESC
--
--GRANT EXECUTE ON [dbo].[p_StockLst_Process_ins7] TO [WINDFALL\HPA]

SET @SOitem = dbo.ProperSO( @SOitem )
SET @PO_item = dbo.ProperPO( @PO_item )

INSERT INTO dbo.StockLst_Process WITH (ROWLOCK)  (
	ID_Detail,
	SalesPerson,
	StartDate,
	DueDate,
	AllowSub,
	PU,
	QTY,
	Pounds,
	SOitem,
	PO_item,
	Process_ID,
	Processor,
	Comment,
	ReceivingID,
	WO,
	Prc_QTY)
    Values (
	@ID_Detail,
	@SalesPerson,
	@StartDate,
	@DueDate,
	@AllowSub,
	@PU,
	@QTY,
	@Pounds,
	@SOitem,
	@PO_item,
	@Process_ID,
	@Processor,
	@Comment,
	@ReceivingID,
	@WO,
	@Prc_QTY)

 
 DECLARE @ID_Detail_Process INT
 SET @ID_Detail_Process = SCOPE_IDENTITY()



 IF @Process_ID = 'PartSelect'
	begin
	
	PRINT '  Build Email for PartSelect'

	DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
	DECLARE @Body varchar(8000)
	SET @Body = ' Stored Procedure dbo.p_StockLst_Process_ins7 '

	DECLARE @SalesNum INT = 0
	--SET @SalesNum = CAST( LEFT(@SOitem,7) AS INT)
	SET @SalesNum =dbo.f_ProperSO(@SOitem)

	DECLARE @PurchaseOrder INT = 0
	--SET @PurchaseOrder = CAST( LEFT(@PO_item,9) AS INT)
	SET @PurchaseOrder = dbo.f_ProperPO(@PO_item)

	SET @Body = @Body + CHAR(13)+CHAR(10) + '   SOitem: '+ISNULL(@SOitem,'') +' '+ dbo.f_get_Order_Description('SOitem',0,@SOitem)+ '  '

	IF @SalesNum > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) +'"'+ dbo.f_Reportlink_CHAR('SOitem',@SOitem) +'"'

	SET @Body = @Body + CHAR(13)+CHAR(10) + '  PO_item: '+ISNULL(@PO_item,'') +' '+ dbo.f_get_Order_Description('POitem',0,@PO_Item)+'  '
	
	IF @PurchaseOrder > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) +'"'+ dbo.f_Reportlink_CHAR('POitem',@PO_item) +'"'

	SET @Body = @Body + CHAR(13)+CHAR(10) + ' SalesPerson: '+ISNULL(@SalesPerson,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '   StartDate: '+CAST(ISNULL(@StartDate,'') AS CHAR(30) )

	IF CAST(ISNULL(@duedate,'') AS CHAR(30) ) = 'Jan  1 1900 12:00AM           '
		SET @Body = @Body + CHAR(13)+CHAR(10) + '   DueDate : '
	ELSE
		SET @Body = @Body + CHAR(13)+CHAR(10) + '   DueDate : '+CAST(ISNULL(@duedate,'') AS CHAR(30) )

	SET @Body = @Body + CHAR(13)+CHAR(10) + '   Comment  : '+ISNULL(@comment,'')
	SET @Body = @Body + CHAR(13)+CHAR(10) + '  Process_ID: '+ISNULL(@process_id,'') + '  Processor:'+ISNULL(@processor,'') 
	SET @Body = @Body + CHAR(13)+CHAR(10) + '   AllowSub : '+ISNULL(@AllowSub,'')

--depricated
--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@pWeight:'+RTRIM(STR(ISNULL(@pWeight,0)))
--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@pPc:'+RTRIM(STR(ISNULL(@pPc,0)))
--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@pFt:'

	IF @PU > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '         PU: '+CAST(ISNULL(@PU,0) AS CHAR(1))
	IF @QTY > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '        QTY: '+RTRIM(STR(@QTY,18,4))

	IF @Pounds > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '      Pounds: '+RTRIM(STR(@Pounds,9,1))

	IF @ID_Detail < 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '   ID_Detail: '+CAST(ISNULL(@ID_Detail,0) AS CHAR(10) )

	IF @ReceivingID > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + ' ReceivingID: '+CAST(ISNULL(@ReceivingID,0) AS CHAR(10))

	IF @WO > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '          WO: '+CAST(ISNULL(@WO,0) AS CHAR(10))  +' '+ dbo.f_get_Order_Description('WO',@WO,'')

	IF @WO > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) +'"'+ dbo.f_HTML_link_WO(@WO)+'"'

--	SET @Body = @Body + CHAR(13)+CHAR(10) + '@WO_Detail:'+CAST(ISNULL(@WO_Detail,0) AS CHAR(10)) +' '+ dbo.f_get_Order_Description('WO_Detail',@WO_Detail,'')

	IF @Prc_QTY > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + '     Prc_QTY: '+RTRIM(STR(@Prc_QTY,18,4))

	IF @ID_Detail_Process > 0
		SET @Body = @Body + CHAR(13)+CHAR(10) + 'ID_Detail_Process: '+RTRIM(STR(@ID_Detail_Process))

	SET @Body = @Body + CHAR(13)+CHAR(10) + ''					
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Entered by '+RTRIM(suser_sname())+' on '+RTRIM(GETDATE())+'.' 
	SET @Body = @Body + CHAR(13)+CHAR(10) + 'Stored Procedure dbo.p_StockLst_Process_ins7 on '+@@SERVERNAME
			
	EXEC dbo.p_eMail_Send
		 @FromEmail = @cEmailFrom, 
		 @ToEmail = 'David.Kirchner@ERP_1s.com', 
		 @SubjectEmail = 'Partial Select.',
		 @BodyEmail = @Body,
		 @BodyType = 'TEXT'		

	end

  ------------------

  SELECT @ID_Detail_Process
