-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 03/20/2020
-- Description:	Updates Sales_Hold_Status table to remove hold
-- Updates:
-- 09/30/2022 - Fixed issue causing SO Item holds to not work
-- =============================================
ALTER PROCEDURE [dbo].[p_Update_Sales_Hold_Status] 
	-- Add the parameters for the stored procedure here
	@SOitem char(10),
	@Hold_Type char(10),
	@Who varchar(255),
	@Comment varchar(255)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE 
		-- Sales_Hold_Status Values we care about
		@SalesNum int = -1,
		@Hold_Value bit = 0,
		@InsertedId int = 0

	-- Get first/latest matching entry for the SOitem
	SELECT TOP(1)
		@SalesNum = [SalesNum],
		@Hold_Value = [Hold_Value]
    FROM dbo.Sales_Hold_Status WITH(NOLOCK)
    WHERE SOitem = dbo.f_ProperSOitem(@SOitem)
		AND Hold_Type = @Hold_Type -- THIS IS ***IMPORTANT***, DO NOT CHANGE THIS
    ORDER BY [WHEN] desc

	IF (@SalesNum > 0 AND @Hold_Value = 1) -- Only continue if a row was found AND order is on hold
	BEGIN
		-- Insert new row into Sales_Hold_Status
		INSERT INTO [dbo].[Sales_Hold_Status] 
		(
			[SOitem]
			,[SalesNum]
			,[Hold_Type]
			,[Hold_Value]
			,[Who]
			,[What]
			,[Comment]
		)
		VALUES 
		(
			@SOitem,
			@SalesNum,
			@Hold_Type,
			0,
			@Who,
			LTRIM(RTRIM(@Hold_Type)) + ' OFF Hold',
			LTRIM(RTRIM(@Comment))
			--LTRIM(RTRIM(@Comment)) + ' Order Off ' + LTRIM(RTRIM(@Hold_Type)) + ' Hold'
		)
		
		set @InsertedId = SCOPE_IDENTITY();

		-- update sales table 
		-- DONE IN Sales_Hold_Status_Insert trgger
		-- exec dbo.p_Set_Sales_Hold_Status @cSOitem = @SOitem

		SELECT * FROM [dbo].[Sales_Hold_Status] WHERE ID = @InsertedId
	END
END

