-- =============================================
-- Author:		Sean Lykins
-- Create date: 2015 4 2
-- Description:	The primary data table intended so that all of the VPR elements should query off of
-- =============================================
ALTER PROCEDURE [dbo].[p_Vendor_Performance_Report_DataTable] 
	-- Add the parameters for the stored procedure here
	@datemin datetime
	,@datemin2 datetime
	,@datemax datetime
	,@vendcode int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
set datefirst 1
SELECT V.company
	, PO.poitem
	,ISNULL(R.RejectPC,0) AS 'Pieces Rejected'
	,CONVERT(int,ISNULL(r.Pass,0)) AS 'Acceptable Documentation'
	,CASE WHEN r.Received IS NULL THEN 0 ELSE 1 END AS 'Number of Documentation'
	,CASE WHEN ISNULL(r.pieces,0) = 0 THEN CASE WHEN ISNULL(r.poitem,'') != '' THEN 1 ELSE 0 END ELSE ISNULL(r.pieces,0) END AS 'Total Pieces'
	, 'Qty of PO Items Late' = CASE WHEN ISNULL((po.HPA_Due_Max),CONVERT(Datetime,'1900-01-01 00:00:00.000')) < ISNULL(r.received,GETDATE()) THEN 1 ELSE 0 END
	,'AvgDaysLate' = ERP_2.dbo.f_CalculateDaysLate(HPA_Due_Max,ISNULL(r.received,GETDATE()))
	,CASE WHEN r.Received IS NULL THEN 1 ELSE 1 END AS 'Total PO Items'
	,r.received as received
	,HPA_Due_Max AS HPA_Due_Max
	,Due_Max AS Due_Max
	,V.VendCode
	,YEAR(po.HPA_Due_Max) AS Year
	,MONTH(po.HPA_Due_Max) AS Month
FROM dbo.Vendor AS v
	LEFT OUTER JOIN dbo.PurchaseOrder PO ON V.vendcode = PO.VendCode
	LEFT OUTER JOIN dbo.Receiving R ON PO.poitem = R.poitem
WHERE ISNULL(PO.cancelled,0) = 0 AND (dbo.f_IsVendorAppr(v.VendCode) = 1 OR dbo.f_IsVendorAppr(v.VendCode) = 2)
	AND ISNULL(po.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) >= @datemin
	AND ISNULL(po.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) <= @datemax
	 AND v.VendCode = @vendcode
	 AND NOT (r.Received IS NULL AND HPA_Due_Max + 1 > GETDATE())
ORDER BY V.company, po.Due_Max
END
GO
