ALTER PROCEDURE [dbo].[p_Warn_Stk_Deleted]
(
@nID_Detail_Process INT
,@cTBL CHAR(1)
,@nID_Detail INT 
,@SOitemWin	VARCHAR(50)
,@WO INT
)
AS
--EXEC p_Warn_Stk_Deleted 69580,'S',18542, ''

SET NOCOUNT ON
DECLARE @err INT = 0,
        @RC INT = 0

--Test Parameters
IF @nID_Detail_Process < 1
	SET @err = 1;

IF NOT ( @cTBL = 'S' or @cTBL = 'B' or @cTBL = 'W' )
	SET @err = 2;

IF @nID_Detail < 0
	SET @err = 3;

IF @err > 0
	RETURN @err;

SET @WO = ISNULL(@WO,0)

--End Test

DECLARE @SalesPerson VarChar(20)
	,@SOitem Char(10)
	,@PO_item Char(12)
	,@Comment VarChar(100)
	,@Process_ID Char(10)
	,@Alloy VARCHAR(12)

IF @cTBL = 'S'
	SELECT @SalesPerson=ISNULL(P.SalesPerson,'')
		,@SOitem=ISNULL(P.SOitem,'')
		,@PO_item=ISNULL(P.PO_item,'')
		,@Comment=ISNULL(P.Comment,'')
		,@Process_ID=ISNULL(P.Process_ID,'No Process') 
		,@Alloy = ISNULL(M.Alloy,'No Alloy')
		FROM dbo.StockLst_Process P
		INNER JOIN dbo.StockLst_Detail D ON P.ID_Detail = D.ID_Detail
		INNER JOIN dbo.StockLst_Master M ON D.ID = M.ID
		WHERE ID_Detail_Process = @nID_Detail_Process
	
IF @cTBL = 'B'
	SELECT @SalesPerson=ISNULL(P.SalesPerson,'')
		,@SOitem=ISNULL(P.SOitem,'')
		,@PO_item=ISNULL(P.PO_item,'')
		,@Comment=ISNULL(P.Comment,'')
		,@Process_ID=ISNULL(P.Process_ID,'No Process') 
		,@Alloy = ISNULL(M.Alloy,'No Alloy')
		FROM dbo.BrokerLst_Process P
		INNER JOIN dbo.BrokerLst_Detail D ON P.ID_Detail = D.ID_Detail
		INNER JOIN dbo.BrokerLst_Master M ON D.ID = M.ID
		WHERE ID_Detail_Process = @nID_Detail_Process

IF @cTBL = 'W'
		SELECT @SalesPerson=ISNULL(P.SalesPerson,'')
		,@SOitem=ISNULL(P.SOitem,'')
		,@PO_item=ISNULL(P.PO_item,'')
		,@Comment=ISNULL(P.Comment,'')
		,@Process_ID=ISNULL(P.Process_ID,'No Process') 
		,@Alloy = ISNULL(M.Alloy,'No Alloy')
		FROM dbo.WIPLst_Process P
		INNER JOIN dbo.WIPLst_Detail D ON P.ID_Detail = D.ID_Detail
		INNER JOIN dbo.WIPLst_Master M ON D.ID = M.ID
		WHERE ID_Detail_Process = @nID_Detail_Process

IF @@ROWCOUNT > 0
begin
	DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
	DECLARE @Body VarChar(8000)

	SET @Body = dbo.f_HTML_HPA_Header()
--	PRINT dbo.f_HTML_HPA_Header()
		
	SET @Body = @Body + 'The Selected Stock is gone.<br />'
	SET @Body = @Body + 'Sales Person: '+@SalesPerson+'<br />'
	IF LEN(@SOitem) > 0
		begin
		SET @Body = @Body + dbo.f_HTML_link_SOitem(@SOitem)+' -stock is gone.</a><br />'
		end
	IF LEN(@SOitemWin) > 0
		begin
		SET @Body = @Body + dbo.f_HTML_link_SOitem(@SOitemWin)+' -used the metal.</a><br />'
		end	
	IF LEN(@PO_item)>0 AND @PO_item <> '0-00'
		begin
		SET @Body = @Body + dbo.f_HTML_link_SOitem(@PO_item)+' -PO.</a><br />'
		end
	IF @WO >0 
		begin
		SET @Body = @Body + dbo.f_HTML_link_WO(@WO)+' -Work Order</a><br />'
		end

	SET @Body = @Body + 'Comment: '+RTRIM(@Alloy)+' '+RTRIM(@Comment)+'<br />'
	SET @Body = @Body + 'Process_ID: '+@Process_ID+'<br />'
	SET @Body = @Body + 'ID_Detail: '+STR(@nID_Detail)+'<br />'
	SET @Body = @Body + 'ID_Detail_Process: '+STR(@nID_Detail_Process)+'<br />'
	SET @Body = @Body + 'TRIGGER dbo.?Lst_Detail_Delete:  EXEC p_Warn_Stk_Deleted  <br />'
	SET @Body = @Body + RTRIM(suser_sname())+'<br />'
	SET @Body = @Body + '<br />'
	
	SET @Body = @Body + dbo.f_HTML_HPA_Footer(0)
--	PRINT  dbo.f_HTML_HPA_Footer(0)	

	EXEC dbo.p_eMail_Send
			 @FromEmail = @cEmailFrom, 
			 @ToEmail = 'Admin.Alerts@ERP_1s.com', 
			 @SubjectEmail = 'Warn SalesPerson of deleted STK Detail.',
			 @BodyEmail = @Body,
			 @BodyType = 'HTML'		
end

RETURN

--GRANT EXECUTE ON [dbo].[p_Warn_Stk_Deleted] TO [WINDFALL\HPA] AS [dbo];
GO
