AS
--EXEC p_WarnStockGone 69580, 18542, ''

SET NOCOUNT ON
DECLARE @err INT,
        @RC INT
	
SET @err = 0
SET @RC = 0

DECLARE @SalesPerson VarChar(20)
	,@SOitem Char(10)
	,@PO_item Char(12)
	,@Comment VarChar(100)
	,@Process_ID Char(10)
DECLARE @Alloy VARCHAR(12)

SELECT @SalesPerson=ISNULL(StockLst_Process.SalesPerson,'')
	,@SOitem=ISNULL(StockLst_Process.SOitem,'')
	,@PO_item=ISNULL(StockLst_Process.PO_item,'')
	,@Comment=ISNULL(StockLst_Process.Comment,'')
	,@Process_ID=ISNULL(StockLst_Process.Process_ID,'No Process') 
	,@Alloy = ISNULL(SM.Alloy,'No Alloy')
	FROM dbo.StockLst_Process 
	INNER JOIN dbo.StockLst_Detail SD ON SD.ID_Detail = StockLst_Process.ID_Detail
	INNER JOIN dbo.StockLst_Master SM ON SM.ID = SD.ID
	WHERE ID_Detail_Process = @nID_Detail_Process
	
IF @@ROWCOUNT > 0
begin
	DECLARE @cEmailFrom VARCHAR(30) = ERP_2.dbo.f_GetSQL_Server_Email()
	DECLARE @cToEmail VARCHAR(30) = ERP_2.dbo.f_Get_Email_Profile_Name(@SalesPerson)
	DECLARE @Body VarChar(8000)

	SET @Body = dbo.f_HTML_HPA_Header()
--	PRINT dbo.f_HTML_HPA_Header()
		
	SET @Body = @Body + 'The Selected Stock is gone.<br />'
	SET @Body = @Body + 'Sales Person: '+@SalesPerson+'<br />'
	IF LEN(@SOitem) > 0
		begin
		SET @Body = @Body + dbo.f_HTML_link_SOitem(@SOitem)+' -stock is gone.</a><br />'
		end
	IF LEN(@SOitemWin) > 0
		begin
		SET @Body = @Body + dbo.f_HTML_link_SOitem(@SOitemWin)+' -used the metal.</a><br />'
		end	
	IF LEN(@PO_item)>0 AND @PO_item <> '0-00'
		begin
		SET @Body = @Body + dbo.f_HTML_link_POitem(@PO_item)+'</a><br />'
		end

	SET @Body = @Body + 'Comment: '+RTRIM(@Alloy)+' '+RTRIM(@Comment)+'<br />'
	SET @Body = @Body + 'Process_ID: '+@Process_ID+'<br />'
	SET @Body = @Body + 'ID_Detail: '+STR(@nID_Detail)+'<br />'
	SET @Body = @Body + 'ID_Detail_Process: '+STR(@nID_Detail_Process)+'<br />'
	SET @Body = @Body + 'TRIGGER dbo.StockLst_Detail_Delete:  EXEC p_WarnStockGone  <br />'
	SET @Body = @Body + RTRIM(suser_sname())+'<br />'
	SET @Body = @Body + '<br />'
	
	SET @Body = @Body + dbo.f_HTML_HPA_Footer(0)
--	PRINT  dbo.f_HTML_HPA_Footer(0)	

	
	--EXEC dbo.p_eMail_Send  @cEmailFrom, 'Admin@ERP_1s.com', 'Warn SalesPerson of deleted stock.', @Body, @BodyType ='HTML'
	EXEC dbo.p_eMail_Send
		 @FromEmail = @cEmailFrom, 
		 @ToEmail = @cToEmail,
		 @SubjectEmail = 'Warn SalesPerson of deleted stock.',
		 @BodyEmail = @Body,
		 @BodyType = 'HTML'	
end

RETURN

